import { load } from 'cheerio';
import { createHash, randomUUID } from 'node:crypto';
import { put } from '@vercel/blob';
const assets = {"/app.js":"const previousSections = {\n  '#costos': '/calculadora/', '#perfiles': '/perfiles/', '#materiales': '/perfiles/#materiales',\n  '#tecnicas': '/guias/', '#diagnostico': '/guias/#diagnostico', '#impresoras': '/perfiles/#impresoras',\n  '#privacidad': '/herramientas/#privacidad', '#acerca': '/herramientas/#acerca'\n};\nconst previousSection = previousSections[location.hash];\nif (previousSection) location.replace(previousSection);\n\nconst models = [\n  ['Flexi Turtle', 'Cults3D', 'gratis', ['STL'], 'https://cults3d.com/en/3d-model/gadget/flexi-turtle', 'Tortuga articulada · Juguetes'],\n  ['Gridfinity Baseplate Lite', 'Printables', 'gratis', ['STL'], 'https://www.printables.com/model/478930-gridfinity-baseplate-quick-print-lite-version-less', 'Base modular · Organización'],\n  ['Maceta Arquitectónica Clásica', 'Cults3D', 'pago', ['STL'], 'https://cults3d.com/es/modelo-3d/casa/maceta-arquitectonica-clasica-stl', 'Maceta con columnas · Decoración'],\n  ['Soporte para pinzas Honeycomb', 'Printables', 'gratis', ['3MF'], 'https://www.printables.com/model/597461-honeycomb-storage-wall-hcw-tweezers-holder/files', 'Panel de herramientas · Taller'],\n  ['Chocolate Truffle Dragon Clicker', 'Cults3D', 'pago', ['STL'], 'https://cults3d.com/en/3d-model/game/chocolate-truffle-dragon-clicker', 'Dragón clicker · Juguetes'],\n  ['3DBenchy', 'Thingiverse', 'gratis', ['STL'], 'https://www.thingiverse.com/thing:763622', 'Barco de calibración · Pruebas de impresión'],\n  ['Ajedrez clásico', 'Cults3D', 'gratis', ['STL', '3MF', 'OBJ'], 'https://cults3d.com/en/3d-model/game/classic-chess-set-printable-3d-print-model', 'Piezas de ajedrez · Chess set'],\n  ['Maceta con autorriego', 'Shapekit', 'gratis', ['STL'], 'https://shapekit.cc/self-watering-planter', 'Maceta con depósito · Self-watering planter'],\n  ['Cable Clip', 'Printables', 'gratis', ['STL'], 'https://www.printables.com/model/35858-cable-clip', 'Sujetacables · Organización'],\n  ['Llavero Perú', 'Cults3D', 'gratis', ['STL'], 'https://cults3d.com/es/modelo-3d/joyas/llavero-peru-3dmini3d', 'Llavero · Keychain'],\n  ['Soporte Gridfinity para 3DBenchy', 'Printables', 'gratis', ['STL'], 'https://www.printables.com/model/369592-gridfinity-3d-benchy-stand', 'Soporte para barco · Organización']\n];\n\nconst repositories = [\n  ['MakerWorld', 'makerworld.com'], ['Printables', 'printables.com'], ['Thingiverse', 'thingiverse.com'],\n  ['Cults3D', 'cults3d.com'], ['MyMiniFactory', 'myminifactory.com'], ['Thangs', 'thangs.com'],\n  ['Creality Cloud', 'crealitycloud.com'], ['Pinshape', 'pinshape.com'], ['Yeggi', 'yeggi.com'],\n  ['STLFinder', 'stlfinder.com'], ['Shapekit', 'shapekit.cc']\n];\n\nconst q = document.querySelector('#q');\nconst format = document.querySelector('#format');\nconst source = document.querySelector('#source');\nconst modelList = document.querySelector('#models');\nconst directory = document.querySelector('#directories');\nconst count = document.querySelector('#count');\nconst search = document.querySelector('#search');\nconst normalize = value => value.normalize('NFD').replace(/\\p{Diacritic}/gu, '').toLowerCase().trim();\nconst synonyms = { maceta: 'planter', dragon: 'dragon', llavero: 'keychain', tortuga: 'turtle', ajedrez: 'chess', soporte: 'holder', gratis: 'gratis', free: 'gratis', paid: 'pago', m3f: '3mf' };\n\nconst translatedTerms = {\"porta celular\": \"phone stand\", \"portacelular\": \"phone stand\", \"soporte para celular\": \"phone stand\", \"soporte celular\": \"phone stand\", \"soporte para telefono\": \"phone stand\", \"soporte de celular\": \"phone stand\", \"organizador de cajon\": \"drawer organizer\", \"repuesto\": \"replacement\", \"juguete\": \"toy\", \"juguetes\": \"toys\", \"decoracion\": \"decor\", \"florero\": \"vase\", \"figura\": \"figurine\", \"miniatura\": \"miniature\", \"articulado\": \"articulated\", \"soportes\": \"holders\", \"macetas\": \"planters\", \"llaveros\": \"keychains\"};\nfunction translate(term) {\n  const normalized=normalize(term);\n  return translatedTerms[normalized] ?? normalized.split(/\\s+/).map(word=>synonyms[word] ?? translatedTerms[word] ?? word).join(\" \");\n}\n\nfor (const name of [...new Set(models.map(model => model[1]))].sort()) {\n  source.add(new Option(name, name));\n}\n\nfunction externalSearch(domain, query, extension, price) {\n  if (!query && !extension && !price) return 'https://' + domain;\n  const priceTerms = { gratis: '(free OR gratis)', pago: '(paid OR purchase OR comprar)' };\n  const terms = ['site:' + domain, query, extension, priceTerms[price]].filter(Boolean);\n  return 'https://www.google.com/search?' + new URLSearchParams({ q: terms.join(' ') });\n}\n\nconst liveStatus = document.querySelector('#live-status');\nlet liveResults = [];\nlet activeRequest;\nlet waiting = false;\nlet topMode = false;\nlet page = 1;\nlet pageStart = [1];\nconst queryParams=new URLSearchParams(location.search);\nq.value=(queryParams.get(\"q\") ?? \"\").slice(0,100);\nlet searchExhausted = false;\nlet hasNext = false;\nconst licenseFilter = document.querySelector('#license');\nconst favoritesOnly = document.querySelector('#favorites-only');\nlet favorites = [];\ntry { const saved=JSON.parse(localStorage.getItem('utilitools-favorites') || '[]'); if(Array.isArray(saved)) favorites=saved.filter(x=>x && typeof x.url==='string' && x.url.startsWith('https://') && Array.isArray(x.formats)); } catch {}\nfunction saveFavorite(model) {\n  const exists=favorites.some(x=>x.url===model.url);\n  if(!exists) window.utilitoolsTrack?.(\"model_saved\");\n  favorites=exists?favorites.filter(x=>x.url!==model.url):[...favorites,model];\n  try { localStorage.setItem('utilitools-favorites',JSON.stringify(favorites)); document.querySelector('#saved-status').textContent=exists?'Modelo quitado de favoritos.':'Modelo guardado en este navegador.'; }\n  catch { document.querySelector('#saved-status').textContent='El navegador no permite guardar favoritos. Se conservarán durante esta sesión.'; }\n  render();\n}\n\nconst licenseBadges = { commercial: 'Uso comercial', personal: 'No comercial', unknown: 'Licencia a revisar' };\n\nfunction card(model) {\n  const article = document.createElement('article');\n  article.className = 'card';\n  const media = document.createElement('a');\n  media.className = 'card-media open-model'; media.href = model.url; media.target = '_blank'; media.rel = 'noopener noreferrer';\n  media.setAttribute('aria-label', 'Ver ' + model.title + ' en ' + model.repo);\n  const placeholder = document.createElement('span');\n  placeholder.className = 'card-placeholder'; placeholder.textContent = model.image ? 'Cargando vista previa…' : 'Sin vista previa · ver en la fuente ↗';\n  media.append(placeholder);\n  if (model.image) {\n    const image = document.createElement('img');\n    image.alt = ''; image.loading = 'lazy'; image.decoding = 'async'; image.referrerPolicy = 'no-referrer';\n    image.width = 640; image.height = 480;\n    image.addEventListener('load', () => { image.classList.add('ready'); placeholder.hidden = true; });\n    image.addEventListener('error', () => { image.remove(); placeholder.textContent = 'Sin vista previa · ver en la fuente ↗'; });\n    let previewUrl = model.image;\n    if (previewUrl.startsWith('https://media.printables.com/') && !previewUrl.includes('/thumbs/')) {\n      previewUrl = previewUrl.replace(/\\/([^/]+)\\.(jpg|jpeg|png|webp)$/i, (_, name, ext) => '/thumbs/inside/640x480/' + ext.toLowerCase() + '/' + name + '.webp');\n    }\n    image.src = previewUrl;\n    media.append(image);\n  }\n  const selected = favorites.some(x => x.url === model.url);\n  const favorite = document.createElement('button');\n  favorite.type = 'button'; favorite.className = 'fav' + (selected ? ' on' : '');\n  favorite.textContent = selected ? '♥' : '♡';\n  favorite.setAttribute('aria-pressed', String(selected));\n  favorite.setAttribute('aria-label', (selected ? 'Quitar de favoritos ' : 'Guardar en favoritos ') + model.title);\n  favorite.title = selected ? 'Quitar de favoritos' : 'Guardar en favoritos';\n  favorite.addEventListener('click', () => saveFavorite(model));\n\n  const details = document.createElement('div');\n  details.className = 'details';\n  const top = document.createElement('div'); top.className = 'card-top';\n  const repo = document.createElement('span'); repo.textContent = model.repo;\n  const badge = document.createElement('span'); badge.className = 'price ' + model.type; badge.textContent = model.type === 'gratis' ? 'GRATIS' : 'PAGO';\n  top.append(repo, badge);\n  const title = document.createElement('h3'); title.textContent = model.title;\n  details.append(top, title);\n  if (model.keywords) { const p = document.createElement('p'); p.textContent = model.keywords; details.append(p); }\n  if (topMode === 'paid' && model.keywords) {\n    const reason = document.createElement('p');\n    reason.textContent = 'Elegido como ejemplo de ' + (model.title.includes('Maceta') ? 'decoración para el hogar' : 'juguete con mecanismo clicker') + '.';\n    details.append(reason);\n  }\n  const meta = document.createElement('div'); meta.className = 'card-meta';\n  if (Number.isFinite(model.downloads)) { const d = document.createElement('span'); d.className = 'downloads'; d.textContent = new Intl.NumberFormat('es-AR').format(model.downloads) + ' descargas'; meta.append(d); }\n  const status = model.licenseStatus ?? 'unknown';\n  const lic = document.createElement('span'); lic.className = 'lic ' + status; lic.textContent = licenseBadges[status] ?? licenseBadges.unknown;\n  if (model.licenseName) lic.title = model.licenseName;\n  meta.append(lic);\n  const formats = document.createElement('div'); formats.className = 'formats';\n  for (const format of model.formats) { const f = document.createElement('span'); f.textContent = format; formats.append(f); }\n  if (model.formats.length) meta.append(formats);\n  details.append(meta);\n  if (model.note) { const note = document.createElement('p'); note.className = 'model-note'; note.textContent = 'Nota: ' + model.note; details.append(note); }\n\n  const bottom = document.createElement('div'); bottom.className = 'card-bottom';\n  const open = document.createElement('a');\n  open.className = 'open-model'; open.href = model.url; open.target = '_blank'; open.rel = 'noopener noreferrer';\n  open.textContent = 'Ver ficha ↗'; open.setAttribute('aria-label', 'Ver ' + model.title + ' en ' + model.repo);\n  const menu = document.createElement('details'); menu.className = 'more-menu';\n  const summary = document.createElement('summary'); summary.textContent = '⋯'; summary.setAttribute('aria-label', 'Más acciones para ' + model.title); summary.title = 'Más acciones';\n  const actions = document.createElement('div'); actions.className = 'model-actions';\n  const calculator = document.createElement('a');\n  calculator.href = 'https://calculadora.utilitools.com.ar/?' + new URLSearchParams({ modelo: model.title, ficha: model.url }) + '#costos';\n  calculator.textContent = 'Calcular costo';\n  const collect = document.createElement('button'); collect.type = 'button'; collect.textContent = 'Guardar en colección';\n  collect.addEventListener('click', () => { menu.open = false; openCollectionEditor(model); });\n  actions.append(calculator, collect);\n  const collection = activeCollection();\n  if (collection && !sharedView && favoritesOnly.checked) {\n    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = 'Quitar de la colección';\n    remove.addEventListener('click', () => {\n      collection.entries = collection.entries.filter(entry => entry.url !== model.url);\n      saveCollections(); render();\n    });\n    actions.append(remove);\n  }\n  if (model.licenseName) { const ln = document.createElement('p'); ln.className = 'license'; ln.textContent = 'Licencia: ' + model.licenseName; actions.append(ln); }\n  menu.append(summary, actions);\n  bottom.append(open, menu);\n  details.append(bottom);\n  article.append(media, favorite, details);\n  return article;\n}\n\n// Cierra los menús \"⋯\" abiertos al tocar fuera de ellos.\ndocument.addEventListener('click', event => {\n  for (const open of document.querySelectorAll('.more-menu[open]')) if (!open.contains(event.target)) open.open = false;\n});\n\nconst catalog = models.map(([title, repo, type, formats, url, keywords], index) => ({\n  title, repo, type, formats, url, keywords, image: '/api/thumbnail/' + index\n}));\n\nfunction render() {\n  const price = document.querySelector('input[name=p]:checked').value;\n  const words = normalize(q.value).split(/\\s+/).filter(Boolean);\n  const matches = topMode === true || page > 1 ? [] : catalog.filter(model => {\n    const field = normalize([model.title, model.repo, model.type, model.formats.join(' '), model.keywords].join(' '));\n    return words.every(word => field.includes(word) || (synonyms[word] && field.includes(synonyms[word])));\n  });\n  const modelKey = model => model.repo === 'Printables' ? model.url.match(/printables\\.com\\/model\\/(\\d+)/)?.[1] : new URL(model.url).pathname.split('/').at(-1);\n  const ids = new Set(liveResults.map(modelKey));\n  const unique = matches.filter(model => !ids.has(modelKey(model)));\n  const candidates = favoritesOnly.checked ? (activeCollection()?.entries ?? favorites) : [...liveResults, ...unique];\n  const filtered = candidates.filter(model =>\n    (!licenseFilter.value || (model.licenseStatus ?? \"unknown\") === licenseFilter.value) &&\n    (!price || model.type === price) && (!format.value || model.formats.includes(format.value)) &&\n    (!source.value || model.repo === source.value));\n  if(favoritesOnly.checked) page=Math.min(page,Math.max(1,Math.ceil(filtered.length/24)));\n  const displayed=favoritesOnly.checked?filtered.slice((page-1)*24,page*24):filtered;\n  modelList.replaceChildren(...displayed.map(card));\n  document.querySelector('#previous').disabled=page===1 || waiting;\n  document.querySelector('#next').disabled=waiting || (favoritesOnly.checked ? page*24>=filtered.length : !hasNext);\n  document.querySelector('#page-status').textContent='Página '+page;\n\n\n  directory.replaceChildren(...repositories.map(([name, domain]) => {\n    const anchor = document.createElement('a');\n    anchor.href = externalSearch(domain, q.value.trim(), format.value, price);\n    anchor.target = '_blank';\n    anchor.rel = 'noopener noreferrer';\n    anchor.textContent = name;\n    const arrow = document.createElement('span');\n    arrow.setAttribute('aria-hidden', 'true');\n    arrow.textContent = '↗';\n    anchor.append(arrow);\n    return anchor;\n  }));\n\n  count.textContent = filtered.length + (filtered.length === 1 ? ' modelo' : ' modelos');\n  document.querySelector('#empty').hidden = waiting || Boolean(filtered.length);\n}\n\nasync function searchLive() {\n  activeRequest?.abort();\n  const controller = new AbortController();\n  activeRequest = controller;\n  const term = q.value.trim();\n  if(favoritesOnly.checked){waiting=false;liveStatus.hidden=true;render();return;}\n  liveResults = [];\n  hasNext=false;\n  searchExhausted=false;\n  waiting = false;\n  liveStatus.hidden = true;\n  const price = document.querySelector('input[name=p]:checked').value;\n  if (topMode==='paid' || price==='pago' || (source.value && source.value!=='Printables') || (!term && !topMode && !format.value && !licenseFilter.value && !source.value && !price)) {\n    render();\n    return;\n  }\n  waiting = true;\n  liveStatus.textContent = 'Buscando modelos…';\n  liveStatus.hidden = false;\n  render();\n\n  try {\n    const limit = format.value || licenseFilter.value ? 4 : 1;\n    const start = pageStart[page-1] ?? 1;\n    for(let offset=start; offset<start+limit; offset++) {\n      const params=new URLSearchParams({\n        q:translate(term), price, source:source.value,\n        top:topMode===true || !term ? '1' : '', page:String(offset),\n        format:format.value, license:licenseFilter.value\n      });\n      const response=await fetch('/api/search?'+params,{signal:controller.signal});\n      if(!response.ok) throw new Error('Search unavailable');\n      const payload=await response.json();\n      if(activeRequest!==controller) return;\n      if(payload.unavailable.length) throw new Error('Source unavailable');\n      liveResults=payload.models;\n      hasNext=Boolean(payload.hasNext);\n      pageStart[page]=offset+1;\n      if(liveResults.length || !hasNext) break;\n    }\n    searchExhausted=!hasNext && !liveResults.length;\n    window.utilitoolsTrack?.('search_completed',{result:liveResults.length?'found':hasNext?'more':'empty'});\n    liveStatus.hidden=Boolean(liveResults.length) || !hasNext;\n    if(!liveStatus.hidden) liveStatus.textContent='Todavía quedan resultados por revisar. Usá Siguiente para continuar con estos filtros.';\n  } catch {\n    if (activeRequest !== controller) return;\n    window.utilitoolsTrack?.('search_completed',{result:'error'});\n    liveStatus.textContent = 'La búsqueda en línea no respondió. Se muestran las coincidencias del catálogo.';\n  } finally {\n    if (activeRequest === controller) {\n      waiting = false;\n      render();\n    }\n  }\n}\n\nlet debounce;\nfunction runSearch(resetPage=true) {\n  if(resetPage) {page=1;pageStart=[1];}\n  clearTimeout(debounce);\n  searchLive();\n}\nsearch.addEventListener('submit', event => {\n  event.preventDefault();\n  runSearch();\n  document.querySelector('#catalogo').scrollIntoView();\n});\nq.addEventListener('input', () => {\n  clearTimeout(debounce);\n  activeRequest?.abort();\n  activeRequest = null;\n  liveResults = [];\n  waiting = Boolean(q.value.trim());\n  liveStatus.hidden = true;\n  render();\n  topMode=false;page=1;pageStart=[1];searchExhausted=false;\n  debounce = setTimeout(searchLive, 700);\n});\ndocument.querySelector('.filters').addEventListener('change', event=>{\n  if (['format','license','source'].includes(event.target.id) || event.target.name==='p') {\n    window.utilitoolsTrack?.('filter_changed',{format:format.value||'all',license:licenseFilter.value||'all',\n      price:document.querySelector('input[name=p]:checked').value||'all'});\n  }\n  runSearch();\n});\ndocument.querySelector('#reset').addEventListener('click', () => {\n  topMode=false;\n  search.reset();\n  source.value = format.value = licenseFilter.value = '';\n  favoritesOnly.checked=false;\n  sharedView=false; updateCollections('');\n  document.querySelector('input[name=p]').checked = true;\n  runSearch();\n});\ndocument.querySelectorAll('[data-query]').forEach(button => {\n  button.addEventListener('click', () => {\n    topMode=false; favoritesOnly.checked=false;\n    source.value=format.value=licenseFilter.value='';\n    document.querySelector('input[name=p]').checked=true;\n    q.value = button.dataset.query;\n    search.requestSubmit();\n  });\n});\nconst collectionKey = 'utilitools-collections-v1';\nconst collectionSelect = document.querySelector('#collection');\nconst collections = readCollections(localStorageValue(collectionKey));\nconst shared = readCollections(new URLSearchParams(location.hash.slice(1)).get('coleccion'))[0];\nlet sharedView = Boolean(shared);\nif (shared) favoritesOnly.checked = true;\n\nfunction localStorageValue(key) {\n  try { return localStorage.getItem(key); } catch { return null; }\n}\n\nfunction readCollections(raw) {\n  try {\n    const parsed = JSON.parse(raw);\n    if (!Array.isArray(parsed)) return [];\n    return parsed.slice(0,30).filter(item => item && typeof item.name === 'string' && Array.isArray(item.entries)).map(item => ({\n      name: item.name.slice(0,60),\n      entries: item.entries.slice(0,50).filter(entry => entry && typeof entry.title === 'string' &&\n        typeof entry.url === 'string' && /^https:\\/\\/(?:www\\.printables\\.com|cults3d\\.com|www\\.thingiverse\\.com|shapekit\\.cc)\\//.test(entry.url)).map(entry => ({\n        title:entry.title.slice(0,200), url:entry.url, repo:String(entry.repo ?? '').slice(0,50),\n        type:entry.type === 'pago' ? 'pago' : 'gratis',\n        formats:Array.isArray(entry.formats) ? entry.formats.filter(f=>['STL','3MF','OBJ','STEP'].includes(f)) : [],\n        image:typeof entry.image === 'string' && /^(https:\\/\\/(media\\.printables\\.com|images\\.cults3d\\.com)\\/|\\/api\\/thumbnail\\/\\d+$)/.test(entry.image) ? entry.image : '',\n        licenseStatus:['personal','commercial'].includes(entry.licenseStatus) ? entry.licenseStatus : 'unknown',\n        licenseName:String(entry.licenseName ?? '').slice(0,150),\n        note:String(entry.note ?? '').slice(0,300)\n      }))\n    }));\n  } catch { return []; }\n}\n\nfunction saveCollections() {\n  try { localStorage.setItem(collectionKey,JSON.stringify(collections)); return true; }\n  catch { document.querySelector('#collection-status').textContent='El navegador solo permite conservar esta colección durante la sesión.'; return false; }\n}\n\nfunction updateCollections(value=collectionSelect.value) {\n  collectionSelect.replaceChildren(new Option('Todos los favoritos',''));\n  collections.forEach((collection,index)=>collectionSelect.add(new Option(collection.name,String(index))));\n  if(sharedView) collectionSelect.add(new Option(shared.name,'shared'));\n  collectionSelect.value = sharedView ? 'shared' : value === 'shared' ? '' : value;\n  document.querySelector('#share-collection').disabled = !activeCollection();\n  document.querySelector('#delete-collection').disabled = !activeCollection() || sharedView;\n}\n\nfunction activeCollection() {\n  if(sharedView && collectionSelect.value==='shared') return shared;\n  return collectionSelect.value === '' ? null : collections[Number(collectionSelect.value)];\n}\n\nfunction openCollectionEditor(model) {\n  const dialog=document.querySelector('#collection-editor');\n  const select=dialog.querySelector('select');\n  select.replaceChildren(new Option('Crear una colección',''));\n  collections.forEach((collection,index)=>select.add(new Option(collection.name,String(index))));\n  const current=collections.indexOf(activeCollection());\n  if(current>=0) select.value=String(current);\n  const name=dialog.querySelector('[name=name]');\n  const note=dialog.querySelector('[name=note]');\n  const sync=()=>{\n    name.required=select.value==='';\n    name.parentElement.hidden=!name.required;\n    note.value=collections[Number(select.value)]?.entries.find(entry=>entry.url===model.url)?.note ?? '';\n    if(!select.value) note.value='';\n  };\n  name.value=''; sync(); select.onchange=sync;\n  dialog.querySelector('form').onsubmit=event=>{\n    event.preventDefault();\n    if(event.submitter?.value==='cancel') {dialog.close();return;}\n    const label=name.value.trim();\n    let index=select.value === '' ? collections.findIndex(item=>item.name.toLowerCase()===label.toLowerCase()) : Number(select.value);\n    if(index<0) {\n      if(!label || collections.length>=30) {dialog.querySelector('output').textContent='Ingresá un nombre válido. Podés tener hasta 30 colecciones.';return;}\n      index=collections.push({name:label,entries:[]})-1;\n      window.utilitoolsTrack?.('collection_created');\n    }\n    const entries=collections[index].entries;\n    const position=entries.findIndex(entry=>entry.url===model.url);\n    if(position<0 && entries.length>=50) {dialog.querySelector('output').textContent='La colección admite hasta 50 modelos.';return;}\n    const entry={...model,note:note.value.trim()};\n    if(position<0) {entries.push(entry);window.utilitoolsTrack?.('collection_model_saved');} else entries[position]=entry;\n    if(saveCollections()) document.querySelector('#collection-status').textContent='Modelo guardado en '+collections[index].name+'.';\n    dialog.close(); updateCollections(); render();\n  };\n  dialog.querySelector('output').textContent='';\n  dialog.showModal();\n}\n\nupdateCollections();\ncollectionSelect.addEventListener('change',()=>{\n  if(collectionSelect.value!=='shared') sharedView=false;\n  favoritesOnly.checked=true; updateCollections(); runSearch();\n});\ndocument.querySelector('#share-collection').addEventListener('click',()=>{\n  const collection=activeCollection();\n  if(!collection) return;\n  const url=new URL('/',location.origin);\n  url.hash=new URLSearchParams({coleccion:JSON.stringify([collection])}).toString();\n  const dialog=document.querySelector('#collection-share');\n  dialog.querySelector('textarea').value=url.href;\n  dialog.querySelector('output').textContent='';\n  dialog.showModal();\n});\ndocument.querySelector('#copy-collection').addEventListener('click',async()=>{\n  const dialog=document.querySelector('#collection-share');\n  const field=dialog.querySelector('textarea');\n  try {await navigator.clipboard.writeText(field.value);window.utilitoolsTrack?.('collection_link_copied');dialog.querySelector('output').textContent='Enlace copiado.';}\n  catch {field.select();dialog.querySelector('output').textContent='Copiá el enlace seleccionado.';}\n});\ndocument.querySelector('#delete-collection').addEventListener('click',()=>{\n  const index=collections.indexOf(activeCollection());\n  if(index<0 || !confirm('¿Eliminar la colección «'+collections[index].name+'»?')) return;\n  collections.splice(index,1); saveCollections(); updateCollections(''); runSearch();\n});\n\nif(q.value && !sharedView) runSearch(); else render();\nif(sharedView) document.querySelector('#catalogo').scrollIntoView();\n\ndocument.querySelector('#top-paid').addEventListener('click',()=>{\n  topMode='paid';q.value='';source.value='';format.value=licenseFilter.value='';\n  favoritesOnly.checked=false;\n  document.querySelector('input[name=p][value=pago]').checked=true;\n  runSearch(); liveStatus.hidden=false;\n  liveStatus.textContent='Selección editorial de UtiliTools. El ranking de ventas está en Cults3D.';\n  document.querySelector('#catalogo').scrollIntoView();\n});\n\ndocument.querySelector('#top-free').addEventListener('click',()=>{topMode=true;favoritesOnly.checked=false;licenseFilter.value=\"\";q.value='';source.value='Printables';format.value='';document.querySelector('input[name=p][value=gratis]').checked=true;runSearch();document.querySelector('#catalogo').scrollIntoView();});\n\ndocument.querySelector('#previous').addEventListener('click',()=>{if(page>1){page--;runSearch(false);}});\ndocument.querySelector('#next').addEventListener('click',()=>{page++;runSearch(false);});\n","/index.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"description\" content=\"Buscá modelos para imprimir en 3D. Filtrá por formato, precio y repositorio.\"><title>UtiliTools 3D | Buscador de archivos para imprimir</title><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><section class=\"hero\"><div class=\"pattern\" aria-hidden=\"true\"></div><div class=\"hero-content\"><p class=\"eyebrow\">IMPRESIÓN 3D / BUSCADOR</p><h1>Buscá modelos <em>3D</em><br>para imprimir</h1><p>Buscá en Printables, explorá el catálogo de modelos gratis y pagos y abrí la ficha original para descargar.</p><form id=\"search\" role=\"search\"><label class=\"sr\" for=\"q\">Buscar modelos</label><span aria-hidden=\"true\">⌕</span><input type=\"search\" id=\"q\" name=\"q\" maxlength=\"100\" placeholder=\"Probá con maceta, dragón o Gridfinity…\"><button type=\"submit\">Buscar ↗</button></form><div class=\"suggestions\"><span>Probá</span><button data-query=\"maceta\">Maceta</button><button data-query=\"dragón\">Dragón</button><button data-query=\"Gridfinity\">Gridfinity</button><button data-query=\"llavero\">Llavero</button></div><div class=\"categories\" aria-label=\"Categorías de impresión\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></div></section>\n<section id=\"tops\"><div class=\"section-head\"><h2>Tops de modelos</h2></div><div class=\"grid\"><article class=\"card\"><div class=\"details\"><h3>Gratis · destacados por descargas</h3><p>Modelos populares de Printables ordenados por descargas dentro de la selección que devuelve la fuente.</p><button id=\"top-free\" class=\"reset\">Explorar top gratis ↓</button></div></article><article class=\"card\"><div class=\"details\"><h3>Pagos · más vendidos en Cults3D</h3><p>Consultá el ranking oficial de ventas en Cults3D. Esta fuente requiere abrir su sitio para ver el listado actualizado.</p><a href=\"https://cults3d.com/en/creations/best-sellers?sort_column=priced_downloads_count\" target=\"_blank\" rel=\"noopener noreferrer\">Ver top pagos en Cults3D ↗</a><p><button id=\"top-paid\" class=\"reset\">Ver selección paga en UtiliTools ↓</button></p></div></article></div></section><section id=\"catalogo\"><div class=\"section-head\"><div><p class=\"eyebrow\">ARCHIVOS IMPRIMIBLES</p><h2>Catálogo de modelos</h2></div><p id=\"count\" role=\"status\"></p></div><div class=\"filters\"><fieldset id=\"prices\"><legend>Precio</legend><label><input type=\"radio\" name=\"p\" value=\"\" checked><span>Todos</span></label><label><input type=\"radio\" name=\"p\" value=\"gratis\"><span>Gratis</span></label><label><input type=\"radio\" name=\"p\" value=\"pago\"><span>Pagos</span></label></fieldset><label>Formato<select id=\"format\"><option value=\"\">Todos</option><option>STL</option><option>3MF</option><option>OBJ</option><option>STEP</option></select></label><label>Repositorio<select id=\"source\"><option value=\"\">Todos</option></select></label><label>Licencia<select id=\"license\"><option value=\"\">Todas</option><option value=\"commercial\">Permite uso comercial</option><option value=\"personal\">Uso no comercial</option><option value=\"unknown\">Por verificar</option></select></label><label><input type=\"checkbox\" id=\"favorites-only\"> Mis favoritos</label><label>Colección<select id=\"collection\"></select></label><button type=\"button\" class=\"reset\" id=\"reset\">Limpiar filtros</button></div><p id=\"live-status\" class=\"note\" role=\"status\" hidden></p><p class=\"note\" id=\"license-note\">El permiso se interpreta según la licencia informada por la fuente. Revisá la ficha del autor antes de vender impresiones.</p><div class=\"grid\" id=\"models\"></div><div class=\"pagination\"><button id=\"previous\" class=\"reset\">← Anterior</button><span id=\"page-status\" role=\"status\"></span><button id=\"next\" class=\"reset\">Siguiente →</button></div><div class=\"collection-controls\"><button type=\"button\" class=\"reset\" id=\"share-collection\">Compartir colección</button><button type=\"button\" class=\"reset\" id=\"delete-collection\">Eliminar colección</button></div><p id=\"collection-status\" role=\"status\"></p><p id=\"saved-status\" role=\"status\"></p><div id=\"empty\" hidden><h3>Sin coincidencias con estos filtros</h3><p>Probá otra palabra, limpiá los filtros o ampliá la búsqueda en los repositorios de abajo.</p><a href=\"#repositorios\">Buscar en repositorios ↓</a></div></section>\n<section id=\"repositorios\"><div class=\"section-head\"><div><p class=\"eyebrow\">BÚSQUEDA EXTERNA</p><h2>Explorá más repositorios</h2></div></div><p class=\"note\">Abrí la búsqueda en la web. El término, el formato y la preferencia de precio se incluyen como palabras clave. Verificá el precio, el formato y la licencia en cada ficha.</p><div class=\"directories\" id=\"directories\"></div></section><section id=\"elegir\"><div class=\"section-head\"><h2>Cómo elegir un archivo para imprimir</h2></div><div class=\"grid\"><article class=\"card\"><div class=\"details\"><h3>Elegí el formato</h3><p>Un STL contiene la geometría. Un 3MF puede incluir datos adicionales como colores o un perfil de laminado. Al abrir un 3MF, revisá la impresora, la boquilla y el material seleccionados.</p></div></article><article class=\"card\"><div class=\"details\"><h3>Revisá la licencia</h3><p>El precio del archivo y los permisos son distintos. Si pensás vender la pieza impresa, consultá si la ficha del autor autoriza ese uso.</p></div></article><article class=\"card\"><div class=\"details\"><h3>Calculá el costo antes de imprimir</h3><p>Tomá los gramos y el tiempo del laminador. Sumá purga, electricidad y terminación para comparar modelos o cotizar un lote.</p><a href=\"/calculadora/\">Abrir calculadora en pesos →</a></div></article></div></section><dialog id=\"collection-editor\"><form><h2>Guardar en colección</h2><label>Colección<select></select></label><label>Nombre<input name=\"name\" maxlength=\"60\"></label><label>Nota<textarea name=\"note\" maxlength=\"300\"></textarea></label><div><button class=\"reset\" type=\"submit\" value=\"cancel\" formnovalidate>Cancelar</button> <button class=\"reset\" type=\"submit\">Guardar</button></div><output role=\"status\"></output></form></dialog><dialog id=\"collection-share\"><form method=\"dialog\"><h2>Compartir colección</h2><p>El enlace incluye los modelos y las notas de esta versión de la colección.</p><label>Enlace<textarea readonly></textarea></label><div><button class=\"reset\" type=\"button\" id=\"copy-collection\">Copiar enlace</button> <button class=\"reset\">Cerrar</button></div><output role=\"status\"></output></form></dialog></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"/privacidad/\">Privacidad</a><a href=\"/acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/style.css":":root{color-scheme:dark;--bg:#101419;--panel:#181e25;--edge:#303943;--muted:#aab6c2;--lime:#c7fa75;--mono:\"IBM Plex Mono\",monospace}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:#edf3f8;font:16px Geist,system-ui,sans-serif}a{color:inherit}button,input,select{font:inherit}button,select{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--lime);outline-offset:4px}[hidden]{display:none!important}.wrap{width:min(1200px,calc(100% - 48px));margin:auto}header{border-bottom:1px solid var(--edge)}.nav,footer{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 0}.brand{display:flex;align-items:center;font:800 23px Geist,sans-serif;text-decoration:none;letter-spacing:-.045em}.mark{color:#152011;background:var(--lime);border-radius:8px;padding:2px 8px;margin-right:10px;font-size:23px}.lime{color:var(--lime)}nav{display:flex;gap:24px}nav a{font-size:14px;text-decoration:none;color:var(--muted)}a:hover{color:var(--lime)}.hero{overflow:hidden;position:relative;margin-top:30px;border:1px solid var(--edge);border-radius:22px;background:#181f26;padding:clamp(25px,5.5vw,72px)}.pattern{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#181f26 15%,transparent 80%),radial-gradient(ellipse at 85% 26%,#58763a60,transparent 48%),repeating-linear-gradient(150deg,transparent 0 38px,#b9f37730 39px 40px),repeating-linear-gradient(30deg,transparent 0 38px,#b9f37730 39px 40px);mask-image:linear-gradient(90deg,transparent 15%,black 75%)}.hero-content{position:relative}.eyebrow{color:var(--lime);font:500 .73rem var(--mono);letter-spacing:.13em;margin:0 0 12px}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(2.85rem,8vw,6.25rem);line-height:.96;letter-spacing:-.075em;margin:0 0 22px}h1 em{font-style:normal;color:var(--lime)}.hero p:not(.eyebrow),.note{color:var(--muted);max-width:580px;line-height:1.55}form{display:flex;align-items:center;gap:10px;max-width:665px;border:1px solid #627152;background:#101419;padding:6px;border-radius:12px;margin-top:24px}form span{font-size:29px;padding-left:8px;color:var(--lime)}form input{min-width:0;flex:1;color:inherit;border:0;background:transparent;padding:10px 0}form button{background:var(--lime);color:#18200c;border:0;border-radius:8px;padding:11px 14px;font-weight:700}.suggestions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:14px;color:var(--muted);font-size:.82rem}.suggestions button,.reset{border:1px solid var(--edge);border-radius:8px;background:var(--panel);color:inherit;padding:6px 10px}.suggestions button:hover,.reset:hover{color:var(--lime)}section:not(.hero){padding-top:48px;scroll-margin-top:12px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:12px;margin-bottom:16px}h2{font-size:clamp(1.7rem,4vw,2.4rem);letter-spacing:-.045em;margin:0}#count{color:var(--muted);font:.78rem var(--mono);margin:0 0 4px;text-align:right}.filters{display:flex;flex-wrap:wrap;align-items:end;gap:14px;padding:14px;background:var(--panel);border:1px solid var(--edge);border-radius:12px;margin-bottom:16px}.filters>label,legend{font-size:.78rem;color:var(--muted)}.filters>label{display:grid;gap:5px}fieldset{border:0;margin:0;padding:0;display:flex;gap:3px}legend{padding:0;margin-bottom:5px}fieldset input,.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}fieldset span,select{display:inline-block;padding:7px 10px;border:1px solid var(--edge);border-radius:6px;background:#11161c;color:#edf3f8;font-size:.88rem}fieldset span{cursor:pointer}fieldset input:checked+span{background:var(--lime);color:#152011;border-color:var(--lime)}fieldset input:focus-visible+span{outline:2px solid white}.reset{margin-left:auto;font-size:.85rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,245px),1fr));gap:14px}.card{background:var(--panel);border:1px solid var(--edge);border-radius:14px;padding:16px;display:flex;flex-direction:column;min-height:177px}.card:hover{border-color:#698651}.card-top,.card-bottom{display:flex;align-items:center;justify-content:space-between;gap:8px}.card-top{color:var(--muted);font-size:.78rem}.price{color:var(--lime);background:#243423;padding:4px 7px;border-radius:5px;font:500 .69rem var(--mono)}.price.pago{color:#ffcf96;background:#3d2c21}.card h3{font-size:1.18rem;margin:17px 0 4px}.card p{color:var(--muted);font-size:.8rem;margin-bottom:15px}.card-bottom{margin-top:auto}.formats{display:flex;gap:4px}.formats span{font:500 .67rem var(--mono);border:1px solid var(--edge);padding:4px;border-radius:4px}.card a{color:var(--lime);text-decoration:none;font-size:.82rem;font-weight:600}.card a:hover{text-decoration:underline}.directories{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:8px}.directories a{display:flex;justify-content:space-between;padding:12px 14px;background:var(--panel);border:1px solid var(--edge);border-radius:8px;text-decoration:none;font-size:.9rem}#empty{border:1px dashed var(--edge);border-radius:12px;padding:22px}#empty p,footer{color:var(--muted)}#empty a{color:var(--lime)}footer{border-top:1px solid var(--edge);margin-top:44px!important;font-size:.79rem}@media(max-width:560px){.wrap{width:calc(100% - 26px)}nav{gap:12px}.hero{margin-top:15px}form{gap:5px}form span{display:none}form input{padding-left:5px}form button{padding:10px 8px}.reset{margin-left:0}}\n.card{padding:0;overflow:hidden}.preview{height:170px;display:grid;place-items:center;position:relative;overflow:hidden;background:#232c32;color:var(--muted);font-size:.75rem}.preview img{width:100%;height:100%;position:absolute;inset:0;object-fit:contain;background:#151a20;opacity:0}.preview img.ready{opacity:1}.details{display:flex;flex-direction:column;flex:1;padding:15px}.card h3{overflow-wrap:anywhere}.card-bottom{padding-top:8px;flex-wrap:wrap}\n\n@media(max-width:560px){.nav{align-items:flex-start;flex-direction:column;gap:12px}nav{flex-wrap:wrap}footer{flex-wrap:wrap}}\n\n.info-page{max-width:720px;line-height:1.6}.info-page h1{font-size:clamp(2.4rem,7vw,4rem);margin-bottom:24px}.info-page h2{margin-top:24px;font-size:1.4rem}.info-page p{color:var(--muted)}\n\n.categories{display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid var(--edge);padding-top:17px;margin-top:20px}.categories button{background:#222d33;border:1px solid #526346;color:#edf3f8;border-radius:20px;padding:9px 14px}.categories button:hover{background:var(--lime);color:#152011}.downloads{font-size:.8rem;color:var(--muted);margin:10px 0}\n\n.pagination{display:flex;justify-content:center;align-items:center;gap:16px;margin:24px 0}.reset:disabled{opacity:.4;cursor:default}.license{margin:12px 0 0!important;font-size:.75rem!important}.details>.reset{margin:12px 0 0;align-self:start}\n\n.preview{position:relative;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:12px}.preview span{padding:0 18px;text-align:center}.preview-original{font-size:12px;color:var(--accent,#c7ff6b);position:relative;z-index:1}.preview img{object-fit:contain;background:#151c22}.preview [hidden]{display:none!important}\n\n.categories a{padding:10px 14px;border:1px solid #44564b;border-radius:24px;background:#232e31;text-decoration:none;color:#eef5f4}\n.categories a:hover,.categories a:focus-visible{border-color:#c6ff6d}\n.model-actions,.collection-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:12px}\n.model-note{flex:1 0 100%;white-space:pre-wrap;overflow-wrap:anywhere}\ndialog{color:#eef5f4;background:#1a2228;border:1px solid #45564c;border-radius:16px;width:min(540px,90vw);padding:24px}\ndialog::backdrop{background:#000a}dialog label{display:grid;gap:5px;margin:12px 0}\ndialog :is(input,select,textarea){width:100%;font:inherit;color:inherit;background:#11161a;border:1px solid #58665d;border-radius:6px;padding:8px}\n.category-guide{max-width:760px;margin:36px 0}.category-guide p{line-height:1.7}\n.category-guide .suggestions a{display:inline-block;margin:4px 8px 4px 0}\n[data-ad-slot][hidden],dialog [hidden]{display:none!important}\n\n[data-ad-slot]:not([hidden]){min-height:120px;margin-block:24px;text-align:center}\n\n.breadcrumb{display:flex;gap:8px;align-items:center;margin-top:28px;font-size:.82rem;color:var(--muted)}\n.breadcrumb a{color:var(--muted);text-decoration:none}\n.breadcrumb a:hover{color:var(--lime)}\n.category-page section:not(.hero){padding-top:40px}\n.category-hero{padding-top:20px!important}\n.category-hero h1{font-size:clamp(2.4rem,6vw,4.4rem);max-width:15ch}\n.category-hero p:not(.eyebrow){color:var(--muted);max-width:68ch;line-height:1.7}\n.category-page h2{font-size:clamp(1.4rem,3vw,1.9rem);margin-bottom:14px}\n.more{color:var(--lime);text-decoration:none;font-weight:600;font-size:.9rem;white-space:nowrap}\n.model-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,250px),1fr));gap:14px}\n.model-card{background:var(--panel);border:1px solid var(--edge);border-radius:14px;overflow:hidden;text-decoration:none;display:flex;flex-direction:column}\n.model-card:hover{border-color:#698651;color:inherit}\n.model-card img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:#151a20}\n.model-card div{padding:12px 14px 14px;display:flex;flex-direction:column;gap:6px;flex:1}\n.model-card strong{font-size:.98rem;line-height:1.3;overflow-wrap:anywhere}\n.model-card small{color:var(--muted);font-size:.75rem;display:flex;flex-direction:column;align-items:flex-start;gap:8px;margin-top:auto}\n.model-card .lic{font:500 .66rem var(--mono);padding:3px 6px;border-radius:4px;background:#243423;color:var(--lime);white-space:nowrap}\n.model-card .lic.personal{background:#3d2c21;color:#ffcf96}\n.model-card .lic.unknown{background:#262f38;color:var(--muted)}\n.models-fallback{border:1px dashed var(--edge);border-radius:12px;padding:22px;color:var(--muted)}\n.models-fallback a{color:var(--lime)}\n.category-related .suggestions a{padding:9px 14px;border:1px solid var(--edge);border-radius:24px;background:var(--panel);text-decoration:none;color:#edf3f8;font-size:.9rem}\n.category-related .suggestions a:hover{border-color:var(--lime)}\n.category-columns{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:0 40px}\n.checklist{margin:0;padding-left:1.2rem;color:var(--muted);line-height:1.7}\n.checklist li{margin-bottom:8px}\n.setup{margin:0;border:1px solid var(--edge);border-radius:12px;overflow:hidden}\n.setup div{display:grid;grid-template-columns:minmax(110px,.6fr) 1fr;gap:12px;padding:10px 14px;border-bottom:1px solid var(--edge)}\n.setup div:last-child{border-bottom:0}\n.setup dt{color:var(--muted);font-size:.85rem}\n.setup dd{margin:0;font-size:.92rem}\n.category-page .note{font-size:.82rem;margin-top:10px}\n.category-cta{margin-top:40px;padding:28px!important;border:1px solid var(--edge);border-radius:16px;background:var(--panel)}\n.category-cta p{color:var(--muted)}\n.button-lime{display:inline-block;background:var(--lime);color:#18200c;text-decoration:none;font-weight:700;border-radius:8px;padding:11px 16px}\n.button-lime:hover{color:#18200c;background:#d8ff96}\n.category-page .categories{border-top:0;margin-top:0;padding-top:0}\n@media(min-width:1100px){.model-grid{grid-template-columns:repeat(4,1fr)}}\n\n.takedown-form{display:grid;gap:14px;max-width:620px;margin:18px 0 0;padding:20px;border:1px solid var(--edge);border-radius:14px;background:var(--panel)}.takedown-form label{display:grid;gap:6px;font-size:.9rem;color:var(--muted)}.takedown-form :is(input,select,textarea){width:100%;font:inherit;color:#edf3f8;background:#11161c;border:1px solid var(--edge);border-radius:8px;padding:10px}.takedown-form button{justify-self:start;background:var(--lime);color:#18200c;border:0;border-radius:8px;padding:11px 16px;font-weight:700}.takedown-form .trap{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}.form-status{padding:12px 14px;border-radius:10px;border:1px solid var(--edge);background:var(--panel)}.form-status.enviada{border-color:#698651;color:var(--lime)}.form-status:is(.incompleto,.error){border-color:#8a5a3c;color:#ffcf96}\n\n/* Tarjeta de modelo (paso E): imagen enlazada, favorito sobre la imagen y acciones secundarias en \"⋯\". */\n.card{position:relative;padding:0;overflow:visible}\n.card-media{display:block;position:relative;aspect-ratio:4/3;background:#151a20;border-radius:13px 13px 0 0;overflow:hidden}\n.card-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .2s,transform .3s}\n.card-media img.ready{opacity:1}\n.card:hover .card-media img{transform:scale(1.03)}\n.card-placeholder{position:absolute;inset:0;display:grid;place-items:center;padding:16px;text-align:center;color:var(--muted);font-size:.8rem}\n.card .fav{position:absolute;top:10px;right:10px;width:38px;height:38px;border-radius:50%;border:1px solid #ffffff30;background:#101419d0;color:#edf3f8;font-size:18px;line-height:1;display:grid;place-items:center}\n.card .fav:hover,.card .fav.on{color:var(--lime);border-color:var(--lime)}\n.card .details{padding:14px 15px 12px;gap:6px}\n.card h3{font-size:1.05rem;line-height:1.3;margin:4px 0 0}\n.card .details>p{margin:0}\n.card-meta{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:4px;font-size:.75rem;color:var(--muted)}\n.card-meta .downloads{margin:0}\n.lic{font:500 .66rem var(--mono);padding:3px 6px;border-radius:4px;background:#243423;color:var(--lime);white-space:nowrap}\n.lic.personal{background:#3d2c21;color:#ffcf96}\n.lic.unknown{background:#262f38;color:var(--muted)}\n.card .card-bottom{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto;padding-top:10px;border-top:1px solid var(--edge)}\n.more-menu{position:relative}\n.more-menu summary{list-style:none;cursor:pointer;width:34px;height:30px;display:grid;place-items:center;border:1px solid var(--edge);border-radius:8px;color:var(--muted);font-size:1.1rem;line-height:1}\n.more-menu summary::-webkit-details-marker{display:none}\n.more-menu summary:hover,.more-menu[open] summary{color:var(--lime);border-color:#698651}\n.more-menu .model-actions{position:absolute;right:0;bottom:calc(100% + 6px);z-index:5;display:flex;flex-direction:column;align-items:stretch;gap:2px;margin:0;min-width:210px;padding:6px;background:#1c242c;border:1px solid var(--edge);border-radius:10px;box-shadow:0 12px 30px #0008}\n.more-menu .model-actions :is(a,button){display:block;text-align:left;padding:8px 10px;border:0;border-radius:6px;background:none;color:#edf3f8;font-size:.85rem;font-weight:500;text-decoration:none}\n.more-menu .model-actions :is(a,button):hover{background:#26313a;color:var(--lime)}\n.more-menu .license{padding:6px 10px 2px;color:var(--muted)}\n@media(max-width:560px){\n#models.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n#models .card .details{padding:10px 10px 8px}\n#models .card h3{font-size:.9rem}\n#models .card .details>p{display:none}\n#models .card-top{font-size:.68rem}\n#models .card .fav{width:32px;height:32px;font-size:15px;top:6px;right:6px}\n#models .card-meta .formats{display:none}\n#models .more-menu .model-actions{min-width:170px}\n#models .card .card-bottom a.open-model{font-size:.78rem}\n}\n.guide-links{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:8px}\n.guide-links a{display:block;padding:12px 14px;border:1px solid var(--edge);border-radius:10px;background:var(--panel);text-decoration:none;font-size:.92rem}\n.guide-links a:hover{border-color:#698651}\n","/herramientas/app.js":"const machines = {\n  k1: ['Creality K1 + CFS', 'Creality Print / OrcaSlicer · Kit CFS', 90, 'Usá el perfil de máquina de la K1 con el kit CFS cuando imprimas desde el alimentador.'],\n  k1c: ['Creality K1C', 'Creality Print / OrcaSlicer', 90, 'Seleccioná el preset de K1C y verificá tu configuración de alimentación.'],\n  ke: ['Creality Ender-3 V3 KE', 'Creality Print / OrcaSlicer', 75, 'Seleccioná el preset de V3 KE y verificá la adhesión con una muestra.'],\n  a1: ['Bambu Lab A1', 'Bambu Studio / OrcaSlicer', 80, 'Seleccioná el preset A1. Para piezas altas y delgadas, probá una velocidad menor si la cama en movimiento genera vibración.'],\n  p2s: ['Bambu Lab P2S','Bambu Studio',90,'Activá el preset de la P2S con tu boquilla en el laminador.'],\n  x2d: ['Bambu Lab X2D','Bambu Studio',90,'Partí del preset de la X2D. Confirmá la boquilla y el extrusor activo antes de laminar.'],\n  core: ['Prusa CORE One+','PrusaSlicer',90,'Activá el perfil CORE One+ en el asistente de configuración de PrusaSlicer.'],\n  centauri: ['Elegoo Centauri Carbon 2','Preset del fabricante / OrcaSlicer si está disponible',90,'Confirmá el perfil de Carbon 2 para tu versión del laminador.'],\n  qidi: ['QIDI Q2','QIDI Studio / OrcaSlicer si está disponible',90,'Usá el preset de Q2 y conservá la configuración térmica de fábrica.'],\n  kobra: ['Anycubic Kobra S1 Combo','Anycubic Slicer Next',90,'Activá Kobra S1 y verificá tu configuración ACE antes de laminar.'],\n  u1: ['Snapmaker U1','Snapmaker Orca',90,'Usá la configuración de la U1 y seleccioná la herramienta correcta.'],\n  k2: ['Creality K2 Plus','Creality Print / OrcaSlicer si está disponible',90,'Usá el preset K2 Plus y revisá el alimentador que tengas conectado.'],\n  h2d: ['Bambu Lab H2D','Bambu Studio',90,'Usá el preset H2D y verificá las boquillas activas.'],\n  p1s: ['Bambu Lab P1S', 'Bambu Studio / OrcaSlicer', 90, 'Seleccioná el preset P1S y conservá los ajustes de ventilación recomendados para tu placa y filamento.']\n};\nconst genericMachine=['Sin impresora seleccionada','Perfil orientativo',80,'Elegí una impresora para consultar sus recomendaciones.'];\nconst machineFor=key=>machines[key]??genericMachine;\nconst categories = {\n  decor:['Decoración','◈'], play:['Juegos y fidgets','◎'],\n  home:['Hogar y escritorio','▥'], shop:['Taller y repuestos','⌑'],\n  gifts:['Regalos y productos para vender','◇'], hobby:['Maquetas y hobbies','▱']\n};\n// Nombre, categoría, materiales, capa, paredes, relleno, pared exterior, variantes y opción especial.\nconst profiles = [\n ['Macetas','decor','pla petg matte plaplus petght asa',.20,3,12,45,'Para interior, probá PLA. Si usás plato, imprimilo aparte y revisá el drenaje. En modelos de autorriego, elegí un material apto para el depósito y probá pérdidas antes de usarlo.'],\n ['Floreros','decor','pla petg matte silk',.20,3,12,40,'Imprimí de pie y ubicá la costura atrás. Para flores frescas, un tubo de vidrio removible puede contener el agua. Para flores secas, la pieza impresa puede usarse sola.'],\n ['Pantallas para lámparas','decor','petg petght',.20,2,0,35,'Probá difusión y temperatura con la luz LED prevista. Verificá el encastre y los requisitos aplicables si vas a vender la luminaria completa.','open-shell'],\n ['Bases para lámparas','decor','pla petg matte abs',.20,4,20,45,'Probá la estabilidad y el ajuste con la pantalla y el módulo reales. Este perfil corresponde a la base impresa.'],\n ['Portavelas LED','decor','pla petg',.16,3,12,35,'Para luces LED sin llama. Medí el diámetro y verificá el acceso al interruptor.'],\n ['Decoración de pared','decor','pla hyper matte silk',.20,3,10,50,'Para relieves, placas y paneles. Imprimí el relieve hacia arriba cuando sea posible y verificá la fijación.'],\n ['Porta sahumerios','decor','pla petg',.20,3,15,45,'Usá la impresión como carcasa para un inserto apropiado. Mantené el calor y las brasas alejados del plástico.'],\n ['Fidgets articulados','play','pla hyper plaplus',.16,3,15,40,'Para cubos infinitos, aros giratorios y animales articulados. Probá 0,30, 0,35 y 0,40 mm entre caras en XY. Dejá enfriar la pieza y comprobá el movimiento completo.','articulated'],\n ['Engranajes','play','pla hyper petg abs pa placf',.16,4,20,40,'Imprimí planos. Para un eje impreso de 5,00 mm, probá un agujero de 5,40 mm y ajustá según el resultado.'],\n ['Mecanismos deslizantes','play','pla hyper petg petght pa',.20,4,20,45,'Para sliders, correderas y guías móviles. Probá 0,20–0,30 mm de holgura por lado y ubicá la costura fuera de las caras de contacto.'],\n ['Clickers y fidgets flexibles','play','petg tpu pp',.20,4,20,35,'Orientá el clip para que la flexión principal ocurra en el plano de las capas. Probá el retorno y revisá si aparecen grietas.'],\n ['Rompecabezas','play','pla hyper plaplus matte',.16,3,15,40,'Probá dos piezas vecinas antes de imprimir el juego completo. Un chaflán inferior puede facilitar el encastre.'],\n ['Accesorios para juegos de mesa','play','pla hyper matte',.20,3,15,45,'Para bandejas, fichas, torres de dados y organizadores. Si diseñás una torre, usá rampas autoportantes o dividila para retirar soportes.'],\n ['Soportes de escritorio y pared','home','pla hyper petg abs asa placf',.20,4,22,45,'Para celulares, controles y auriculares. Probá el peso real y el acceso a cables o botones. Si va a la pared, verificá la fijación.'],\n ['Organizadores y bandejas','home','pla hyper petg matte petght silk',.24,3,12,50,'Para cajones, escritorio y vaciabolsillos. Medí el espacio disponible y probá un módulo antes de imprimir un conjunto.'],\n ['Organización de cables','home','petg tpu pp',.20,4,20,40,'Para clips, guías y pasacables. Medí el diámetro y probá apertura, retención y retorno.'],\n ['Soportes para taller y equipos','shop','petg petght asa petgcf abs',.20,5,25,45,'Para baterías, herramientas o routers. Probá el peso, el encastre y la fijación con el equipo real. Dejá ventilación y acceso a conectores cuando corresponda.'],\n ['Adaptadores y acoples','shop','petg petght abs hips pet',.20,4,20,40,'Medí diámetros interiores y exteriores. Probá un tramo corto para verificar ajuste y sellado antes de imprimir el adaptador completo.'],\n ['Repuestos y encastres','shop','petg pla abs asa pa pc hips',.16,4,22,35,'Para tapas, perillas y piezas similares. Copiá el encastre con calibre y limitá la aplicación a repuestos sin función de seguridad.'],\n ['Guías y plantillas','shop','pla hyper petg placf petgcf',.20,4,20,45,'Comprobá distancias con calibre. Para plantillas repetidas, imprimí una muestra y verificá la alineación antes de fabricar la tanda.'],\n ['Cajas y carcasas','shop','petg abs asa pp pc petgcf hips',.20,4,20,40,'Probá el cierre, las pestañas y los tornillos en una sección. Aplicá el perfil a carcasas sin funciones de seguridad.'],\n ['Topes y patas flexibles','shop','tpu',.20,3,20,28,'Probá la compresión con la carga prevista y revisá la orientación de las capas.'],\n ['Piezas para exterior','shop','asa petght',.20,4,20,45,'Para soportes livianos y accesorios expuestos al sol. Verificá el montaje, la carga y el comportamiento del material con una muestra.'],\n ['Bisagras flexibles','shop','pp',.20,3,20,35,'Para una bisagra viva, probá una sección y evaluá flexión y fatiga antes de fabricar la pieza completa.'],\n ['Llaveros','gifts','pla hyper petg plaplus matte silk',.16,4,20,35,'Para llaveros lisos, con logo o bicolor. Concentrá los cambios de color en capas superiores cuando se pueda y probá la resistencia del ojal.'],\n ['Carteles y exhibidores','gifts','pla hyper petg matte silk',.20,3,15,45,'Para carteles de nombre, exhibidores de tarjetas y códigos QR. Verificá la estabilidad y probá que el texto o código se lea al tamaño final.'],\n ['Imanes decorativos','gifts','pla hyper',.16,3,15,40,'Medí el alojamiento del imán y verificá su retención. Mantené los imanes pequeños fuera del alcance infantil.'],\n ['Posavasos','gifts','petg petght tpu',.20,4,20,45,'Probá la estabilidad y la condensación con el vaso real. Podés sumar una base de corcho.'],\n ['Figuras y miniaturas','hobby','pla hyper matte silk',.12,3,12,32,'Para figuras decorativas, miniaturas y peanas. Orientá las caras visibles lejos de los soportes. Para detalles finos, evaluá una boquilla de 0,2 mm con su propio preset.','painted-supports'],\n ['Maquetas y escenografía','hobby','pla hyper matte hips',.20,3,12,42,'Para terreno de rol y maquetas arquitectónicas. Separá piezas difíciles y verificá paredes finas, texturas y encastres en la vista previa.'],\n ['Organizadores de cartas','hobby','pla hyper petg',.20,3,15,50,'Medí las cartas con funda. Agregá acceso para el dedo y probá el ancho con el mazo real.']\n];\nconst byId = id => document.getElementById(id);\nconst el = {printer:byId('printer'),material:byId('material'),category:byId('category'),search:byId('search'),list:byId('list'),detail:byId('detail')};\nlet selected = 0;\nfunction addOptions(select, entries) {\n  for (const [key,label] of entries) select.add(new Option(label,key));\n}\naddOptions(el.printer,[['all','Elegí una impresora'],...Object.entries(machines).map(([key,value])=>[key,value[0]])]);\naddOptions(el.material,[['all','Todos los filamentos'],...Object.entries(materials).filter(([,value])=>value[1]!==null).map(([key,value])=>[key,value[0]])]);\naddOptions(el.category,[['all','Todas las categorías'],...Object.entries(categories).map(([key,value])=>[key,value[0]])]);\nel.printer.value = 'all';\nconst normalize = value => value.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'');\nconst mm = value => value.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});\nfunction getSettings(row, printer, material) {\n  const [,nozzle,bed,fan,materialSpeed] = materials[material];\n  const [, ,machineSpeed] = machineFor(printer);\n  const [, , ,layer,walls,infill,outer,,mode] = row;\n  const inside = Math.min(outer + 30,machineSpeed,materialSpeed);\n  const shell = Math.max(4,Math.ceil(.64/layer));\n  const first = layer === .24 ? .24 : .20;\n  return [\n    ['Boquilla',nozzle+' °C'],['Cama',bed+' °C'],['Ventilador de pieza',fan],\n    ['Altura de capa',mm(layer)+' mm'],['Primera capa',mm(first)+' mm'],['Línea exterior','0,42 mm'],\n    ['Paredes',String(walls)],['Capas arriba / abajo',mode === 'open-shell' ? '0 / 0*' : shell+' / '+shell],['Relleno',infill ? infill+'% gyroid' : '0%'],\n    ['Pared externa',Math.min(outer,materialSpeed)+' mm/s'],['Pared interna',inside+' mm/s'],['Primera capa · velocidad','25 mm/s'],\n    ['Pie de elefante',mode === 'articulated' ? '0,15 mm' : '0,10 mm'],['Soportes',mode === 'painted-supports' ? 'Pintados si hacen falta' : 'Apagados de inicio'],['Perímetros chicos',Math.min(outer,materialSpeed,mode === 'articulated' ? 30 : 35)+' mm/s']\n  ];\n}\nfunction showDetail(index) {\n  if (index === undefined) {\n    el.detail.innerHTML = '<div class=\"detail-head\"><h2>Sin perfiles para esos filtros</h2><p>Probá con otra búsqueda, categoría o material.</p></div>';\n    return;\n  }\n  const row = profiles[index];\n  const [name,group,recommended,,,,,note,mode] = row;\n  const printer = el.printer.value;\n  const material = el.material.value === 'all' ? recommended.split(' ')[0] : el.material.value;\n  const settings = getSettings(row,printer,material);\n  const supportGap = materials[material][5].startsWith('PETG') ? '0,28–0,32' : '0,24';\n  const extra = mode === 'articulated'\n    ? 'En capa de 0,16 mm, probá separaciones Z de 0,32 y 0,48 mm si hay piezas superpuestas. Revisá los puentes en la vista previa.'\n    : 'Si agregás soportes, probá 2 capas de interfaz y una separación Z superior de '+supportGap+' mm. Confirmá el espacio efectivo en la vista previa.';\n  const materialNote=materialNotes[material]?' '+materialNotes[material]:'';\n  const shape = mode === 'open-shell' ? ' *Cero capas sólidas para una pantalla modelada como pared abierta. Confirmá que el aro de montaje se imprime completo; ajustá capas sólidas si el modelo las requiere.' : '';\n  el.detail.innerHTML = '<div class=\"detail-head\"><span class=\"mono\">'+categories[group][0]+' · '+materials[material][0]+'</span><h2>'+name+'</h2><p>'+note+'</p></div><dl class=\"data\">'+settings.map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl><div class=\"notes\"><p>'+extra+shape+materialNote+'</p><button class=\"copy\" type=\"button\">Copiar parámetros</button><span class=\"status\" role=\"status\"></span></div>';\n  attachExport(el.detail.querySelector('.notes'), {row, printer, material});\n  el.detail.querySelector('.copy').onclick = async () => {\n    const output = [name+' · '+machineFor(printer)[0]+' · '+materials[material][0]+' · Boquilla 0,4 mm',...settings.map(pair=>pair.join(': ')),note,extra+shape+materialNote].join('\\n');\n    const status = el.detail.querySelector('.status');\n    try { await navigator.clipboard.writeText(output); status.textContent = 'Copiado'; }\n    catch {\n      let box = el.detail.querySelector('textarea');\n      if (!box) { box = document.createElement('textarea'); box.className = 'copybox'; box.readOnly = true; box.rows = 6; box.setAttribute('aria-label','Parámetros para copiar'); status.after(box); }\n      box.value = output; box.focus(); box.select(); status.textContent = 'Copiá el texto seleccionado';\n    }\n  };\n}\nfunction render(focusProfile = false) {\n  const printer = el.printer.value;\n  byId('context').textContent = machineFor(printer)[3]+' Parámetros iniciales para boquilla de 0,4 mm.';\n  const previousScroll=el.list.scrollTop;\n  const query = normalize(el.search.value.trim()).split(/\\s+/);\n  const results = profiles.map((row,index)=>({row,index})).filter(({row})=>\n    (el.category.value === 'all' || row[1] === el.category.value) &&\n    (el.material.value === 'all' || row[2].split(' ').includes(el.material.value)) &&\n    query.every(word=>normalize(row[0]+' '+categories[row[1]][0]+' '+row[7]+' '+row[2].split(' ').map(key=>materials[key][0]).join(' ')).includes(word))\n  );\n  if (!results.some(entry=>entry.index === selected)) selected = results[0]?.index;\n  byId('count').textContent = results.length+' / '+profiles.length;\n  el.list.replaceChildren(...results.map(({row,index})=>{\n    const button = document.createElement('button');\n    button.type = 'button'; button.className = 'item';\n    button.dataset.profile = index;\n    button.setAttribute('aria-pressed',String(index === selected));\n    button.innerHTML = '<span class=\"icon\" aria-hidden=\"true\">'+categories[row[1]][1]+'</span><span><strong>'+row[0]+'</strong><small>'+row[2].split(' ').map(key=>materials[key][0]).join(' · ')+'</small></span><span class=\"arrow\" aria-hidden=\"true\">›</span>';\n    button.onclick = () => { selected = index; render(true); };\n    return button;\n  }));\n  el.list.scrollTop=focusProfile?previousScroll:0;\n  showDetail(selected);\n  if (focusProfile) {\n    if (matchMedia('(max-width: 750px)').matches) el.detail.focus();\n    else el.list.querySelector('[data-profile=\"'+selected+'\"]')?.focus({preventScroll:true});\n  }\n}\nbyId('clearFilters').onclick = () => {\n  el.printer.value='all'; el.material.value='all'; el.category.value='all'; el.search.value='';\n  selected=0; render(); el.search.focus();\n};\nfor (const control of [el.printer,el.material,el.category,el.search]) control.addEventListener('input',()=>render());\nrender();\nconst materialCatalog=byId('materialCatalog');\nfor(const group of materialGroups) {\n  const section=document.createElement('section');\n  section.className='material-group';\n  const entries=Object.entries(materials).filter(([,value])=>value[6]===group);\n  section.innerHTML='<h3>'+group+'</h3><div class=\"guide-grid\">'+entries.map(([key,[name,nozzle,bed,, , , ,description]])=>\n    '<article><h4>'+name+'</h4><p>'+description+'</p>'+(nozzle===null?'<small>Consultá la ficha de la bobina.</small>':'<small>'+nozzle+' °C boquilla · '+bed+' °C cama</small><button class=\"quiet\" type=\"button\" data-material=\"'+key+'\">Ver perfiles</button>')+'</article>').join('')+'</div>';\n  materialCatalog.append(section);\n}\nmaterialCatalog.addEventListener('click',event=>{\n  const key=event.target.closest('[data-material]')?.dataset.material;\n  if(!key) return;\n  el.material.value=key; el.category.value='all'; el.search.value=''; render();\n  location.hash='perfiles'; el.material.focus({preventScroll:true});\n});\n\nconst costForm=byId('costForm');\nconst modelParams=new URLSearchParams(location.search);\nconst costModel=byId('costModel');\nconst modelTitle=modelParams.get('modelo')?.trim().slice(0,200);\nif(costModel && modelTitle) {\n  costModel.hidden=false;\n  costModel.querySelector('span').textContent='Modelo: '+modelTitle;\n  const modelLink=costModel.querySelector('a');\n  const ficha=modelParams.get('ficha') ?? '';\n  if(/^https:\\/\\/(www\\.printables\\.com|cults3d\\.com|www\\.thingiverse\\.com|shapekit\\.cc)\\//.test(ficha)) modelLink.href=ficha;\n  else modelLink.hidden=true;\n  for(const name of ['grams','hours']) {\n    const input=costForm.elements.namedItem(name);\n    input.value='';\n    input.placeholder='Dato del laminador';\n  }\n}\nfunction makerCost({grams,spool,extraGrams,extraSpool,hours,hour,watts,kwh,laborMinutes,laborRate,packing,fixed,fee,margin,units,failure}) {\n  const filament=(grams*spool+extraGrams*extraSpool)/1000;\n  const energy=hours*watts*kwh/1000;\n  const labor=laborMinutes*laborRate/60;\n  const machine=hours*hour;\n  const batch=(filament+energy+machine+labor)/(1-failure/100);\n  const unit=batch/units+packing;\n  const order=unit*units+fixed;\n  const available=1-(fee+margin)/100;\n  return {filament,energy,labor,machine,batch,unit,order,floor:order/(1-fee/100),price:available>0?Math.ceil(order/available):null};\n}\nfunction calculateCost() {\n  const output=byId('costResult');\n  if(!costForm.checkValidity()) {\n    const invalid=[...costForm.elements].find(element=>element.willValidate && !element.checkValidity());\n    const label=invalid?.closest('label')?.firstChild?.textContent?.trim();\n    output.textContent=label ? 'Completá o corregí «'+label+'» para ver el precio.' : 'Revisá los importes, unidades y porcentajes.';\n    return;\n  }\n  const input=Object.fromEntries([...new FormData(costForm)].map(([key,value])=>[key,Number(value)]));\n  const cost=makerCost(input);\n  const pesos=new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0});\n  const money=value=>pesos.format(value);\n  const rows=[\n    ['Filamento por intento',cost.filament],['Energía por intento',cost.energy],['Desgaste por intento',cost.machine],['Mano de obra por intento',cost.labor],\n    ['Producción con fallos estimados',cost.batch],['Costo unitario con embalaje',cost.unit],['Punto de equilibrio por pedido',Math.ceil(cost.floor)]\n  ];\n  const perPiece=cost.price===null?null:cost.price/input.units;\n  const summary=document.createElement('div');\n  summary.className='price-summary';\n  if(cost.price===null) {\n    summary.innerHTML='<p class=\"price-error\"></p>';\n    summary.querySelector('p').textContent='La comisión y el margen deben sumar menos de 100%.';\n  } else {\n    summary.innerHTML='<div><span>Precio sugerido por pedido</span><strong></strong><small></small></div><div><span>Por pieza</span><strong></strong><small></small></div>';\n    const [order,piece]=summary.querySelectorAll('div');\n    order.querySelector('strong').textContent=money(cost.price);\n    order.querySelector('small').textContent=input.units+(input.units===1?' unidad':' unidades')+' · '+input.margin+' % de margen';\n    piece.querySelector('strong').textContent=money(perPiece);\n    piece.querySelector('small').textContent='Costo unitario '+money(cost.unit);\n  }\n  const breakdown=document.createElement('dl');\n  breakdown.className='cost-breakdown';\n  breakdown.innerHTML=rows.map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+money(value)+'</dd></div>').join('');\n  const detail=document.createElement('p');\n  detail.className='visually-hidden';\n  detail.textContent=cost.price===null?'':'Precio sugerido por pedido de '+input.units+' unidad(es): '+money(cost.price)+' · Equivale a '+money(perPiece)+' por pieza.';\n  output.replaceChildren(summary,breakdown,detail);\n}\ncostForm.addEventListener('input',calculateCost);\ncostForm.addEventListener('submit',event=>event.preventDefault());\ncalculateCost();\n\n(function () {\n  const form = document.getElementById('costForm');\n  if (!form) return;\n  const panel = document.getElementById('quote-tools');\n  const input = document.getElementById('slicer-file');\n  const fileName = document.getElementById('slicer-file-name');\n  input?.addEventListener('change', () => { if (fileName) fileName.textContent = input.files?.[0]?.name ?? 'Ningún archivo seleccionado'; });\n  // Arrastrar y soltar el G-code sobre el recuadro de importación.\n  const dropZone = input?.closest('.quote-box');\n  if (dropZone && 'DataTransfer' in window) {\n    dropZone.classList.add('drop-zone');\n    const hasFile = event => [...(event.dataTransfer?.types ?? [])].includes('Files');\n    for (const type of ['dragenter', 'dragover']) dropZone.addEventListener(type, event => {\n      if (!hasFile(event)) return;\n      event.preventDefault(); dropZone.classList.add('dragging');\n    });\n    dropZone.addEventListener('dragleave', event => { if (!dropZone.contains(event.relatedTarget)) dropZone.classList.remove('dragging'); });\n    dropZone.addEventListener('drop', event => {\n      if (!hasFile(event)) return;\n      event.preventDefault(); dropZone.classList.remove('dragging');\n      const file = event.dataTransfer.files[0];\n      if (!file) return;\n      const transfer = new DataTransfer(); transfer.items.add(file);\n      input.files = transfer.files;\n      input.dispatchEvent(new Event('change', { bubbles: true }));\n    });\n  }\n  const status = document.getElementById('import-status');\n  const plate = document.getElementById('slicer-plate');\n  const settingsStatus = document.getElementById('settings-status');\n  const field = name => form.elements.namedItem(name);\n  const costFields = ['spool','extraSpool','hour','watts','kwh','laborRate','packing','fee','margin','failure'];\n  const presetKey = 'utilitools-cost-settings-v1';\n  let selections = [];\n  let generation = 0;\n\n  function duration(value) {\n    if (/^\\d+(?:\\.\\d+)?$/.test(value)) return Number(value);\n    const clock = /^(\\d+):(\\d{2}):(\\d{2})$/.exec(value);\n    if (clock) return Number(clock[1])*3600+Number(clock[2])*60+Number(clock[3]);\n    if (!/^(?:\\d+(?:[.,]\\d+)?\\s*[dhms]\\s*)+$/i.test(value)) return 0;\n    const scale = {d:86400,h:3600,m:60,s:1};\n    return [...value.matchAll(/(\\d+(?:[.,]\\d+)?)\\s*([dhms])/gi)]\n      .reduce((sum,match)=>sum+Number(match[1].replace(',','.'))*scale[match[2].toLowerCase()],0);\n  }\n\n  function metadata(text) {\n    const lines = new Map();\n    for (const match of text.matchAll(/^\\s*;\\s*([^=:\\r\\n]+?)\\s*[:=]\\s*([^\\r\\n]+)/gm)) {\n      const key=match[1].trim().toLowerCase();\n      if(!lines.has(key)) lines.set(key,match[2].trim());\n    }\n    function masses(key, vector) {\n      const raw = lines.get(key);\n      if (!raw) return [];\n      const values = vector ? raw.split(/\\s*[,;]\\s*/) : [raw.replace(',','.')];\n      if(!values.every(value=>/^\\d+(?:\\.\\d+)?(?:\\s*g)?$/i.test(value))) return [];\n      return values.map(value=>Number(value.replace(/\\s*g$/i,''))).filter(value=>value>0 && Number.isFinite(value));\n    }\n    let weights = masses('filament used [g]',true);\n    if(!weights.length) weights=masses('filament weight [g]',true);\n    const total = ['total filament weight [g]','total filament used [g]','filament weight','filament used'].flatMap(key=>{\n      if(key.endsWith('[g]')) return masses(key,false);\n      return /g$/i.test(lines.get(key) ?? '') ? masses(key,false) : [];\n    })[0];\n    if (!weights.length && total) weights=[total];\n    if (weights.length===1 && total) weights=[total];\n    // Use the declared total only when it can be reconciled with per-material figures.\n    const sum=weights.reduce((a,b)=>a+b,0);\n    const mixedTotal=weights.length>1 && total && Math.abs(total-sum)>0.1 ? total : null;\n    const seconds = ['total estimated time','estimated total printing time','estimated printing time (normal mode)','estimated printing time','print time','print_time','model printing time','time']\n      .map(key=>duration(lines.get(key) ?? '')).find(value=>value>0 && Number.isFinite(value)) ?? 0;\n    const slicer=/bambustudio|bambu studio/i.test(text)?'bambu':\n      /orcaslicer|orca slicer/i.test(text)?'orca':/creality[_ ]?print/i.test(text)?'creality':'unknown';\n    return {weights, seconds, mixedTotal, slicer};\n  }\n\n  const maxDecoded=160*1024*1024;\n  const decoder=new TextDecoder();\n  async function zipPlates(file) {\n    const tail=await file.slice(Math.max(0,file.size-65557)).arrayBuffer();\n    const end=new DataView(tail);\n    let offset=end.byteLength-22;\n    while(offset>=0 && !(end.getUint32(offset,true)===0x06054b50 && offset+22+end.getUint16(offset+20,true)===end.byteLength)) offset--;\n    if(offset<0 || end.getUint16(offset+4,true) || end.getUint16(offset+6,true)) throw Error('No se pudo leer el archivo comprimido.');\n    const count=end.getUint16(offset+10,true);\n    const size=end.getUint32(offset+12,true);\n    const start=end.getUint32(offset+16,true);\n    if(count>1500 || size>2_000_000 || start+size>file.size) throw Error('El archivo comprimido es demasiado grande.');\n    const directory=new DataView(await file.slice(start,start+size).arrayBuffer());\n    const entries=[];\n    for(let i=0, cursor=0;i<count;i++) {\n      if(cursor+46>size || directory.getUint32(cursor,true)!==0x02014b50) throw Error('El índice del archivo está incompleto.');\n      const nameLength=directory.getUint16(cursor+28,true);\n      const next=cursor+46+nameLength+directory.getUint16(cursor+30,true)+directory.getUint16(cursor+32,true);\n      if(next>size) throw Error('El índice del archivo está incompleto.');\n      const name=decoder.decode(new Uint8Array(directory.buffer,cursor+46,nameLength));\n      if(/^Metadata\\/plate[_-]?\\d+\\.gcode$/i.test(name)) {\n        const method=directory.getUint16(cursor+10,true);\n        const bytes=directory.getUint32(cursor+20,true);\n        const unpacked=directory.getUint32(cursor+24,true);\n        const header=directory.getUint32(cursor+42,true);\n        if(unpacked>maxDecoded || bytes>maxDecoded || (directory.getUint16(cursor+8,true)&1) || ![0,8].includes(method)) throw Error('La placa comprimida supera el límite o usa un formato incompatible.');\n        entries.push({name,method,bytes,unpacked,header});\n      }\n      cursor=next;\n    }\n    if(!entries.length) throw Error('Este 3MF no contiene G-code de una placa. Laminá y exportá la placa desde Bambu Studio.');\n    return entries.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true})).map(entry=>({\n      name:entry.name.split('/').pop(),format:'3mf',\n      read:async()=>{\n        const local=new DataView(await file.slice(entry.header,entry.header+30).arrayBuffer());\n        if(local.byteLength!==30 || local.getUint32(0,true)!==0x04034b50) throw Error('No se pudo abrir la placa.');\n        const start=entry.header+30+local.getUint16(26,true)+local.getUint16(28,true);\n        if(start+entry.bytes>file.size) throw Error('Los datos de la placa están incompletos.');\n        let stream=file.slice(start,start+entry.bytes).stream();\n        if(entry.method===8) {\n          try { stream=stream.pipeThrough(new DecompressionStream('deflate-raw')); }\n          catch { throw Error('Este navegador no puede abrir la placa comprimida. Exportá un archivo .gcode.'); }\n        }\n        return readEdges(stream,entry.unpacked);\n      }\n    }));\n  }\n\n  async function readEdges(stream, declared) {\n    const reader=stream.getReader();\n    const cap=1024*1024;\n    const first=new Uint8Array(cap), last=new Uint8Array(cap);\n    let total=0;\n    try {\n      for(;;) {\n        const {done,value}=await reader.read();\n        if(done) break;\n        if(total+value.length>Math.min(maxDecoded,declared)) throw Error('La placa excede el tamaño declarado.');\n        if(total<cap) first.set(value.subarray(0,cap-total),total);\n        if(value.length>=cap) last.set(value.subarray(value.length-cap));\n        else {last.copyWithin(0,value.length);last.set(value,cap-value.length);}\n        total+=value.length;\n      }\n    } finally { await reader.cancel(); }\n    if(total!==declared) throw Error('La placa está incompleta.');\n    return decoder.decode(first.subarray(0,Math.min(cap,total)))+\n      (total>cap?'\\n'+decoder.decode(last):'');\n  }\n\n  function commit(data) {\n    const {weights,seconds,mixedTotal}=data;\n    const usable = weights.length<=2 && !mixedTotal;\n    field('grams').value=usable && weights.length ? weights[0] : '';\n    field('extraGrams').value=usable ? weights[1] ?? 0 : '';\n    field('hours').value=seconds ? Number((seconds/3600).toFixed(5)) : '';\n    field('units').value='';\n    const message=[];\n    if(!usable) message.push('El archivo informa varios consumos que la calculadora no puede separar. Revisá los precios y cargá un costo equivalente o los pesos manualmente.');\n    else if(!weights.length) message.push('No encontré el peso en gramos. Ingresalo desde el laminador.');\n    else message.push('Filamento: '+weights.join(' g + ')+' g.' + (weights.length===1?' Si la placa usa varios materiales, verificá cómo se reparte ese total.':''));\n    if(seconds) message.push('Tiempo: '+Math.floor(seconds/3600)+' h '+Math.floor((seconds%3600)/60)+' min '+Math.round(seconds%60)+' s.');\n    else message.push('No encontré el tiempo. Ingresalo manualmente.');\n    if(weights.length===2 && usable) message.push('Revisá el precio por kilo de ambos materiales.');\n    message.push('Ingresá la cantidad de piezas que contiene la placa.');\n    status.textContent=message.join(' ');\n    calculateCost();\n  }\n\n  async function readSelection(entry) {\n    if (!entry) return;\n    const request=++generation;\n    status.textContent='Leyendo la placa…';\n    try {\n      const result=metadata(await entry.read());\n      if(request===generation) {\n        commit(result);\n        window.utilitoolsTrack?.('slicer_import',{slicer:result.slicer,format:entry.format ?? 'gcode',\n          result:result.seconds && result.weights.length && result.weights.length<=2 && !result.mixedTotal ? 'complete':'partial'});\n      }\n    } catch(error) {\n      if(request===generation) {\n        status.textContent=error.message;\n        window.utilitoolsTrack?.('slicer_import',{result:'error',format:entry.format ?? 'gcode'});\n      }\n    }\n  }\n\n  input.addEventListener('change',async()=>{\n    const request=++generation;\n    const file=input.files[0];\n    selections=[]; plate.replaceChildren(); plate.parentElement.hidden=true;\n    if(!file) return;\n    status.textContent='Leyendo el archivo…';\n    try {\n      if(file.size>maxDecoded) throw Error('El archivo supera el límite de 160 MB.');\n      let loaded;\n      if(/\\.3mf$/i.test(file.name)) loaded=await zipPlates(file);\n      else if(/\\.gcode$/i.test(file.name)) {\n        loaded=[{name:file.name,read:async()=>{\n          const cap=1024*1024;\n          if(file.size<=2*cap) return file.text();\n          const [start,end]=await Promise.all([file.slice(0,cap).text(),file.slice(-cap).text()]);\n          return start+'\\n'+end;\n        }}];\n      } else throw Error('Elegí un archivo .gcode o un .gcode.3mf laminado.');\n      if(request!==generation) return;\n      selections=loaded;\n      selections.forEach((entry,index)=>plate.add(new Option(entry.name,String(index))));\n      plate.parentElement.hidden=selections.length<2;\n      await readSelection(selections[0]);\n    } catch(error) { if(request===generation) status.textContent=error.message; }\n  });\n  plate.addEventListener('change',()=>readSelection(selections[Number(plate.value)]));\n\n  try {\n    const saved=JSON.parse(localStorage.getItem(presetKey) ?? 'null');\n    if(saved) for(const name of costFields) {\n      if(typeof saved[name]!=='number' || !Number.isFinite(saved[name])) continue;\n      const control=field(name), previous=control.value;\n      control.value=saved[name];\n      if(!control.validity.valid) control.value=previous;\n    }\n  } catch {}\n  calculateCost();\n\n  document.getElementById('save-costs').addEventListener('click',()=>{\n    if(!costFields.every(name=>field(name).validity.valid)) {\n      settingsStatus.textContent='Revisá los valores de costos antes de guardarlos.';return;\n    }\n    try {\n      localStorage.setItem(presetKey,JSON.stringify(Object.fromEntries(costFields.map(name=>[name,field(name).valueAsNumber]))));\n      settingsStatus.textContent='Costos guardados en este navegador.';\n    } catch {settingsStatus.textContent='El navegador no permitió guardar los costos.';}\n  });\n  function quote() {\n    if(!form.reportValidity()) return '';\n    const data=Object.fromEntries([...new FormData(form)].map(([key,value])=>[key,Number(value)]));\n    const calculated=makerCost(data);\n    if(calculated.price===null || !Number.isFinite(calculated.price)) {\n      settingsStatus.textContent='Revisá el margen, la comisión y los costos para generar la cotización.';return '';\n    }\n    const label=document.getElementById('quote-name').value.trim() || modelTitle || 'Impresión 3D';\n    const ars=new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS'});\n    const perUnit=Number((calculated.price/data.units).toFixed(2));\n    const text=['Presupuesto · '+label,'Cantidad: '+data.units,\n      'Precio '+(perUnit*data.units===calculated.price?'':'promedio ')+'por unidad: '+ars.format(perUnit),\n      'Total: '+ars.format(calculated.price)].join('\\n');\n    document.getElementById('quote-text').value=text;\n    document.getElementById('quote-text').parentElement.hidden=false;\n    return text;\n  }\n  document.getElementById('copy-quote').addEventListener('click',async()=>{\n    const text=quote();\n    if(!text) return;\n    try {await navigator.clipboard.writeText(text);window.utilitoolsTrack?.('quote_exported',{method:'clipboard'});settingsStatus.textContent='Presupuesto copiado para WhatsApp.';}\n    catch {document.getElementById('quote-text').select();settingsStatus.textContent='Copiá el texto seleccionado.';}\n  });\n  document.getElementById('download-quote').addEventListener('click',()=>{\n    const text=quote();\n    if(!text) return;\n    const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));\n    const a=document.createElement('a');a.href=url;a.download='presupuesto-utilitools.txt';a.click();window.utilitoolsTrack?.('quote_exported',{method:'text_file'});\n    setTimeout(()=>URL.revokeObjectURL(url),1000);\n    settingsStatus.textContent='Presupuesto descargado.';\n  });\n  panel.hidden=false;\n}());\n","/herramientas/assets/portada-1120.webp":"","/herramientas/assets/portada-640.webp":"","/herramientas/exports.js":"const slicerNames = {\n  creality:'Creality Print 6/7',\n  orca:'OrcaSlicer 2.x',\n  bambu:'Bambu Studio 2.x',\n  prusa:'PrusaSlicer',\n  cura:'UltiMaker Cura'\n};\nconst jsonPresetVersions = {creality:'6.0.0.0',orca:'2.0.0.0',bambu:'2.0.0.0'};\nfunction standaloneJsonBase(target,type,v) {\n  const preset={type,name:v.name,version:jsonPresetVersions[target],inherits:'',compatible_printers:[]};\n  if(type==='filament') {\n    preset.filament_type=[v.polymer];\n    preset.filament_vendor=['Generic'];\n  }\n  return preset;\n}\nfunction exportValues({row,printer,material}) {\n  const [name,,,layer,walls,infill,outer,,mode] = row;\n  const [label,nozzle,bed,fan,limit] = materials[material];\n  return {\n    name:'Utilitools 3D - '+name+' - '+label,\n    layer,walls,infill,outer:Math.min(outer,limit),\n    inner:Math.min(outer+30,limit,machineFor(printer)[2]),\n    first:layer===.24?.24:.20,\n    shells:mode==='open-shell'?0:Math.max(4,Math.ceil(.64/layer)),\n    elephant:mode==='articulated'?.15:.10,\n    gap:materials[material][5].startsWith('PETG')?.32:.24,\n    nozzle,bed,polymer:materials[material][5],materialName:label,fan:fan.replaceAll('%','').split('–').map(Number)\n  };\n}\nfunction makeJsonPreset(base,v) {\n  if (!base || base.type !== 'process' || typeof base.name !== 'string' || !base.name.trim()) {\n    throw new Error('Elegí el JSON de un preset de proceso, guardado desde tu laminador.');\n  }\n  if (base.from === 'system') throw new Error('Guardá primero una copia del proceso como preset de usuario.');\n  const values = {\n    layer_height:v.layer,initial_layer_print_height:v.first,outer_wall_line_width:.42,\n    wall_loops:v.walls,top_shell_layers:v.shells,bottom_shell_layers:v.shells,\n    sparse_infill_density:v.infill+'%',sparse_infill_pattern:'gyroid',\n    outer_wall_speed:v.outer,inner_wall_speed:v.inner,initial_layer_speed:25,\n    elefant_foot_compensation:v.elephant,enable_support:0,\n    support_top_z_distance:v.gap,support_interface_top_layers:2\n  };\n  if (v.shells===0) { values.top_shell_thickness=0; values.bottom_shell_thickness=0; }\n  const preset={...base,...Object.fromEntries(Object.entries(values).map(([key,value])=>[key,String(value)])),name:v.name,print_settings_id:v.name,from:'User'};\n  for (const key of ['setting_id','sync_info','user_id','preset_id']) delete preset[key];\n  return JSON.stringify(preset,null,2)+'\\n';\n}\nfunction makePrusaBundle(v,kind) {\n  const print = {\n    layer_height:v.layer,first_layer_height:v.first,external_perimeter_extrusion_width:.42,\n    perimeters:v.walls,top_solid_layers:v.shells,bottom_solid_layers:v.shells,\n    fill_density:v.infill+'%',fill_pattern:'gyroid',external_perimeter_speed:v.outer,\n    perimeter_speed:v.inner,first_layer_speed:25,elefant_foot_compensation:v.elephant,\n    support_material:0,support_material_contact_distance:v.gap,support_material_interface_layers:2\n  };\n  if(v.shells===0) { print.top_solid_min_thickness=0; print.bottom_solid_min_thickness=0; }\n  const filament = {\n    filament_type:v.polymer,temperature:v.nozzle,first_layer_temperature:v.nozzle,bed_temperature:v.bed,\n    first_layer_bed_temperature:v.bed,min_fan_speed:v.fan[0],max_fan_speed:v.fan[1],\n    cooling:1,disable_fan_first_layers:2\n  };\n  const section=(type,settings)=>'['+type+':'+v.name+']\\n'+Object.entries(settings).map(pair=>pair.join(' = ')).join('\\n');\n  return section(kind==='filament'?'filament':'print',kind==='filament'?filament:print)+'\\n';\n}\nfunction downloadPreset(name,body,mime) {\n  const url=URL.createObjectURL(new Blob([body],{type:mime}));\n  const link=document.createElement('a');\n  link.href=url; link.download=name; document.body.append(link); link.click(); link.remove();\n  setTimeout(()=>URL.revokeObjectURL(url),1000);\n}\nconst privateKeys=/^(print_?host|host_(type|url|apikey|cafile|password|user|username|access_code)|printhost_.*|access_code|api_key|password|device_id|auth_token)$/i;\nfunction stripPrivateKeys(object) {\n  for (const key of Object.keys(object)) {\n    if (privateKeys.test(key)) delete object[key];\n    else if (object[key] && typeof object[key]==='object') stripPrivateKeys(object[key]);\n  }\n  return object;\n}\nfunction makeTypedJson(base,v,kind,plate,model) {\n  if(!base || base.type!==kind || typeof base.name!=='string' || !base.name.trim() || base.from==='system') {\n    throw new Error('Adjuntá un preset de usuario del tipo elegido, exportado desde ese laminador.');\n  }\n  const name='Utilitools 3D - '+(kind==='machine'?model+' - 0.4 mm':v.materialName+' - '+v.nozzle+' C');\n  const preset=stripPrivateKeys(structuredClone(base));\n  for(const key of ['setting_id','sync_info','user_id','preset_id']) delete preset[key];\n  Object.assign(preset,{name,from:'User'});\n  if(kind==='machine') {\n    if(Array.isArray(base.nozzle_diameter) && base.nozzle_diameter.some(d=>Number(d)!==.4)) throw new Error('Usá una base de máquina con boquilla de 0,4 mm.');\n    preset.printer_settings_id=name;\n  } else {\n    if(Array.isArray(base.filament_type) && base.filament_type.some(type=>type!==v.polymer)) throw new Error('El filamento base debe ser del mismo polímero: '+v.polymer+'.');\n    Object.assign(preset,{\n      filament_settings_id:[name],filament_type:[v.polymer],\n      nozzle_temperature:[String(v.nozzle)],nozzle_temperature_initial_layer:[String(v.nozzle)],\n      fan_min_speed:[String(v.fan[0])],fan_max_speed:[String(v.fan[1])]\n    });\n    if(plate!=='keep') {\n      preset[plate+'_temp']=[String(v.bed)];\n      preset[plate+'_temp_initial_layer']=[String(v.bed)];\n    }\n  }\n  return JSON.stringify(preset,null,2)+'\\n';\n}\nfunction makePrusaMachine(base,model) {\n  const sections=base.replace(/\\r\\n/g,'\\n').split(/(?=^\\[[^\\]\\n]+\\]\\s*$)/m);\n  const printers=sections.filter(section=>/^\\[printer:[^\\]\\n]+\\]/.test(section));\n  if(printers.length!==1) throw new Error('Adjuntá un INI de paquete que contenga exactamente un preset de impresora.');\n  const lines=printers[0].split('\\n');\n  const nozzle=lines.find(line=>/^nozzle_diameter\\s*=/.test(line));\n  if(nozzle && nozzle.split('=')[1].split(',').some(value=>Number(value)!==.4)) throw new Error('Usá una base con boquilla de 0,4 mm.');\n  return ['[printer:Utilitools 3D - '+model+' - 0.4 mm]',...lines.slice(1).filter(line=>!privateKeys.test(line.split('=')[0].trim()))].join('\\n');\n}\nfunction makeCuraMaterial(base,v) {\n  if(/<!DOCTYPE|<!ENTITY/i.test(base)) throw new Error('El XML del material contiene declaraciones no admitidas.');\n  const doc=new DOMParser().parseFromString(base,'application/xml');\n  const root=doc.documentElement;\n  if(root.localName!=='fdmmaterial') throw new Error('Adjuntá un material XML exportado desde Cura.');\n  const direct=(element,key)=>[...element.children].find(node=>node.localName===key);\n  const meta=direct(root,'metadata'), settings=direct(root,'settings');\n  const name=meta&&direct(meta,'name'), guid=meta&&direct(meta,'GUID');\n  if(!name || !guid || !settings) throw new Error('Faltan los datos básicos del material Cura.');\n  const material=direct(name,'material');\n  if(material && !material.textContent.trim().toUpperCase().startsWith(v.polymer)) throw new Error('El material base debe ser del mismo polímero: '+v.polymer+'.');\n  guid.textContent=crypto.randomUUID();\n  const label=direct(name,'label');\n  if(label) label.textContent='Utilitools 3D '+v.polymer;\n  for(const [key,value] of Object.entries({'print temperature':v.nozzle,'heated bed temperature':v.bed,'print cooling':v.fan[1]})) {\n    const existing=[...settings.children].find(node=>node.localName==='setting' && node.getAttribute('key')===key);\n    const node=existing??doc.createElementNS(root.namespaceURI,'setting');\n    node.setAttribute('key',key);\n    node.textContent=String(value);\n    if(!existing) settings.insertBefore(node,settings.firstElementChild);\n  }\n  return new XMLSerializer().serializeToString(doc);\n}\nfunction attachExport(parent,selection) {\n  const panel=document.createElement('details');\n  panel.className='export';\n  panel.innerHTML='<summary>Exportar para laminador</summary><label>Laminador<select class=\"slicer\">'+Object.entries(slicerNames).map(([id,name])=>'<option value=\"'+id+'\">'+name+'</option>').join('')+'</select></label><label>Tipo de perfil<select class=\"kind\"><option value=\"process\">Proceso de impresión</option><option value=\"filament\">Filamento</option><option value=\"machine\">Impresora / máquina</option></select></label><p class=\"instructions\"></p><label class=\"plate\" hidden>Placa para temperatura de cama<select><option value=\"keep\">Conservar temperaturas del preset</option><option value=\"textured_plate\">PEI texturizado</option><option value=\"hot_plate\">Placa de alta temperatura / PEI liso</option></select></label><label class=\"template\"><span>Archivo base</span> <input type=\"file\"></label><button class=\"copy\" type=\"button\">Descargar perfil</button><small class=\"error\" role=\"status\"></small>';\n  parent.append(panel);\n  const select=panel.querySelector('.slicer'), kind=panel.querySelector('.kind'), file=panel.querySelector('input');\n  const plate=panel.querySelector('.plate'), status=panel.querySelector('[role=status]');\n  const model=machineFor(selection.printer)[0];\n  function explain() {\n    const target=select.value, type=kind.value;\n    const template=panel.querySelector('.template');\n    const prusa=target==='prusa', cura=target==='cura';\n    const optionalBase=Object.hasOwn(jsonPresetVersions,target)&&type!=='machine';\n    template.hidden=prusa&&type!=='machine';\n    template.querySelector('span').textContent=optionalBase?'Preset base opcional':'Archivo base del laminador';\n    plate.hidden=prusa||cura||type!=='filament';\n    file.accept=prusa?'.ini':!cura?'.json,application/json':({process:'.curaprofile',filament:'.fdm_material,.xml',machine:'.json'})[type];\n    const instructions=prusa?{\n      process:'Importá el INI como paquete de configuración y seleccioná el nuevo proceso.',\n      filament:'Importá el INI como paquete de configuración y seleccioná el nuevo filamento.',\n      machine:'Adjuntá un paquete INI de PrusaSlicer con un solo preset de impresora. Importá la descarga como paquete de configuración.'\n    }:cura?{\n      process:'Adjuntá un .curaprofile exportado de Cura para tu máquina. Importá la descarga en Preferencias → Perfiles.',\n      filament:'Adjuntá un .xml.fdm_material del mismo polímero. Importá la descarga desde Materiales. Los ajustes específicos de máquina del archivo base pueden tener prioridad.',\n      machine:'Adjuntá la definición .def.json de tu impresora. La descarga conserva el nombre de archivo para usarla como respaldo e instalarla con sus definiciones de extrusor, según la guía de Cura.'\n    }:{\n      process:'Descargá el JSON directamente. En el laminador, seleccioná tu impresora y boquilla antes de importar el proceso. Si querés conservar ajustes propios, podés adjuntar un preset base.',\n      filament:'Descargá el JSON directamente y verificá la placa y las temperaturas en el laminador. Si querés conservar ajustes propios, podés adjuntar un preset del mismo polímero.',\n      machine:'Adjuntá un JSON de máquina de usuario de este laminador, para '+model+' y boquilla de 0,4 mm. Se conservan geometría, firmware y G-code de la base. Importá el JSON generado y verificá esos datos antes de imprimir.'\n    };\n    panel.querySelector('.instructions').textContent=instructions[type];\n    file.value='';\n    plate.querySelector('select').value=optionalBase&&type==='filament'?'textured_plate':'keep';\n    status.textContent='';\n  }\n  file.onchange=()=>{\n    if(!plate.hidden) plate.querySelector('select').value=file.files.length?'keep':'textured_plate';\n  };\n  select.onchange=explain;\n  kind.onchange=explain;\n  panel.querySelector('button').onclick=async()=>{\n    status.textContent='';\n    try {\n      const v=exportValues(selection);\n      const type=kind.value, target=select.value, base=file.files[0];\n      const slug=normalize(type==='process'?v.name:type==='machine'?model:'utilitools-'+v.polymer+'-'+v.nozzle).replace(/[^a-z0-9]+/g,'-').replace(/-$/,'');\n      if(type==='machine'&&selection.printer==='all') throw new Error('Seleccioná una impresora arriba para exportar su configuración de máquina.');\n      const needsBase=type==='machine'||target==='cura';\n      if(needsBase&&!base) throw new Error(type==='machine'?'Para exportar la máquina, elegí su preset base. Así se conservan las dimensiones, el firmware y el G-code.':'Cura necesita su archivo base para vincular el perfil con tu configuración. También podés usar Copiar parámetros.');\n      if(base&&base.size>2000000) throw new Error('El archivo base supera los 2 MB.');\n      if(target==='prusa') {\n        const preset=type==='machine'?makePrusaMachine(await base.text(),model):makePrusaBundle(v,type);\n        downloadPreset(slug+'-'+type+'.ini',preset,'text/plain');\n      } else if(target==='cura'&&type==='process') {\n        downloadPreset(slug+'.curaprofile',await makeCuraPreset(await base.arrayBuffer(),v),'application/zip');\n      } else if(target==='cura'&&type==='filament') {\n        downloadPreset(slug+'.xml.fdm_material',makeCuraMaterial(await base.text(),v),'application/xml');\n      } else if(target==='cura') {\n        const definition=JSON.parse(await base.text());\n        if(!base.name.endsWith('.def.json') || !definition?.name || !definition?.inherits || definition.metadata?.type==='extruder') throw new Error('Elegí la definición .def.json de la máquina.');\n        downloadPreset(base.name,JSON.stringify(stripPrivateKeys(definition),null,2)+'\\n','application/json');\n      } else {\n        const parsed=base?JSON.parse(await base.text()):standaloneJsonBase(target,type,v);\n        const plateKey=plate.querySelector('select').value;\n        const preset=type==='process'?makeJsonPreset(parsed,v):makeTypedJson(parsed,v,type,plateKey,model);\n        downloadPreset(slug+'-'+target+'-'+type+'.json',preset,'application/json');\n      }\n      status.textContent='Archivo generado. Verificá la importación y laminá una muestra.';\n    } catch(error) {\n      status.textContent=error instanceof SyntaxError?'El archivo no contiene JSON válido.':error.message;\n    }\n  };\n  explain();\n}\n\nasync function readCuraZip(buffer) {\n  const bytes=new Uint8Array(buffer);\n  const view=new DataView(buffer);\n  const decoder=new TextDecoder();\n  let end=bytes.length-22;\n  while(end>=Math.max(0,bytes.length-65557) && view.getUint32(end,true)!==0x06054b50) end--;\n  if(end<Math.max(0,bytes.length-65557)) throw new Error('El archivo no es un perfil exportado por Cura.');\n  const count=view.getUint16(end+10,true);\n  if(!count || count>16) throw new Error('El archivo no tiene la estructura de un perfil de Cura.');\n  let offset=view.getUint32(end+16,true);\n  const entries=[];\n  for(let i=0;i<count;i++) {\n    if(view.getUint32(offset,true)!==0x02014b50) throw new Error('El índice del perfil está dañado.');\n    const method=view.getUint16(offset+10,true);\n    const size=view.getUint32(offset+20,true);\n    const expanded=view.getUint32(offset+24,true);\n    const length=view.getUint16(offset+28,true);\n    const name=decoder.decode(bytes.subarray(offset+46,offset+46+length));\n    const local=view.getUint32(offset+42,true);\n    if(expanded>250000 || ![0,8].includes(method) || view.getUint32(local,true)!==0x04034b50) throw new Error('Entrada de perfil no compatible.');\n    const start=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true);\n    const payload=bytes.subarray(start,start+size);\n    let content=payload;\n    if(method===8) {\n      const reader=new Blob([payload]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();\n      const chunks=[];\n      let total=0;\n      while(true) {\n        const {done,value}=await reader.read();\n        if(done) break;\n        total+=value.length;\n        if(total>250000){await reader.cancel();throw new Error('Entrada de perfil demasiado grande.');}\n        chunks.push(value);\n      }\n      content=new Uint8Array(await new Blob(chunks).arrayBuffer());\n    }\n    if(content.length!==expanded) throw new Error('El tamaño de la entrada del perfil es incorrecto.');\n    entries.push([name,decoder.decode(content)]);\n    offset+=46+length+view.getUint16(offset+30,true)+view.getUint16(offset+32,true);\n  }\n  return entries;\n}\nfunction writeCuraZip(entries) {\n  const encode=new TextEncoder();\n  const chunks=[], directory=[];\n  let offset=0, directorySize=0;\n  for(const [name,text] of entries) {\n    const path=encode.encode(name), data=encode.encode(text);\n    let checksum=0xffffffff;\n    for(const byte of data) {\n      checksum^=byte;\n      for(let i=0;i<8;i++) checksum=(checksum>>>1)^((checksum&1)?0xedb88320:0);\n    }\n    checksum^=0xffffffff;\n    const header=new DataView(new ArrayBuffer(30));\n    const record=new DataView(new ArrayBuffer(46));\n    for(const [view,signature,start] of [[header,0x04034b50,0],[record,0x02014b50,2]]) {\n      view.setUint32(0,signature,true);\n      view.setUint16(4+start,20,true);\n      view.setUint16(6+start,0x800,true);\n      view.setUint32(14+start,checksum,true);\n      view.setUint32(18+start,data.length,true);\n      view.setUint32(22+start,data.length,true);\n      view.setUint16(26+start,path.length,true);\n    }\n    record.setUint16(4,20,true);\n    record.setUint32(42,offset,true);\n    chunks.push(header.buffer,path,data);\n    directory.push(record.buffer,path);\n    offset+=30+path.length+data.length;\n    directorySize+=46+path.length;\n  }\n  const end=new DataView(new ArrayBuffer(22));\n  end.setUint32(0,0x06054b50,true);\n  end.setUint16(8,entries.length,true);\n  end.setUint16(10,entries.length,true);\n  end.setUint32(12,directorySize,true);\n  end.setUint32(16,offset,true);\n  return new Blob([...chunks,...directory,end.buffer]);\n}\nasync function makeCuraPreset(buffer,v) {\n  const entries=await readCuraZip(buffer);\n  const globals={layer_height:v.layer,layer_height_0:v.first,support_enable:'False',xy_offset_layer_0:-v.elephant};\n  const extrusion={\n    wall_line_width_0:.42,wall_line_count:v.walls,top_layers:v.shells,bottom_layers:v.shells,\n    infill_sparse_density:v.infill,infill_pattern:'gyroid',speed_wall_0:v.outer,speed_wall_x:v.inner,\n    speed_print_layer_0:25,support_top_distance:v.gap\n  };\n  const updated=entries.map(([name,text])=>{\n    const lines=text.replace(/\\r\\n/g,'\\n').trimEnd();\n    if(!/^type\\s*=\\s*quality_changes\\s*$/m.test(lines) || !/^\\[values\\]\\s*$/m.test(lines)) throw new Error('Exportá un perfil personalizado desde Cura y volvé a adjuntarlo.');\n    const single=entries.length===1;\n    const isExtruder=/^position\\s*=\\s*\\d+\\s*$/m.test(lines);\n    const patch=single?{...globals,...extrusion}:isExtruder?extrusion:globals;\n    const keys={...globals,...extrusion};\n    const renamed=lines.replace(/^name\\s*=.*$/m,'name = '+v.name);\n    const clean=renamed.split('\\n').filter(line=>!Object.hasOwn(keys,line.split('=')[0].trim())).join('\\n');\n    return [name,clean+'\\n'+Object.entries(patch).map(pair=>pair.join(' = ')).join('\\n')+'\\n'];\n  });\n  return writeCuraZip(updated);\n}\n","/herramientas/guias/calibrar-filamento.html":"<!doctype html><html lang=\"es-AR\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo calibrar una bobina de filamento · UtiliTools</title><meta name=\"description\" content=\"Probá temperatura, caudal y tolerancia con muestras cortas antes de imprimir un lote.\"><link rel=\"stylesheet\" href=\"/herramientas/site.css\">\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo calibrar una bobina de filamento</h1><p class=\"intro\">Probá temperatura, caudal y tolerancia con muestras cortas antes de imprimir un lote.</p><section class=\"help\"><h2>Registrá la configuración de partida</h2><p>Anotá marca, material, color, boquilla, placa y ruta de alimentación. Guardá una copia del preset del laminador. Si cambiás a la vez bobina, altura de capa y velocidad, después es difícil atribuir la diferencia a una sola variable.</p></section><section class=\"help\"><h2>Ajustá temperatura y caudal</h2><p>Tomá el rango de temperatura de la bobina. Compará puentes, detalle y unión entre capas en una torre. Con esa temperatura, buscá el punto en que empiezan a aparecer zonas opacas, discontinuas o claramente subextruidas en una prueba de caudal volumétrico. Usá un límite conservador y repetí con una pieza de pared larga.</p></section><section class=\"help\"><h2>Afiná flujo y tolerancia según el resultado</h2><p>Si las caras sólidas dejan surcos o rebordes, probá el ajuste de flujo. Si el problema aparece al frenar y acelerar, revisá el pressure advance. Para un encastre, medí agujero y eje fríos con calibre y anotá el resultado antes de compensar el contorno.</p></section><section class=\"help\"><h2>Validá la pieza real</h2><p>Imprimí una muestra de la misma orientación y material que vas a vender. Registrá tiempo real, gramos totales y qué condición define una pieza aceptable. Si cambiás de lote de bobina, repetí el control que más afecte el producto.</p></section><p><a href=\"https://github.com/OrcaSlicer/OrcaSlicer/wiki/calibration_guide\">Guía de calibración de OrcaSlicer</a></p><aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento y guardarlo bien</a></li><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta</a></li><li><a href=\"/guias/boquillas.html\">Qué boquilla usar: tamaño y material</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/repuestos/\">Repuestos</a> · <a href=\"__SEARCH_HOME__categorias/diy-taller/\">DIY y taller</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main><footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>","/herramientas/guias/costos-de-impresion.html":"<!doctype html><html lang=\"es-AR\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo calcular el costo real de una impresión 3D · UtiliTools</title><meta name=\"description\" content=\"Separá la fabricación, los costos por venta y el margen antes de ponerle precio a un lote.\"><link rel=\"stylesheet\" href=\"/herramientas/site.css\">\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo calcular el costo real de una impresión 3D</h1><p class=\"intro\">Separá la fabricación, los costos por venta y el margen antes de ponerle precio a un lote.</p><section class=\"help\"><h2>Medí lo que consume el lote</h2><p>Anotá gramos, incluida la torre de purga, y horas de impresión. Si usás dos materiales, calculá cada uno por separado. Medí el consumo medio si querés estimar electricidad. Potencia máxima de la fuente y consumo medio son medidas distintas.</p></section><section class=\"help\"><h2>Separá los costos</h2><p>Incluí el tiempo de retirar soportes, ensamblar, revisar y preparar la venta. Sumá el embalaje por unidad y el cargo fijo o envío por pedido. Si estimás fallos por intento, anotá si los fallos suelen ocurrir al principio o al final, porque su costo puede diferir del de una tanda completa.</p></section><section class=\"help\"><h2>Calculá el punto de equilibrio</h2><p>Si un pedido cuesta $8.000 y la comisión es 15% del precio, el equilibrio es $8.000 dividido por 0,85. Para buscar 25% de margen sobre la venta, dividí por 0,60. El precio resultante ronda $13.334 antes de cargos que hayas omitido.</p></section><section class=\"help\"><h2>Contrastá con una venta real</h2><p>Guardá la liquidación y compará el dinero recibido con tu estimación. Si el producto ocupa la impresora durante cinco horas, anotá el margen por hora de máquina para compararlo con otros pedidos.</p></section><p><a href=\"https://vendedores.mercadolibre.com.ar/aprender/nota/como-funcionan-los-costos-de-mercado-libre\">Costos de venta de Mercado Libre</a></p><aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D en Argentina</a></li><li><a href=\"/guias/multicolor.html\">Impresión multicolor con menos purga</a></li><li><a href=\"/guias/mantenimiento.html\">Mantenimiento básico de la impresora 3D</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/llaveros/\">Llaveros</a> · <a href=\"__SEARCH_HOME__categorias/organizacion/\">Organización</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main><footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>","/herramientas/guias/fidgets-y-holguras.html":"<!doctype html><html lang=\"es-AR\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo lograr que un fidget gire al salir de la cama · UtiliTools</title><meta name=\"description\" content=\"Una prueba de holguras para bisagras, correderas y aros impresos en una sola pieza.\"><link rel=\"stylesheet\" href=\"/herramientas/site.css\">\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo lograr que un fidget gire al salir de la cama</h1><p class=\"intro\">Una prueba de holguras para bisagras, correderas y aros impresos en una sola pieza.</p><section class=\"help\"><h2>Identificá dónde se traba</h2><p>Si se unió solo al tocar la cama, mirá el pie de elefante. Si se bloquea arriba, mirá si un puente cayó sobre el eje. Si roza en un punto fijo durante el giro, inspeccioná la costura y las rebabas.</p></section><section class=\"help\"><h2>Armá una prueba de tres holguras</h2><p>Para una articulación de PLA con boquilla de 0,4 mm, probá 0,30, 0,35 y 0,40 mm entre caras en XY. En un eje impreso aparte, usá diferencia entre diámetros. Un agujero de 5,40 mm sobre un eje de 5,00 mm deja 0,20 mm por lado si ambos quedan centrados.</p></section><section class=\"help\"><h2>Revisá el laminado por capas</h2><p>Buscá trayectorias que unan caras móviles y soportes dentro del mecanismo. Si hay una tapa sobre el eje, comprobá la separación efectiva en Z en la vista previa. Si podés, rediseñá la pieza con una rampa o dividila para imprimir el eje por separado.</p></section><section class=\"help\"><h2>Hacé una tanda corta</h2><p>Dejá enfriar la impresión. Probá que se libere a mano, gire en todo su recorrido y mantenga el tacto después de varios ciclos. Repetí con varias unidades en la misma placa antes de vender un lote.</p></section><p><a href=\"https://github.com/OrcaSlicer/OrcaSlicer/wiki/tolerance_calib\">Pruebas de tolerancia de OrcaSlicer</a></p><aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta</a></li><li><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento</a></li><li><a href=\"/guias/tpu-flexibles.html\">Cómo imprimir TPU y filamentos flexibles</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/juguetes/\">Juguetes</a> · <a href=\"__SEARCH_HOME__categorias/electronica/\">Electrónica</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main><footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>","/herramientas/index.html":"<!doctype html>\n<html lang=\"es-AR\">\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>UtiliTools · Perfiles, materiales y herramientas para makers</title>\n<meta name=\"description\" content=\"Consultá perfiles de impresión 3D, compará filamentos, exportá ajustes para tu laminador y calculá el costo de tus piezas en pesos argentinos.\">\n<meta name=\"theme-color\" content=\"#101419\">\n<link rel=\"stylesheet\" href=\"/herramientas/site.css\">\n<body id=\"inicio\"><a class=\"skip\" href=\"#perfiles\">Ir al buscador de perfiles</a>\n<header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<section class=\"hero\"><div class=\"wrap hero-inner\"><div class=\"hero-copy\"><p class=\"kicker\">IMPRESIÓN 3D PARA MAKERS</p><h1>De la primera capa<br> <em>a la pieza final.</em></h1><p>Encontrá un perfil para tu impresora, elegí el filamento y calculá cuánto te cuesta fabricar la pieza.</p><div class=\"hero-actions\"><a class=\"button primary\" href=\"#perfiles\">Explorar perfiles</a><a class=\"button secondary\" href=\"#costos\">Calcular un costo</a></div></div><div class=\"visual\"><img src=\"/herramientas/assets/portada-640.webp\" srcset=\"/herramientas/assets/portada-640.webp 640w, /herramientas/assets/portada-1120.webp 1120w\" sizes=\"(max-width: 660px) calc(100vw - 28px), (max-width: 1268px) 42vw, 505px\" width=\"640\" height=\"480\" fetchpriority=\"high\" decoding=\"async\" alt=\"Una impresora 3D deposita filamento sobre el borde de un florero violeta con textura en espiral.\"></div></div></section>\n<main class=\"wrap\"><section id=\"perfiles\" class=\"workspace\" aria-labelledby=\"profileTitle\"><div class=\"workspace-heading\"><div><h2 id=\"profileTitle\">Perfiles de impresión</h2><p>Elegí un tipo de pieza y filtrá por máquina o material. Cada ficha incluye una base de impresión y consejos para sus variantes.</p></div><button class=\"quiet\" id=\"clearFilters\" type=\"button\">Limpiar filtros</button></div>\n\n<div class=\"filters search-panel\">\n<label>Impresora<select id=\"printer\"></select></label>\n<label>Material<select id=\"material\"></select></label>\n<label>Categoría<select id=\"category\"></select></label>\n<label>Buscar perfil<input id=\"search\" type=\"search\" placeholder=\"Ej. macetas, figuras, fidgets…\"></label>\n</div>\n<div class=\"notice\" id=\"context\">Elegí una impresora para consultar sus recomendaciones. Parámetros iniciales para boquilla de 0,4 mm.</div>\n<div class=\"catalog\"><section aria-labelledby=\"catalog-title\"><h2 id=\"catalog-title\">Catálogo <span class=\"muted mono\" id=\"count\"></span></h2><div class=\"list\" id=\"list\"></div></section><section class=\"detail\" id=\"detail\" aria-label=\"Parámetros del perfil\" tabindex=\"-1\"></section></div>\n</section>\n<details class=\"help top\" id=\"impresoras\"><summary>Top 10 impresoras FDM · selección editorial</summary><p>Selección de noviembre de 2026 basada en reseñas y guías, con opciones para distintos usos. Los precios y la disponibilidad en Argentina pueden variar.</p>\n<ol><li><b>Bambu Lab A1</b> · Inicio y uso general</li><li><b>Bambu Lab P2S</b> · Cerrada para uso general</li><li><b>Bambu Lab X2D</b> · Gama media y multimaterial</li><li><b>Prusa CORE One+</b> · Prototipado y ecosistema Prusa</li><li><b>Elegoo Centauri Carbon 2</b> · Cerrada de precio competitivo</li><li><b>QIDI Q2</b> · Materiales técnicos</li><li><b>Anycubic Kobra S1 Combo</b> · Multicolor en máquina cerrada</li><li><b>Snapmaker U1</b> · Cambio de herramientas</li><li><b>Creality K2 Plus</b> · Piezas grandes</li><li><b>Bambu Lab H2D</b> · Doble boquilla</li></ol>\n<p><a href=\"https://www.tomshardware.com/best-picks/best-3d-printers\">Tom’s Hardware</a> · <a href=\"https://www.techradar.com/best/best-3d-printers\">TechRadar</a> · <a href=\"https://simplyprint.io/es/articles/best-3d-printer\">SimplyPrint</a> · <a href=\"https://deal3d.com/en/top-lists/best-3d-printers\">Deal3D</a></p></details>\n<section class=\"help\" id=\"materiales\"><h2>Biblioteca de filamentos</h2><p>Consultá el uso recomendado y los requisitos del material. Las temperaturas son puntos de partida. La ficha de cada bobina y los límites de tu máquina tienen prioridad.</p><div id=\"materialCatalog\"></div><p><a href=\"https://help.prusa3d.com/es/filament-material-guide\">Guía de materiales de Prusa</a> · <a href=\"https://wiki.creality.com/en/cfs/cfs-filament-compatibility\">Compatibilidad del CFS original</a></p></section>\n<section class=\"help\" id=\"tecnicas\"><h2>Guías de impresión</h2><p>Elegí una técnica para calibrar, diseñar un encastre o mejorar el acabado.</p><div class=\"guide-grid editorial-links\"><article><h3><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir</a></h3><p>Diferencias de temperatura, resistencia y acabado, y qué material conviene para cada pieza.</p></article><article><h3><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta</a></h3><p>Diagnóstico visual, Z offset, limpieza y nivelación para que la pieza no se despegue.</p></article><article><h3><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento</a></h3><p>Señales de humedad, temperaturas por material y cómo guardar las bobinas.</p></article><article><h3><a href=\"/guias/warping.html\">Warping: por qué se levanta la pieza</a></h3><p>Adhesión, enfriamiento, brim y diseño para que las esquinas no se curven.</p></article><article><h3><a href=\"/guias/hilos-stringing.html\">Cómo eliminar los hilos</a></h3><p>Secado, torre de temperatura, retracción y recorridos, en ese orden.</p></article><article><h3><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento</a></h3><p>Probá temperatura, caudal y tolerancia con muestras cortas antes de imprimir un lote.</p></article><article><h3><a href=\"/guias/fidgets-y-holguras.html\">Cómo lograr que un fidget gire al salir de la cama</a></h3><p>Una prueba de holguras para bisagras, correderas y aros impresos en una sola pieza.</p></article><article><h3><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D</a></h3><p>Cómo armar el precio con material, máquina, tiempo, fallos y comisión, con un ejemplo en pesos.</p></article><article><h3><a href=\"/guias/costos-de-impresion.html\">Cómo calcular el costo real de una impresión 3D</a></h3><p>Separá la fabricación, los costos por venta y el margen antes de ponerle precio a un lote.</p></article><article><h3><a href=\"/guias/vender-en-mercado-libre.html\">Cómo vender impresiones 3D en Mercado Libre</a></h3><p>Costos de venta, publicaciones que venden, embalaje y propiedad intelectual.</p></article><article><h3><a href=\"/guias/licencias-modelos-3d.html\">Licencias de modelos 3D: qué podés vender</a></h3><p>Creative Commons, licencias de plataformas, marcas y cómo citar al autor.</p></article><article><h3><a href=\"/guias/soportes.html\">Soportes fáciles de retirar</a></h3><p>Normales o en árbol, distancias, interfaz y el truco del PETG.</p></article><article><h3><a href=\"/guias/multicolor.html\">Multicolor con menos purga</a></h3><p>Cambio por capa, multimaterial y cómo desperdiciar menos filamento.</p></article><article><h3><a href=\"/guias/tpu-flexibles.html\">Cómo imprimir TPU y flexibles</a></h3><p>Dureza, extrusor, velocidad y cuidados para que no se trabe.</p></article><article><h3><a href=\"/guias/boquillas.html\">Qué boquilla usar</a></h3><p>Tamaños, latón o acero endurecido y cuándo cambiarla.</p></article><article><h3><a href=\"/guias/mantenimiento.html\">Mantenimiento básico de la impresora</a></h3><p>Rutina, lubricación, correas, atascos y seguridad.</p></article></div><details><summary>Calibrar una bobina nueva</summary><p>Empezá por temperatura y caudal volumétrico. Ajustá pressure advance y flujo con muestras del laminador. Afiná retracción y tolerancias al final.</p><a href=\"https://github.com/OrcaSlicer/OrcaSlicer/wiki/calibration_guide\">Guía de calibración de OrcaSlicer</a></details><details><summary>Soportes más fáciles de retirar</summary><p>Reorientá o dividí la pieza para dejar los soportes fuera de los encastres. Para empezar, probá dos capas de interfaz y una distancia Z superior de 0,24 mm en PLA o 0,28–0,32 mm en PETG. Revisá la separación efectiva en la vista previa.</p></details><details><summary>Bisagras y encastres móviles</summary><p>Para una bisagra impresa en PLA, probá 0,30, 0,35 y 0,40 mm entre caras en XY. Medí con calibre y ajustá una variable por vez. Si se pega solo abajo, revisá la primera capa.</p></details><details><summary>Multicolor con menos purga</summary><p>Cuando el diseño lo permita, concentrá el cambio de color en las capas del logo. Compará gramos de pieza y purga antes de imprimir la tanda.</p></details><details><summary>Orientación y acabado</summary><p>Ubicá la cara visible lejos de las marcas de soporte y la costura lejos del encastre. Para clips, orientá la flexión principal en el plano de las capas y ensayá el retorno.</p></details></section>\n<section class=\"help\" id=\"diagnostico\"><h2>Diagnóstico por síntoma</h2><details><summary>El CFS empuja el tubo y se sale el acople</summary><p>Cancelá la carga. Revisá que el tubo esté insertado y que el acople lo retenga. Contrastá el recorrido con el manual de tu kit y probá la carga supervisada. Si vuelve a expulsarlo, verificá el sistema de alimentación con la guía de Creality.</p><a href=\"https://wiki.creality.com/en/k1-flagship-series/CFSUK\">Soporte oficial del kit K1 + CFS</a></details><details><summary>La pieza se levanta de la cama</summary><p>Limpiá la placa según el fabricante, verificá la primera capa y probá un brim si la geometría tiene poco contacto.</p></details><details><summary>Hay hilos entre partes</summary><p>Usá una muestra chica con la bobina seca. Probá temperaturas dentro del rango del fabricante y recién después ajustá retracción.</p></details><details><summary>El mecanismo sale trabado</summary><p>Dejalo enfriar. Revisá si se pegó solo en la base, si hay rebabas en el eje o si el modelo tiene holgura insuficiente. Repetí una unión de prueba antes de imprimir el lote.</p></details></section>\n<section class=\"help\" id=\"costos\"><h2>Calculadora para makers</h2><p>Calculá cuánto cuesta fabricar un lote y qué precio cobrar por el pedido. Importes en pesos argentinos.</p><p id=\"costModel\" hidden><span></span> <a href=\"https://www.utilitools.com.ar/#catalogo\" target=\"_blank\" rel=\"noopener noreferrer\">Ver ficha original ↗</a></p><div class=\"quote-box\"><h2 class=\"box-title\">Importar datos del laminador</h2><p>Creality Print, OrcaSlicer y Bambu Studio. Elegí o arrastrá acá un archivo .gcode o una placa laminada .gcode.3mf. El archivo se lee en tu navegador.</p><label for=\"slicer-file\">Archivo de impresión</label><div class=\"file-picker\"><input id=\"slicer-file\" class=\"file-input\" type=\"file\" accept=\".gcode,.3mf\" aria-describedby=\"slicer-file-name\"><label for=\"slicer-file\" class=\"file-button\" aria-hidden=\"true\">Elegir archivo</label><span id=\"slicer-file-name\" class=\"file-name\">Ningún archivo seleccionado</span></div><label hidden>Placa <select id=\"slicer-plate\"></select></label><p id=\"import-status\" role=\"status\"></p></div><form id=\"costForm\" class=\"filters\"><label>Filamento principal, gramos con purga<input name=\"grams\" type=\"number\" min=\"0\" step=\"any\" value=\"100\" required></label><label>Filamento principal, precio por kg<input name=\"spool\" type=\"number\" min=\"0\" step=\"any\" value=\"22000\" required></label><label>Segundo material, gramos con purga<input name=\"extraGrams\" type=\"number\" min=\"0\" step=\"any\" value=\"0\" required></label><label>Segundo material, precio por kg<input name=\"extraSpool\" type=\"number\" min=\"0\" step=\"any\" value=\"0\" required></label><label>Horas de impresión por intento<input name=\"hours\" type=\"number\" min=\"0\" step=\"any\" value=\"2\" required></label><label>Desgaste y mantenimiento por hora<input name=\"hour\" type=\"number\" min=\"0\" step=\"any\" value=\"700\" required></label><label>Consumo medio de la impresora, W<input name=\"watts\" type=\"number\" min=\"0\" step=\"any\" value=\"100\" required></label><label>Tarifa eléctrica por kWh<input name=\"kwh\" type=\"number\" min=\"0\" step=\"any\" value=\"0\" required></label><label>Minutos de trabajo manual por intento<input name=\"laborMinutes\" type=\"number\" min=\"0\" step=\"any\" value=\"0\" required></label><label>Valor de tu hora de trabajo<input name=\"laborRate\" type=\"number\" min=\"0\" step=\"any\" value=\"0\" required></label><label>Unidades del lote y pedido<input name=\"units\" type=\"number\" min=\"1\" step=\"1\" value=\"1\" required></label><label>Intentos fallidos estimados (%)<input name=\"failure\" type=\"number\" min=\"0\" max=\"99\" step=\"any\" value=\"5\" required></label><label>Embalaje e insumos por unidad<input name=\"packing\" type=\"number\" min=\"0\" step=\"any\" value=\"500\" required></label><label>Cargo fijo y envío por pedido<input name=\"fixed\" type=\"number\" min=\"0\" step=\"any\" value=\"0\" required></label><label>Comisión sobre la venta (%)<input name=\"fee\" type=\"number\" min=\"0\" max=\"99\" step=\"any\" value=\"0\" required></label><label>Margen objetivo sobre la venta (%)<input name=\"margin\" type=\"number\" min=\"0\" max=\"99\" step=\"any\" value=\"30\" required></label></form><output id=\"costResult\" aria-live=\"polite\"></output><div class=\"quote-box\" id=\"quote-tools\" hidden><h2 class=\"box-title\">Guardar costos y armar un presupuesto</h2><label>Nombre del trabajo <input id=\"quote-name\" maxlength=\"120\" placeholder=\"Ej. Llaveros para un evento\"></label><div class=\"quote-actions\"><button type=\"button\" id=\"save-costs\">Guardar mis costos</button><button type=\"button\" id=\"copy-quote\">Copiar para WhatsApp</button><button type=\"button\" id=\"download-quote\">Descargar .txt</button></div><label hidden>Presupuesto <textarea id=\"quote-text\" readonly rows=\"5\"></textarea></label><p id=\"settings-status\" role=\"status\"></p></div><p class=\"notice\">Usá los gramos y tiempos del laminador y un consumo medio medido. El cálculo supone que un intento fallido cuesta igual que uno exitoso. El embalaje se aplica a unidades vendibles y los cargos de envío y venta se aplican al pedido. Si hay impuestos u otros cargos, incorporalos a los costos según corresponda.</p></section>\n<section class=\"help\" id=\"modelos\"><h2>Bibliotecas de modelos 3D</h2><p>Buscá diseños en los sitios originales y revisá la licencia de cada modelo antes de vender impresiones o redistribuir archivos. En modelos con atribución, guardá el nombre del autor y el enlace original.</p>\n<ul><li><a href=\"https://www.printables.com/\">Printables</a></li><li><a href=\"https://makerworld.com/\">MakerWorld</a></li><li><a href=\"https://www.thingiverse.com/\">Thingiverse</a></li><li><a href=\"https://thangs.com/\">Thangs</a></li><li><a href=\"https://www.myminifactory.com/\">MyMiniFactory</a></li><li><a href=\"https://www.crealitycloud.com/\">Creality Cloud</a></li></ul>\n<p><a href=\"https://creativecommons.org.ar/licencias/\">Qué permite cada licencia Creative Commons</a> · <a href=\"https://forum.bambulab.com/t/empowering-our-creators-with-new-commercial-license-membership/145511\">Licencias de impresión comercial en MakerWorld</a></p></section>\n<details class=\"help\" id=\"guia\"><summary>Cómo calibrar y consultar fuentes</summary>\n<ul><li>Duplicá el perfil de máquina y de filamento en tu laminador. Las fichas son valores iniciales para boquilla de 0,4 mm. Conservá los límites de máquina, la retracción y la calibración de flujo de tu combinación.</li><li>Probá primero una pieza corta. Si la geometría tiene encastres, repetí la prueba con la misma orientación y medí antes de tocar compensaciones XY.</li><li>Si el CFS expulsa el tubo durante la carga, probá las piezas de un color con la bobina externa cuando tu configuración lo permita. El cambio de color aumenta el tiempo y el material de purga.</li><li>Para costos, tomá gramos y duración de la vista previa del laminador, incluida la purga, y contrastalos con un lote real.</li></ul>\n<p><a href=\"https://wiki.creality.com/en/k1-flagship-series/CFSUK\">Kit K1 + CFS</a> · <a href=\"https://wiki.creality.com/en/cfs/cfs-filament-compatibility\">Compatibilidad CFS</a> · <a href=\"https://github.com/OrcaSlicer/OrcaSlicer/wiki/quality_settings_precision\">Precisión en OrcaSlicer</a> · <a href=\"https://github.com/OrcaSlicer/OrcaSlicer/wiki/tolerance_calib\">Prueba de tolerancias</a> · <a href=\"https://printalot.com.ar/categoria-producto/filamentos/pet-g/\">PETG PrintaLot</a> · <a href=\"https://www.argentina.gob.ar/normativa/nacional/resoluci%C3%83%C2%B3n-16-2025-410052\">Reglamento argentino de seguridad eléctrica</a></p>\n</details>\n<section class=\"help info\" id=\"acerca\"><h2>Acerca de UtiliTools</h2><p>UtiliTools reúne parámetros de partida, guías y herramientas para impresión FDM. Indicamos cuándo un valor debe calibrarse con una muestra y enlazamos las fuentes técnicas para que puedas comprobarlo.</p></section>\n<section class=\"help info\" id=\"privacidad\"><h2>Privacidad</h2><p>La calculadora y la conversión de archivos se ejecutan en el navegador. Los presets que adjuntás para convertir se procesan en tu dispositivo. Los enlaces externos se rigen por la política de cada sitio.</p><p>Las palabras que escribís en el buscador de modelos se envían a las fuentes de búsqueda habilitadas para obtener resultados.</p></section></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer>\n<script src=\"/herramientas/materials.js\"></script>\n<script src=\"/herramientas/exports.js\"></script>\n<script src=\"/herramientas/app.js\"></script>\n</body>\n</html>\n","/herramientas/materials.js":"const materials = {\n  pla: ['PLA',210,55,'80–100%',90,'PLA','Uso general','Figuras, prototipos y fidgets. Probá el encastre con la bobina que vas a usar.'],\n  hyper: ['Hyper PLA',215,55,'80–100%',90,'PLA','Uso general','Para tandas rápidas. Calibrá el caudal volumétrico antes de subir velocidad.'],\n  plaplus: ['PLA+',215,55,'70–100%',80,'PLA','Uso general','Las formulaciones varían por marca. Ajustá la temperatura con la ficha de tu bobina.'],\n  matte: ['PLA mate',210,55,'70–100%',65,'PLA','Acabados','Para macetas y decoración. Probá adhesión entre capas en piezas finas.'],\n  silk: ['PLA silk',220,55,'65–90%',45,'PLA','Acabados','Para acabados brillantes. Mantené pareja la velocidad de la pared exterior.'],\n  petg: ['PETG',240,75,'30–50%',65,'PETG','Uso general','Para repuestos y piezas funcionales. Si aparecen hilos, comprobá humedad y temperatura.'],\n  petght: ['PETG HT',255,80,'20–40%',50,'PETG','Técnicos','PETG de mayor resistencia térmica según formulación. Verificá temperatura y ventilación con el fabricante.'],\n  abs: ['ABS',250,95,'0–20%',60,'ABS','Técnicos','Para carcasas y piezas interiores. Usá cámara adecuada y ventilación o extracción según tu equipo.'],\n  asa: ['ASA',255,95,'0–20%',55,'ASA','Técnicos','Para piezas expuestas al sol. Usá cámara adecuada y ventilación o extracción según tu equipo.'],\n  tpu: ['TPU 95A',225,45,'30–60%',30,'TPU','Flexibles','Para topes, clips y fundas. En el CFS original usá alimentación externa compatible.'],\n  tpe: ['TPE / TPU blando',null,null,null,null,null,'Flexibles','Seguí la ficha de dureza y temperatura. Requiere una ruta de extrusión apta para flexibles.'],\n  pa: ['PA / nylon',265,75,'0–20%',40,'PA','Técnicos','El nylon absorbe humedad. Secá e imprimí desde un contenedor seco según la ficha de la bobina.'],\n  pc: ['PC / policarbonato',270,105,'0–20%',40,'PC','Técnicos','Verificá los límites reales de boquilla, cama y placa. La formulación define si necesita cámara calefaccionada.'],\n  pp: ['PP / polipropileno',235,85,'0–20%',40,'PP','Técnicos','Requiere una superficie compatible con PP. Probá adherencia y contracción en una muestra pequeña.'],\n  hips: ['HIPS',235,95,'0–20%',45,'HIPS','Técnicos','Usalo según la ficha de la bobina y con ventilación adecuada. También existe como soporte separable para ABS.'],\n  pet: ['PET',255,80,'20–45%',45,'PET','Técnicos','Confirmá la ficha técnica de la formulación antes de aplicar el punto de partida.'],\n  placf: ['PLA-CF',220,55,'50–80%',55,'PLA-CF','Compuestos','Usá una boquilla resistente a la abrasión. Confirmá el diámetro mínimo que pide la bobina.'],\n  petgcf: ['PETG-CF',255,80,'20–45%',50,'PETG-CF','Compuestos','Para piezas rígidas y acabado mate. Verificá boquilla, alimentador y secado.'],\n  pacf: ['PA-CF / PA-GF',null,null,null,null,null,'Compuestos','Las variantes de nylon difieren mucho en temperatura y secado. Requieren boquilla resistente a la abrasión.'],\n  wood: ['PLA madera / cargas decorativas',null,null,null,null,null,'Acabados','La proporción de carga cambia la impresión. Elegí boquilla y temperatura según la bobina.'],\n  pva: ['PVA / BVOH',null,null,null,null,null,'Soportes','Para interfaces solubles en agua. Verificá compatibilidad térmica con el material principal y mantené la bobina seca.'],\n  breakaway: ['Soporte desprendible',null,null,null,null,null,'Soportes','Elegí una interfaz diseñada para el polímero principal y probá separación y acabado.'],\n  industrial: ['PEEK / PEI / PPS / PPA',null,null,null,null,null,'Industriales','Consultá la ficha exacta. Algunas formulaciones requieren equipo industrial o cámara calefaccionada.']\n};\nconst materialGroups = ['Uso general','Acabados','Flexibles','Técnicos','Compuestos','Soportes','Industriales'];\nconst materialNotes = {tpu:'Para la K1 con CFS original, usá la ruta externa apta para TPU.', abs:'Comprobá cámara y ventilación.', asa:'Comprobá cámara y ventilación.', pc:'Verificá los límites de cama y hotend.', placf:'Requiere boquilla resistente a abrasión.', petgcf:'Requiere boquilla resistente a abrasión.'};\n","/herramientas/site.css":":root{--bg:#f7f7fc;--panel:#fff;--ink:#211d38;--muted:#5b566e;--line:#e1deed;--purple:#5c39bb;--accent:#e5ff80;--dark:#15142b;--round:18px;color-scheme:light}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;scroll-padding-top:18px}\nbody{margin:0;color:var(--ink);background:var(--bg);font:15px/1.55 system-ui,sans-serif}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer}\na{color:var(--purple);text-underline-offset:3px}\n[hidden]{display:none!important}\n:focus-visible{outline:3px solid #8863ee;outline-offset:3px}\n.skip{position:absolute;top:-100px;left:18px;z-index:5;background:white;padding:8px}\n.skip:focus{top:8px}\n.wrap{width:min(1220px,100% - 48px);margin-inline:auto}\n.site-header{color:#fff;background:var(--dark);border-bottom:1px solid #ffffff19}\n.header-inner,.footer-inner{min-height:70px;display:flex;align-items:center;justify-content:space-between;gap:24px}\n.brand{display:inline-flex;align-items:center;gap:6px;color:inherit;text-decoration:none;font-size:21px;font-weight:780;letter-spacing:-.05em;white-space:nowrap}\n.brand>span:last-child{color:#aa98f4}\n.brand-mark{display:inline-grid;place-items:center;width:32px;height:32px;border-radius:9px;background:var(--accent);color:#17172b;font-size:19px;font-weight:850;margin-right:4px}\nnav,.footer-inner>div{display:flex;flex-wrap:wrap;gap:10px 24px}\nnav a,.footer-inner>div a{color:#ddd9ee;text-decoration:none;font-weight:600;font-size:14px}\nnav a:hover,.footer-inner>div a:hover{color:var(--accent)}\n.hero{overflow:hidden;color:#fff;background:radial-gradient(ellipse at 78% 105%,#392560 0%,transparent 65%),var(--dark)}\n.hero-inner{min-height:384px;display:grid;grid-template-columns:1.35fr 1fr;gap:40px;align-items:center;padding-block:42px}\n.hero-copy{position:relative;z-index:1}\n.kicker,.mono{font:700 12px/1.4 ui-monospace,monospace;letter-spacing:.035em}\n.kicker{color:#c1afff;margin:0 0 15px}\n.hero h1{font-size:clamp(45px,6vw,81px);line-height:.99;letter-spacing:-.08em;margin:0}\n.hero h1 em{font-style:normal;color:#c8b8ff}\n.hero-copy>p:not(.kicker){color:#e0dbec;max-width:47ch;font-size:17px;margin:20px 0}\n.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:25px}\n.button,.copy,.quiet{display:inline-flex;justify-content:center;align-items:center;gap:12px;border-radius:10px;padding:9px 14px;font-weight:750;text-decoration:none;border:1px solid transparent;transition:background .16s,border-color .16s}\n.primary{background:var(--accent);color:#202426}.primary:hover{background:#f0ffa8}\n.secondary{border-color:#ffffff55;color:#fff}.secondary:hover{background:#ffffff16}\n .visual{width:100%;overflow:hidden;border-radius:18px;border:1px solid #c1afff40;box-shadow:0 18px 55px #08061575;background:#100a22}\n.visual img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;object-position:center}\nmain{padding-block:32px 52px}\n.workspace-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:16px}\nh2{margin:0 0 5px;font-size:clamp(24px,3vw,33px);line-height:1.15;letter-spacing:-.045em}\n.workspace-heading p,.help>p{margin:0 0 12px;color:var(--muted)}\n.workspace-heading p{margin:0}\n.search-panel,.top,.help:not(.top){padding:19px;background:var(--panel);border:1px solid var(--line);border-radius:var(--round)}\n.filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}\n.filters label{display:grid;align-content:start;gap:6px;font-size:13px;font-weight:700}\ninput,select{width:100%;min-width:0;border:1px solid #cbc3dc;border-radius:9px;background:#fff;color:var(--ink);padding:9px;min-height:41px}\n.notice{font-size:13px;color:var(--muted);margin:12px 0}\n.catalog{display:grid;grid-template-columns:minmax(240px,1fr) minmax(0,1.55fr);gap:18px;margin-top:18px;align-items:start}\n.catalog>section:first-child{min-width:0}\n.catalog>section:first-child h2{font-size:19px;display:flex;justify-content:space-between;align-items:center;padding:0 3px 8px}\n.list{display:grid;gap:7px;max-height:550px;overflow:auto;padding:3px;overscroll-behavior:contain;scrollbar-color:#bdb0dc transparent}\n.item{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:10px;align-items:center;width:100%;min-height:61px;padding:9px;text-align:left;border:1px solid var(--line);border-radius:11px;color:var(--ink);background:#fff}\n.item:hover{border-color:#a494d4}\n.item[aria-pressed=true]{border-color:#9a84dd;background:#eee8ff}\n.item strong{display:block}.item small,.muted{color:var(--muted)}\n.icon{width:32px;height:32px;display:grid;place-items:center;border-radius:8px;background:#f0ebff;color:#6645bd;font-size:18px}.arrow{color:#7051bd;font-size:21px}\n.detail{overflow:hidden;border:1px solid var(--line);border-radius:var(--round);background:var(--panel);box-shadow:0 9px 24px #291a4910}\n.detail-head{padding:20px;background:linear-gradient(135deg,#f2edff,#e9e2ff)}\n.detail-head h2{margin:5px 0 7px}.detail-head p{margin:0}.detail-head .mono{color:#574095}\n.data{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;background:var(--line);margin:0;border-block:1px solid var(--line)}\n.data>div{padding:10px 12px;background:var(--panel)}.data dt{font-size:12px;color:var(--muted)}.data dd{margin:3px 0 0;font:650 13px/1.4 ui-monospace,monospace;overflow-wrap:anywhere}\n.notes{padding:15px 19px}.notes p{margin:0 0 9px}\n.copy{background:#5a39b2;color:white}.copy:hover{background:#493091}.quiet{background:#fff;border-color:#cec2ea;color:#563a9f}.quiet:hover{background:#f0eaff}.status{margin-left:8px;font-size:13px}.copybox{width:100%;margin-top:8px}\n.export{margin-top:12px;border:1px solid var(--line);border-radius:10px;padding:10px}.export label{display:block;margin:8px 0}.export summary,.help summary{cursor:pointer;font-weight:750}.export small{display:block;margin-top:5px}.export .error{color:#87251d}\n.help{margin-top:22px}.help details{padding:10px 0;border-top:1px solid var(--line)}.help details p{margin:8px 0}.help ol{columns:2;column-gap:28px}.help li{break-inside:avoid}.material-group>h3{margin:18px 0 6px}\n.guide-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(210px,100%),1fr));gap:9px}.guide-grid article{border:1px solid var(--line);padding:12px;border-radius:11px;background:#fcfbff}.guide-grid h4,.guide-grid p{margin:0 0 6px}.guide-grid small{display:block;color:var(--muted)}.guide-grid button{font-size:13px;padding:4px 8px;margin-top:8px}\n#costResult{display:block;margin-top:16px}#costResult p{font-weight:750}.site-footer{background:var(--dark);color:white}.footer-inner{padding-block:16px}\n@media(max-width:850px){.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.hero-inner{gap:16px}.hero h1{font-size:clamp(42px,7vw,62px)}}\n@media(max-width:660px){.wrap{width:calc(100% - 28px)}.header-inner,.footer-inner{flex-wrap:wrap;gap:9px;padding-block:11px;min-height:0}nav{gap:6px 12px}.hero-inner{grid-template-columns:1fr;padding-block:28px 13px}.visual{margin-top:2px;margin-bottom:8px}.visual img{aspect-ratio:3/2;object-position:center 55%}.hero h1{font-size:clamp(40px,10vw,57px)}.catalog{grid-template-columns:1fr}.list{max-height:230px}.workspace-heading{align-items:start}.workspace-heading .quiet{font-size:12px;padding:6px 8px;flex-shrink:0}.help ol{columns:1}.data{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}\n.editorial{max-width:790px;margin-inline:auto}.editorial h1{font-size:clamp(34px,6vw,58px);line-height:1.04;letter-spacing:-.07em;margin:14px 0}.editorial .intro{font-size:19px;color:var(--muted)}.editorial .help h2{font-size:22px}.editorial .help p{margin:0}.editorial-links{margin-bottom:15px}.editorial-links h3{margin:0 0 7px;font-size:17px}\n\nbody[data-tool] .hero { display: none; }\nbody[data-tool] main { padding-top: 24px; }\nbody[data-tool] main > :where(:not(#acerca):not(#privacidad)) { display: none; }\nbody[data-tool=\"calculadora\"] #costos,\nbody[data-tool=\"perfiles\"] :is(#perfiles,#impresoras,#materiales,#diagnostico,#guia),\nbody[data-tool=\"guias\"] :is(#tecnicas,#diagnostico) { display: revert; }\nbody[data-tool] #acerca:not(:target), body[data-tool] #privacidad:not(:target) { display: none; }\n\n[data-ad-slot]:not([hidden]){min-height:120px;margin-block:24px;text-align:center}\n\n.quote-box{border:1px solid #5d6c67;border-radius:12px;padding:1rem;margin:1.5rem 0}.quote-box label{display:block;margin:.65rem 0}.quote-box label[hidden],.quote-box[hidden]{display:none}.quote-box textarea{display:block;width:100%;padding:.5rem}.quote-actions{display:flex;flex-wrap:wrap;gap:.5rem}.quote-actions button{cursor:pointer;border:1px solid #85968d;border-radius:7px;padding:.5rem .75rem;background:#202c29;color:#f4f9f6}.quote-actions button:focus-visible{outline:2px solid #aff34a}\n\n.file-picker{position:relative;display:flex;flex-wrap:wrap;align-items:center;gap:.75rem;margin:.4rem 0}.file-input{position:absolute;width:1px;height:1px;opacity:0;overflow:hidden}.quote-box .file-button{display:inline-block;margin:0;cursor:pointer;border:1px solid #85968d;border-radius:7px;padding:.5rem .75rem;background:#202c29;color:#f4f9f6;font-weight:700}.file-button:hover{background:#2b3a36}.file-input:focus-visible+.file-button{outline:2px solid #aff34a;outline-offset:2px}.file-name{color:var(--muted);font-size:.95rem;overflow-wrap:anywhere}\n\n/* Tema unificado con la portada: fondo oscuro, acento lima, Geist. */\n:root{--bg:#101419;--panel:#181e25;--ink:#edf3f8;--muted:#aab6c2;--line:#303943;--purple:#c7fa75;--accent:#c7fa75;--dark:#101419;--lime:#c7fa75;color-scheme:dark}\nbody{font-family:Geist,system-ui,sans-serif}\na{color:var(--lime)}\n:focus-visible{outline-color:var(--lime)}\n.skip{background:var(--panel);color:var(--ink)}\n.site-header{background:var(--bg);border-bottom:1px solid var(--line)}\n.brand{font-weight:800;font-size:23px;letter-spacing:-.045em}\n.brand-mark{background:var(--lime);color:#152011;border-radius:8px}\nnav a,.footer-inner>div a{color:var(--muted);font-weight:500}\nnav a:hover,.footer-inner>div a:hover{color:var(--lime)}\n.site-footer{background:var(--bg);border-top:1px solid var(--line);color:var(--muted)}\n.hero{background:var(--bg)}\n.hero-inner{border:1px solid var(--line);border-radius:22px;background:#181f26;padding-inline:clamp(20px,4vw,56px);margin-top:30px}\n.kicker{color:var(--lime);font-family:\"IBM Plex Mono\",monospace}\n.hero h1 em,.hero .hero-title em{color:var(--lime)}\n.primary{background:var(--lime);color:#18200c}\n.primary:hover{background:#d8ff96}\n.visual{border-color:var(--line);box-shadow:none;background:#151a20}\ninput,select,textarea{background:#11161c;border-color:var(--line);color:var(--ink)}\n.item{background:var(--panel);color:var(--ink)}\n.item:hover{border-color:#698651}\n.item[aria-pressed=true]{border-color:var(--lime);background:#1d2620}\n.icon{background:#243423;color:var(--lime)}\n.arrow{color:var(--lime)}\n.list{scrollbar-color:#3c4a3a transparent}\n.detail{box-shadow:none}\n.detail-head{background:#1d2620}\n.detail-head .mono{color:var(--lime)}\n.data{gap:0;background:none}\n.data>div{box-shadow:0 0 0 .5px var(--line)}\n.copy{background:var(--lime);color:#18200c}\n.copy:hover{background:#d8ff96}\n.quiet{background:var(--panel);border-color:var(--line);color:var(--ink)}\n.quiet:hover{background:#222b33;border-color:#698651}\n.guide-grid article{background:#151b21}\n.export .error{color:#ff9a8a}\n.quote-box{border-color:var(--line);background:var(--panel)}\n.quote-actions button,.quote-box .file-button{background:#222b33;border-color:#4a5866;color:var(--ink)}\n.quote-actions button:hover,.file-button:hover{background:#2b3640;border-color:var(--lime)}\n#costResult p{color:var(--lime)}\n.editorial a{color:var(--lime)}\n.brand>span.brand-mark:last-child{color:#152011}\n.editorial .byline{color:var(--muted);font-size:13px;margin:-4px 0 14px}\n.editorial .help ul{margin:8px 0 0;padding-left:1.2rem}\n.editorial .help li{margin-bottom:6px}\n.editorial .help li strong{color:var(--ink)}\n.editorial .help p+p{margin-top:10px}\n.editorial .note{font-size:13px;color:var(--muted);margin-top:10px!important}\n.table-wrap{overflow-x:auto;margin-top:10px;border:1px solid var(--line);border-radius:12px}\n.table-wrap table{width:100%;border-collapse:collapse;font-size:14px;min-width:420px}\n.table-wrap th,.table-wrap td{text-align:left;padding:9px 12px;border-bottom:1px solid var(--line);vertical-align:top}\n.table-wrap tr:last-child>*{border-bottom:0}\n.table-wrap thead th{color:var(--muted);font-weight:600;font-size:13px;background:#151b21}\n.table-wrap tbody th{font-weight:600}\n.related-guides ul{list-style:none;padding:0!important}\n.related-guides li{border-top:1px solid var(--line);padding:9px 0;margin:0!important}\n.related-guides .button{margin-top:12px}\n.editorial .button.primary{color:#18200c;text-decoration:none}\n.price-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px;margin-bottom:14px}\n.price-summary>div{display:grid;gap:2px;padding:16px 18px;border-radius:14px;background:#1d2620;border:1px solid #4f6b3a}\n.price-summary>div+div{background:var(--panel);border-color:var(--line)}\n.price-summary span{font-size:13px;color:var(--muted)}\n.price-summary strong{font-size:clamp(28px,4vw,38px);line-height:1.1;letter-spacing:-.03em;color:var(--lime)}\n.price-summary>div+div strong{color:var(--ink)}\n.price-summary small{font-size:12px;color:var(--muted)}\n.price-error{color:#ffcf96;font-weight:700;margin:0}\n.cost-breakdown{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:0 24px;margin:0;border-top:1px solid var(--line)}\n.cost-breakdown>div{display:flex;justify-content:space-between;gap:12px;padding:9px 2px;border-bottom:1px solid var(--line)}\n.cost-breakdown dt{color:var(--muted);font-size:13px}\n.cost-breakdown dd{margin:0;font:650 13px/1.4 \"IBM Plex Mono\",ui-monospace,monospace}\n.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}\n.drop-zone{transition:border-color .15s,background .15s}\n.drop-zone.dragging{border-color:var(--lime);border-style:dashed;background:#1d2620}\n.quote-box .box-title{font-size:1.17em;letter-spacing:normal;margin:0 0 8px}\n#context{min-height:2.6em}\n#perfiles .list{min-height:550px}\n#perfiles .detail{min-height:620px}\n@media(max-width:660px){#perfiles .list{min-height:230px}#perfiles .detail{min-height:880px}}\n.related-cats{margin-top:12px!important;color:var(--muted)}\n","/acerca/":"<!doctype html><html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Acerca de UtiliTools</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header><main class=\"wrap\"><section class=\"info-page\"><h1>Acerca de UtiliTools</h1><p>UtiliTools reúne herramientas y guías gratuitas para impresión 3D. El buscador enlaza a los repositorios originales. Los autores y las plataformas gestionan los archivos, sus precios y licencias.</p><h2>Cómo presentamos los datos</h2><p>Las fichas enlazan al origen. Mostramos los formatos identificados y dejamos que la ficha original confirme qué incluye cada descarga. Cuando una fuente está fuera de servicio, el buscador muestra un aviso.</p><p>Las guías de impresión reúnen puntos de partida. Calibrá con una muestra de tu impresora y tu filamento antes de fabricar una tanda.</p><h2 id=\"bajas\">Pedir la baja de un modelo</h2><p>Si sos autor de un modelo, titular de una marca o representás a una plataforma y no querés que un modelo, su imagen o su título aparezcan en UtiliTools, completá este formulario. Revisamos cada pedido y, si corresponde, lo quitamos del sitio.</p><p class=\"note\">UtiliTools no aloja archivos: para que el modelo deje de estar disponible, también tenés que pedirlo en la plataforma donde está publicado.</p><!--BAJA-ESTADO--><form class=\"takedown-form\" method=\"post\" action=\"/api/bajas\"><label>Enlace o nombre del modelo<input name=\"modelo\" required maxlength=\"500\" placeholder=\"https://www.printables.com/model/…\"></label><label>Motivo<select name=\"motivo\" required><option value=\"\">Elegí un motivo</option><option value=\"autor\">Soy el autor y no quiero que aparezca</option><option value=\"licencia\">La licencia no permite este uso</option><option value=\"marca\">Usa una marca o personaje del que soy titular</option><option value=\"otro\">Otro motivo</option></select></label><label>Detalle (opcional)<textarea name=\"detalle\" maxlength=\"1500\" rows=\"4\"></textarea></label><label>Tu email, para responderte<input name=\"email\" type=\"email\" required maxlength=\"200\" autocomplete=\"email\"></label><label class=\"trap\" aria-hidden=\"true\">No completar<input name=\"web\" tabindex=\"-1\" autocomplete=\"off\"></label><p class=\"note\">Guardamos estos datos solo para gestionar el pedido. Más información en <a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a>.</p><button type=\"submit\">Enviar pedido</button></form></section></main><footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>","/privacidad/":"<!doctype html><html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Privacidad de UtiliTools</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header><main class=\"wrap\"><section class=\"info-page\"><h1>Privacidad</h1><h2>Búsqueda de modelos</h2><p>Las palabras que ingresás pueden enviarse a los repositorios consultados para recuperar resultados. Evitá incluir datos personales en las consultas. Las fichas y miniaturas externas se rigen por las políticas de sus sitios de origen.</p><h2>Calculadora y perfiles</h2><p>La calculadora procesa los importes en tu navegador. Los archivos que adjuntás al convertidor de perfiles se procesan en tu dispositivo.</p><h2>Pedidos de baja</h2><p>Si usás el formulario para pedir la baja de un modelo, guardamos el enlace o nombre del modelo, el motivo, el detalle y tu email para revisar el pedido y responderte. Los datos se almacenan en Vercel y se eliminan cuando el pedido queda resuelto. No los usamos para otro fin.</p><h2>Alojamiento</h2><p>Vercel aloja el sitio y puede procesar datos técnicos de las solicitudes, como direcciones IP, para entregar las páginas y operar su infraestructura.</p><h2>Publicidad</h2><p>Actualmente UtiliTools no carga anuncios de Google. Si se habilitan, Google y sus socios pueden usar cookies u otros identificadores para mostrar y medir anuncios. Cuando corresponda podrás gestionar tu consentimiento. Consultá <a href=\"https://policies.google.com/technologies/partner-sites?hl=es\">cómo usa Google los datos de sitios asociados</a>.</p></section><p>Las colecciones se guardan en tu navegador. El enlace para compartirlas incluye sus notas y modelos.</p><p>La calculadora extrae los datos de los archivos de laminado en el navegador. Los costos que elijas guardar se conservan en ese navegador.</p><p>Si activás «Permitir estadísticas de uso», enviamos a PostHog eventos como visitas, búsquedas con o sin resultados, importaciones y presupuestos exportados. Usamos un identificador aleatorio de sesión que vence tras 30 minutos de inactividad. No enviamos consultas escritas, archivos ni textos de presupuestos. Podés desactivar la opción al pie en cualquier momento.</p></main><footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>","/categorias/juguetes/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Juguetes</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Juguetes</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Juguetes para imprimir en 3D</h1><p>Animales articulados, fidgets, trompos y juegos de mesa son de lo más descargado en cualquier repositorio. Muchos se imprimen en una sola pieza, con las articulaciones ya encastradas, así que no hace falta pegar ni ensamblar nada.</p><p>La clave está en las holguras: si la separación entre piezas es muy chica, el juguete sale trabado; si es muy grande, queda flojo. Antes de imprimir una tanda para vender o regalar, imprimí una unidad de prueba con el mismo material y perfil.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=articulated%20toy#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:articulated toy--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=articulated%20toy#catalogo\">Juguetes articulados →</a><a href=\"/?q=articulated%20turtle#catalogo\">Tortuga articulada →</a><a href=\"/?q=fidget#catalogo\">Fidgets →</a><a href=\"/?q=print%20in%20place#catalogo\">Imprimir sin ensamblar →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Que las uniones se impriman separadas y sin soportes dentro de las bisagras.</li><li>La primera capa: si se aplasta demasiado, las piezas móviles quedan pegadas a la cama.</li><li>Bordes y puntas: para chicos chicos, evitá piezas pequeñas que se puedan desprender.</li><li>La licencia, si pensás venderlos: muchos juguetes populares son de uso no comercial.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA o PLA+; PETG si necesitás más resistencia a golpes</dd></div><div><dt>Altura de capa</dt><dd>0,16 a 0,20 mm</dd></div><div><dt>Relleno</dt><dd>10 a 15 %</dd></div><div><dt>Soportes</dt><dd>Normalmente no; respetá la orientación del autor</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/fidgets-y-holguras.html\">Holguras para fidgets y encastres →</a></li><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta →</a></li><li><a href=\"/guias/licencias-modelos-3d.html\">Licencias de modelos 3D →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/diy-taller/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>DIY y taller</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">DIY y taller</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>DIY y taller para imprimir en 3D</h1><p>Soportes para herramientas, organizadores de pared, guías de corte y plantillas de perforado: el taller es donde la impresión 3D se paga sola. Un soporte a medida para una herramienta que usás todos los días cuesta unos pocos gramos de filamento.</p><p>Los sistemas modulares como Honeycomb Storage Wall o los paneles perforados (pegboard) tienen cientos de accesorios compatibles. Elegí un sistema y mantenelo, así todas las piezas encastran entre sí.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=tool%20holder#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:tool holder--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=tool%20holder#catalogo\">Soportes para herramientas →</a><a href=\"/?q=honeycomb%20storage%20wall#catalogo\">Panel Honeycomb →</a><a href=\"/?q=pegboard%20tool%20holder#catalogo\">Accesorios para pegboard →</a><a href=\"/?q=drill%20guide#catalogo\">Guías de perforado →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Medí el mango o el cuerpo de la herramienta con calibre antes de elegir el soporte.</li><li>Confirmá la distancia entre los agujeros de tu panel o pared.</li><li>Para piezas que cargan peso, orientalas de forma que las capas no trabajen separándose.</li><li>Cerca de calor o al sol, el PLA se deforma: usá PETG o ASA.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PETG para piezas de uso diario; PLA para plantillas</dd></div><div><dt>Altura de capa</dt><dd>0,20 a 0,28 mm</dd></div><div><dt>Relleno</dt><dd>20 a 40 % según la carga</dd></div><div><dt>Perímetros</dt><dd>3 o 4 para piezas que soportan peso</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir →</a></li><li><a href=\"/guias/soportes.html\">Soportes fáciles de retirar →</a></li><li><a href=\"/guias/boquillas.html\">Qué boquilla usar →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/decoracion/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Decoración</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Decoración</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Decoración para imprimir en 3D</h1><p>Floreros, lámparas, cuadros en relieve y adornos de pared se imprimen bien en casi cualquier impresora. Muchos floreros están pensados para el modo espiral (vase mode): una sola pared continua, rápida de imprimir y sin costuras.</p><p>En decoración el acabado lo es todo. El filamento seda o mate cambia por completo cómo se ve la pieza, y una capa más fina reduce el escalonado en las curvas.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=home%20decor#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:home decor--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=home%20decor#catalogo\">Decoración para el hogar →</a><a href=\"/?q=decorative%20vase#catalogo\">Floreros decorativos →</a><a href=\"/?q=wall%20art#catalogo\">Cuadros y adornos de pared →</a><a href=\"/?q=lamp%20shade#catalogo\">Pantallas de lámpara →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Si el florero va a llevar agua, el modo espiral de una sola pared puede filtrar: usá dos o tres paredes.</li><li>Para lámparas, usá luces LED: una lámpara incandescente o halógena calienta y deforma el plástico.</li><li>Ubicá la costura en una arista o en la parte de atrás.</li><li>Revisá si el modelo necesita fondo cerrado o soporte para colgar.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA seda o mate para el acabado; PETG si lleva agua</dd></div><div><dt>Altura de capa</dt><dd>0,12 a 0,20 mm</dd></div><div><dt>Relleno</dt><dd>0 % en modo espiral; 10 a 15 % en piezas macizas</dd></div><div><dt>Velocidad</dt><dd>Más baja en las capas visibles para un mejor acabado</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/multicolor.html\">Multicolor con menos purga →</a></li><li><a href=\"/guias/hilos-stringing.html\">Cómo eliminar los hilos →</a></li><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/organizacion/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Organización</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Organización</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Organización para imprimir en 3D</h1><p>Organizadores de cajón, cajas modulares y separadores son ideales para imprimir porque los podés hacer a la medida exacta del espacio. El sistema más usado es Gridfinity, una cuadrícula estándar con bases y cajas que encastran entre sí.</p><p>Gridfinity usa módulos de 42 × 42 mm. Una caja de 2 × 1 ocupa dos módulos de largo y uno de ancho. Medí el cajón y calculá cuántos módulos entran antes de imprimir la base.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=gridfinity#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:gridfinity--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=gridfinity#catalogo\">Modelos Gridfinity →</a><a href=\"/?q=gridfinity%20baseplate#catalogo\">Bases Gridfinity →</a><a href=\"/?q=gridfinity%20bin#catalogo\">Cajas Gridfinity →</a><a href=\"/?q=drawer%20organizer#catalogo\">Organizadores de cajón →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Medí el interior del cajón, no el exterior, y restá un margen de 1 o 2 mm.</li><li>Si la base no entra en tu cama, imprimila en partes que encastran.</li><li>Para cajas que se apilan, verificá que el labio superior sea compatible con la base.</li><li>Las variantes \"lite\" o \"quick print\" usan menos material y tiempo.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA o PETG</dd></div><div><dt>Altura de capa</dt><dd>0,20 a 0,28 mm</dd></div><div><dt>Relleno</dt><dd>10 a 15 %; las paredes dan la rigidez</dd></div><div><dt>Soportes</dt><dd>No: el estándar está pensado para imprimirse sin soportes</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta →</a></li><li><a href=\"/guias/warping.html\">Warping: por qué se levanta la pieza →</a></li><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/macetas/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Macetas</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Macetas</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Macetas para imprimir en 3D</h1><p>Las macetas son uno de los objetos más impresos y más vendidos: hay modelos geométricos, con forma de animal, con plato de drenaje y con depósito de autorriego. Las chicas, para suculentas y cactus, se imprimen en pocas horas.</p><p>Elegí el diámetro útil según el cepellón de la planta y revisá si el modelo tiene drenaje o depósito integrado. Una maceta sin agujero sirve como cubremaceta, pero no para plantar directo.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=planter#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:planter--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=planter#catalogo\">Macetas →</a><a href=\"/?q=plant%20pot%20with%20drainage#catalogo\">Macetas con drenaje →</a><a href=\"/?q=self%20watering%20planter#catalogo\">Macetas con autorriego →</a><a href=\"/?q=succulent%20planter#catalogo\">Macetas para suculentas →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>En una maceta con depósito, hacé una prueba con agua antes de poner tierra.</li><li>Verificá que el recipiente interior salga sin trabarse.</li><li>Al sol, el PLA se ablanda y se degrada: para exterior usá PETG o ASA.</li><li>Si la vas a vender, aclarale al cliente si es para interior o exterior.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA para interior; PETG o ASA para exterior</dd></div><div><dt>Altura de capa</dt><dd>0,20 mm</dd></div><div><dt>Relleno</dt><dd>10 a 15 %, con 3 paredes para que no filtre</dd></div><div><dt>Fondo</dt><dd>4 o 5 capas inferiores si va a contener agua</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir →</a></li><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento →</a></li><li><a href=\"/guias/warping.html\">Warping: por qué se levanta la pieza →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/miniaturas/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Miniaturas</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Miniaturas</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Miniaturas para imprimir en 3D</h1><p>Figuras para juegos de rol, escenografía para wargames y bustos para pintar. Las miniaturas con mucho detalle suelen verse mejor en impresoras de resina, pero muchos autores publican versiones pensadas para FDM, sin soportes o ya divididas en partes.</p><p>La escala más común en juegos de mesa es de 28 a 32 mm. Compará la altura de la figura y el diámetro de su base con las miniaturas que ya tenés antes de imprimir un grupo completo.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=tabletop%20miniature#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:tabletop miniature--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=tabletop%20miniature#catalogo\">Miniaturas para juegos de mesa →</a><a href=\"/?q=supportless%20miniature#catalogo\">Miniaturas sin soportes →</a><a href=\"/?q=tabletop%20terrain#catalogo\">Escenografía para juegos de mesa →</a><a href=\"/?q=dnd%20miniature#catalogo\">Miniaturas de rol →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Buscá versiones \"supportless\" o \"presupported\" según tu tipo de impresora.</li><li>En FDM, usá una boquilla de 0,2 o 0,25 mm si querés más detalle en caras y manos.</li><li>Las piezas finas, como espadas o lanzas, se rompen con facilidad: reforzalas o escalalas un poco.</li><li>Muchos autores venden sus miniaturas por suscripción: revisá la licencia antes de vender impresiones.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA mate o resina estándar</dd></div><div><dt>Altura de capa</dt><dd>0,08 a 0,12 mm en FDM</dd></div><div><dt>Relleno</dt><dd>15 a 20 %</dd></div><div><dt>Soportes</dt><dd>En árbol, con interfaz liviana</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/soportes.html\">Soportes fáciles de retirar →</a></li><li><a href=\"/guias/boquillas.html\">Qué boquilla usar →</a></li><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/repuestos/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Repuestos</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Repuestos</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Repuestos para imprimir en 3D</h1><p>Perillas de cocina, clips de persianas, tapas de control remoto, ruedas de cajón: muchos repuestos que no se consiguen se pueden imprimir. Buscá por la marca y el modelo del objeto, en inglés suele haber más resultados.</p><p>Si no encontrás el repuesto exacto, buscá uno parecido que se pueda editar. Muchos autores publican el archivo STEP o el proyecto paramétrico para ajustar medidas.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=replacement%20part#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:replacement part--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=replacement%20part#catalogo\">Repuestos →</a><a href=\"/?q=replacement%20knob#catalogo\">Perillas →</a><a href=\"/?q=replacement%20clip#catalogo\">Clips y trabas →</a><a href=\"/?q=remote%20control%20cover#catalogo\">Tapas de control remoto →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Medí ejes, agujeros y trabas con calibre antes de imprimir.</li><li>Imprimí primero una prueba corta de la parte que encastra.</li><li>Para piezas cerca de calor, como perillas de cocina, el PLA no alcanza: usá PETG, ASA o ABS.</li><li>No imprimas repuestos de seguridad, como frenos o piezas de gas: usá el original.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PETG en general; ASA o ABS si hay calor</dd></div><div><dt>Altura de capa</dt><dd>0,12 a 0,20 mm para buena precisión</dd></div><div><dt>Relleno</dt><dd>30 a 50 % en piezas que cargan esfuerzo</dd></div><div><dt>Perímetros</dt><dd>3 o más</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir →</a></li><li><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento →</a></li><li><a href=\"/guias/tpu-flexibles.html\">Cómo imprimir TPU y flexibles →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/cosplay/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Cosplay</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Cosplay</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Cosplay para imprimir en 3D</h1><p>Cascos, armaduras, armas de utilería y accesorios: el cosplay es una de las áreas donde más se nota la impresión 3D. Las piezas grandes suelen venir divididas en partes para que entren en cualquier cama de impresión.</p><p>Tomá medidas sobre la ropa que vas a usar y comparalas con las dimensiones internas del archivo. Es mejor escalar el modelo antes de imprimir que lijar o recortar después.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=cosplay#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:cosplay--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=cosplay#catalogo\">Cosplay →</a><a href=\"/?q=cosplay%20armor#catalogo\">Armaduras →</a><a href=\"/?q=cosplay%20helmet#catalogo\">Cascos →</a><a href=\"/?q=cosplay%20accessories#catalogo\">Accesorios de cosplay →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Escalá cascos y armaduras según la medida de tu cabeza o tu cuerpo, no al ojo.</li><li>Las piezas grandes se pegan con cianoacrilato o epoxi, y se reparan las uniones con masilla.</li><li>Para pintar, lijá, aplicá imprimación de relleno y recién después color.</li><li>En eventos, revisá las reglas sobre réplicas de armas.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA o PLA+ (fácil de lijar); PETG para piezas que se doblan</dd></div><div><dt>Altura de capa</dt><dd>0,20 a 0,28 mm en piezas grandes</dd></div><div><dt>Relleno</dt><dd>5 a 15 %; las paredes dan la forma</dd></div><div><dt>Perímetros</dt><dd>3 o 4 para poder lijar sin atravesar</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/warping.html\">Warping: por qué se levanta la pieza →</a></li><li><a href=\"/guias/soportes.html\">Soportes fáciles de retirar →</a></li><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/llaveros/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Llaveros</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Llaveros</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Llaveros para imprimir en 3D</h1><p>Los llaveros son el producto más común para vender en ferias y eventos: son rápidos, usan poco material y se pueden personalizar con nombres o logos. Muchos usan cambio de color en una capa para destacar el texto sin necesidad de multicolor.</p><p>Para una tanda grande, armá una placa completa y calculá el costo por unidad incluyendo la argolla y el embalaje.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=keychain#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:keychain--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=keychain#catalogo\">Llaveros →</a><a href=\"/?q=personalized%20keychain#catalogo\">Llaveros personalizados →</a><a href=\"/?q=name%20tag%20keychain#catalogo\">Llaveros con nombre →</a><a href=\"/?q=articulated%20keychain#catalogo\">Llaveros articulados →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Revisá que el agujero admita tu argolla y que el borde tenga material suficiente alrededor.</li><li>El texto en relieve se lee mejor con al menos 0,6 mm de altura y letras gruesas.</li><li>Para cambio de color, poné una pausa en la capa donde empieza el texto.</li><li>Logos de marcas y personajes suelen tener derechos: no los vendas sin permiso.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA o PETG</dd></div><div><dt>Altura de capa</dt><dd>0,20 mm</dd></div><div><dt>Relleno</dt><dd>100 % o 4 perímetros, porque es una pieza fina</dd></div><div><dt>Soportes</dt><dd>No</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/multicolor.html\">Multicolor con menos purga →</a></li><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D →</a></li><li><a href=\"/guias/vender-en-mercado-libre.html\">Cómo vender en Mercado Libre →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/utilitools-analytics.js":"(() => {\n  const cookieDomain = '.utilitools.com.ar';\n  const secure = '; Path=/; Secure; SameSite=Lax; Domain='+cookieDomain;\n  const read = key => document.cookie.split('; ').find(item=>item.startsWith(key+'='))?.slice(key.length+1);\n  const consentKey = 'utilitools_measure';\n  const sessionKey = 'utilitools_measure_session';\n  const input = document.getElementById('analytics-consent');\n  let pageRecorded = false;\n  if (!input) return;\n  input.checked = read(consentKey)==='yes';\n  function pageType() {\n    if(location.pathname.startsWith('/categorias/')) return 'category';\n    if(location.pathname.startsWith('/guias/') && location.pathname!=='/guias/') return 'guide';\n    const subdomain=location.hostname.split('.')[0];\n    if(['calculadora','guias','perfiles'].includes(subdomain)) return subdomain;\n    if(location.pathname==='/') return 'home';\n    return 'other';\n  }\n  function originChannel() {\n    try {\n      const host=new URL(document.referrer).hostname.toLowerCase();\n      if(host==='utilitools.com.ar'||host.endsWith('.utilitools.com.ar')) return 'internal';\n      if(/^(?:www\\.)?(?:google\\.[a-z.]+|bing\\.com|duckduckgo\\.com)$/.test(host)) return 'search';\n      if(/(?:^|\\.)(?:facebook\\.com|instagram\\.com|tiktok\\.com|youtube\\.com|reddit\\.com|whatsapp\\.com)$/.test(host)) return 'social';\n      return 'referral';\n    } catch {return 'direct';}\n  }\n  function track(event, detail={}) {\n    if(read(consentKey)!=='yes') return;\n    const id=read(sessionKey) || crypto.randomUUID();\n    document.cookie=sessionKey+'='+id+'; Max-Age=1800'+secure;\n    fetch('/api/medicion',{method:'POST',keepalive:true,credentials:'omit',referrerPolicy:'no-referrer',\n      headers:{'content-type':'application/json'},body:JSON.stringify({event,id,page:pageType(),...detail})}).catch(()=>{});\n  }\n  window.utilitoolsTrack=track;\n  function pageView() {\n    if(pageRecorded || read(consentKey)!=='yes') return;\n    pageRecorded=true;\n    track('page_view',{channel:originChannel(),category:location.pathname.match(/^\\/categorias\\/([a-z-]+)\\/$/)?.[1]});\n  }\n  input.addEventListener('change',()=>{\n    document.cookie=consentKey+'='+(input.checked?'yes':'no')+'; Max-Age=15552000'+secure;\n    if(input.checked) pageView();\n    else {\n      document.cookie=sessionKey+'=; Max-Age=0'+secure;\n      pageRecorded=false;\n    }\n  });\n  document.addEventListener('click',event=>{\n    const link=event.target.closest?.('a');\n    if(!link) return;\n    if(link.matches('a.open-model')) track('model_opened');\n    if(link.matches('.model-actions a')) track('calculator_opened');\n  });\n  pageView();\n})();\n","/404.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Página no encontrada</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><section class=\"hero\"><div class=\"pattern\" aria-hidden=\"true\"></div><div class=\"hero-content\"><p class=\"eyebrow\">ERROR 404</p><h1>No encontramos<br>esta <em>página</em></h1><p>Puede que el enlace esté mal escrito o que la página se haya movido. Probá buscar un modelo o elegí una categoría.</p><form role=\"search\" action=\"__SEARCH_HOME__\" method=\"get\"><label class=\"sr\" for=\"q404\">Buscar modelos</label><span aria-hidden=\"true\">⌕</span><input type=\"search\" id=\"q404\" name=\"q\" maxlength=\"100\" placeholder=\"Probá con maceta, dragón o Gridfinity…\"><button type=\"submit\">Buscar ↗</button></form><div class=\"categories\" aria-label=\"Categorías de impresión\"><a href=\"__SEARCH_HOME__categorias/juguetes/\">Juguetes</a><a href=\"__SEARCH_HOME__categorias/diy-taller/\">DIY y taller</a><a href=\"__SEARCH_HOME__categorias/decoracion/\">Decoración</a><a href=\"__SEARCH_HOME__categorias/organizacion/\">Organización</a><a href=\"__SEARCH_HOME__categorias/macetas/\">Macetas</a><a href=\"__SEARCH_HOME__categorias/miniaturas/\">Miniaturas</a><a href=\"__SEARCH_HOME__categorias/repuestos/\">Repuestos</a><a href=\"__SEARCH_HOME__categorias/cosplay/\">Cosplay</a><a href=\"__SEARCH_HOME__categorias/llaveros/\">Llaveros</a><a href=\"__SEARCH_HOME__categorias/gamer/\">Gamer</a><a href=\"__SEARCH_HOME__categorias/cocina/\">Cocina</a><a href=\"__SEARCH_HOME__categorias/mascotas/\">Mascotas</a><a href=\"__SEARCH_HOME__categorias/electronica/\">Electrónica</a></div></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/favicon.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\"><rect width=\"32\" height=\"32\" rx=\"7\" fill=\"#c7fa75\"/><path d=\"M10 8v9a6 6 0 0 0 12 0V8\" fill=\"none\" stroke=\"#152011\" stroke-width=\"4\" stroke-linecap=\"round\"/></svg>\n","/favicon.ico":"","/apple-touch-icon.png":"","/herramientas/assets/portada-1120.jpg":"","/herramientas/guias/pla-vs-petg.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PLA o PETG: cuál elegir para cada pieza</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>PLA o PETG: cuál elegir para cada pieza</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Son los dos filamentos más usados y conviven en casi todos los talleres. Esta comparación te ayuda a elegir según dónde va a estar la pieza, cuánto calor y esfuerzo tiene que aguantar y qué acabado buscás.</p>\n<section class=\"help\"><h2>La diferencia en una línea</h2><p>El PLA es más fácil de imprimir, tiene mejor detalle y más variedad de colores y acabados. El PETG aguanta más calor, golpes y humedad, pero hace más hilos y pide un poco más de ajuste. Para decoración y prototipos, PLA. Para piezas que trabajan, PETG.</p></section>\n<section class=\"help\"><h2>Comparación rápida</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\"></th><th scope=\"col\">PLA</th><th scope=\"col\">PETG</th></tr></thead><tbody><tr><th scope=\"row\">Boquilla</th><td>190 a 220 °C</td><td>220 a 250 °C</td></tr><tr><th scope=\"row\">Cama</th><td>50 a 60 °C</td><td>70 a 85 °C</td></tr><tr><th scope=\"row\">Se ablanda cerca de</th><td>55 a 60 °C</td><td>75 a 80 °C</td></tr><tr><th scope=\"row\">Ventilador de pieza</th><td>100 %</td><td>30 a 60 %</td></tr><tr><th scope=\"row\">Facilidad</th><td>Muy fácil</td><td>Media</td></tr><tr><th scope=\"row\">Hilos</th><td>Pocos</td><td>Más frecuentes</td></tr><tr><th scope=\"row\">Impacto</th><td>Rígido, puede quebrarse</td><td>Más tenaz, se dobla antes de romperse</td></tr><tr><th scope=\"row\">Sol y exterior</th><td>Se degrada</td><td>Aguanta mejor</td></tr></tbody></table></div><p class=\"note\">Son rangos orientativos. La ficha de cada marca manda: hay PLA+ y PETG de alta velocidad con temperaturas distintas.</p></section>\n<section class=\"help\"><h2>Cuándo conviene PLA</h2><ul><li>Decoración, figuras, macetas de interior y regalos.</li><li>Prototipos para probar medidas antes de imprimir la pieza final.</li><li>Piezas con mucho detalle o texto chico.</li><li>Acabados especiales: seda, mate, madera, brillantina o multicolor.</li><li>Si recién empezás: perdona más errores de configuración.</li></ul></section>\n<section class=\"help\"><h2>Cuándo conviene PETG</h2><ul><li>Soportes, ganchos, clips y piezas que reciben esfuerzo o golpes.</li><li>Objetos que van a estar al sol o al aire libre, como macetas de balcón.</li><li>Piezas cerca de fuentes de calor moderado, como la cocina o el lavadero.</li><li>Recipientes que tienen contacto con agua.</li></ul></section>\n<section class=\"help\"><h2>Ojo con el auto y el calor extremo</h2><p>En verano, el interior de un auto al sol puede superar los 70 °C. El PLA se deforma seguro y el PETG puede ablandarse en el tablero. Para piezas de auto expuestas al sol, usá ASA o ABS con una impresora cerrada.</p></section>\n<section class=\"help\"><h2>Consejos para imprimir PETG sin problemas</h2><ul><li>Secalo antes de usarlo si la bobina estuvo abierta: la humedad multiplica los hilos y las burbujas.</li><li>Subí un poco el Z offset respecto del PLA. El PETG aplastado contra la cama se pega demasiado y ensucia la boquilla.</li><li>En camas de PEI liso o vidrio puede adherirse tanto que arranca material de la superficie: usá una capa fina de lápiz adhesivo como separador.</li><li>Bajá el ventilador de pieza a 30–60 % para mejorar la unión entre capas.</li><li>Si hace hilos, ajustá primero temperatura y secado, y después retracción.</li></ul></section>\n<section class=\"help\"><h2>¿Y para contacto con alimentos?</h2><p>Ninguno de los dos garantiza que una pieza impresa sea apta para alimentos. Las capas dejan rendijas donde se acumulan bacterias y los aditivos o la boquilla pueden aportar contaminantes. Para cortantes de galletitas de un solo uso puede alcanzar; para vasos, platos o recipientes de uso repetido, no.</p></section>\n<section class=\"help\"><h2>Precio</h2><p>En Argentina el PETG suele costar parecido o un poco más que el PLA de la misma marca. La diferencia real está en la tasa de fallos: si una pieza en PETG te sale bien al primer intento, el costo final es muy similar. Cargá los valores de tu bobina en la <a href=\"/calculadora/\">calculadora</a> para comparar.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento y guardarlo bien</a></li><li><a href=\"/guias/hilos-stringing.html\">Cómo eliminar los hilos (stringing) en impresión 3D</a></li><li><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/macetas/\">Macetas</a> · <a href=\"__SEARCH_HOME__categorias/repuestos/\">Repuestos</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/cuanto-cobrar-impresion-3d.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cuánto cobrar una impresión 3D en Argentina</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cuánto cobrar una impresión 3D en Argentina</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Cobrar por gramo es la forma más común y la que más plata hace perder. Esta guía te muestra cómo armar un precio que cubra material, máquina, tu tiempo, los fallos y la comisión, con un ejemplo completo en pesos.</p>\n<section class=\"help\"><h2>Por qué cobrar solo por gramo no alcanza</h2><p>Dos piezas de 50 gramos pueden tardar 1 hora o 6 horas, según la altura de capa, el relleno y la cantidad de detalles. Si cobrás solo el material, la impresora trabaja gratis y tu tiempo de preparar, retirar soportes y embalar no aparece en ningún lado.</p></section>\n<section class=\"help\"><h2>Los componentes del precio</h2><ul><li><strong>Material:</strong> gramos del laminador, incluida la purga, por el precio del kilo.</li><li><strong>Máquina:</strong> desgaste y mantenimiento por hora (boquillas, correas, PEI, repuestos y amortización).</li><li><strong>Energía:</strong> consumo medio por horas por tarifa del kWh.</li><li><strong>Mano de obra:</strong> minutos de preparación, postprocesado y armado, a tu valor hora.</li><li><strong>Fallos:</strong> un porcentaje de intentos que salen mal y hay que repetir.</li><li><strong>Embalaje y envío:</strong> bolsa, caja, etiqueta y el cargo fijo por pedido.</li><li><strong>Comisión:</strong> lo que se queda la plataforma o el medio de pago.</li><li><strong>Margen:</strong> tu ganancia real, después de todo lo anterior.</li></ul></section>\n<section class=\"help\"><h2>Un ejemplo completo</h2><p>Una pieza de 100 g en PLA a $22.000 el kilo, que tarda 2 horas, con 15 minutos de trabajo manual, vendida por una plataforma que cobra 15 % de comisión y con un margen buscado de 30 %.</p><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Concepto</th><th scope=\"col\">Cálculo</th><th scope=\"col\">Importe</th></tr></thead><tbody><tr><th scope=\"row\">Material</th><td>100 g × $22 por gramo</td><td>$2.200</td></tr><tr><th scope=\"row\">Desgaste</th><td>2 h × $700</td><td>$1.400</td></tr><tr><th scope=\"row\">Energía</th><td>0,1 kW × 2 h × $150 el kWh</td><td>$30</td></tr><tr><th scope=\"row\">Mano de obra</th><td>15 min a $6.000 la hora</td><td>$1.500</td></tr><tr><th scope=\"row\">Subtotal</th><td></td><td>$5.130</td></tr><tr><th scope=\"row\">Con 5 % de fallos</th><td>$5.130 ÷ 0,95</td><td>$5.400</td></tr><tr><th scope=\"row\">Con embalaje</th><td>+ $500</td><td>$5.900</td></tr><tr><th scope=\"row\">Precio final</th><td>$5.900 ÷ (1 − 0,15 − 0,30)</td><td>$10.727</td></tr></tbody></table></div><p class=\"note\">El precio se divide por lo que queda después de comisión y margen, no se le suma un porcentaje. Si sumás 45 % a $5.900 llegás a $8.555, y después de la comisión tu margen real queda muy por debajo del 30 %.</p></section>\n<section class=\"help\"><h2>Usá el precio de reposición</h2><p>Con inflación, el precio que pagaste por la bobina no sirve: cobrá lo que te cuesta reponerla hoy. Actualizá el precio del kilo cada vez que comprás filamento, y revisá tus precios publicados al menos una vez por mes.</p></section>\n<section class=\"help\"><h2>Pedidos especiales</h2><ul><li><strong>Diseño a medida:</strong> cobrá las horas de modelado aparte. Un repuesto que tenés que medir y dibujar puede llevar más tiempo que imprimirlo.</li><li><strong>Monto mínimo:</strong> fijá un mínimo por pedido para que una pieza chica no te haga perder la tarde.</li><li><strong>Lotes:</strong> en tandas grandes la preparación se reparte entre más unidades, así que podés bajar el precio unitario sin perder.</li><li><strong>Urgencias:</strong> si un pedido desplaza a otros, corresponde un recargo.</li></ul></section>\n<section class=\"help\"><h2>Compará con el mercado, pero no copies precios</h2><p>Mirá cuánto se publican piezas similares para saber si estás en rango. Pero muchos vendedores no calculan sus costos y venden a pérdida sin saberlo. Si tu precio queda muy arriba, revisá si podés imprimir más rápido, con menos material o en lotes, antes de bajar el margen.</p></section>\n<section class=\"help\"><h2>Impuestos</h2><p>Si facturás, sumá los impuestos que correspondan a tu situación fiscal como un costo más o incluilos en la comisión. Consultá con tu contador cómo aplicarlos.</p></section>\n<section class=\"help\"><h2>Hacé la cuenta con tus números</h2><p>La <a href=\"/calculadora/\">calculadora de UtiliTools</a> hace este cálculo con tus valores, importa los gramos y las horas desde el G-code y arma un presupuesto para mandar por WhatsApp.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/costos-de-impresion.html\">Cómo calcular el costo real de una impresión 3D</a></li><li><a href=\"/guias/vender-en-mercado-libre.html\">Cómo vender impresiones 3D en Mercado Libre</a></li><li><a href=\"/guias/licencias-modelos-3d.html\">Licencias de modelos 3D: qué podés vender y qué no</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/llaveros/\">Llaveros</a> · <a href=\"__SEARCH_HOME__categorias/organizacion/\">Organización</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/vender-en-mercado-libre.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo vender impresiones 3D en Mercado Libre</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo vender impresiones 3D en Mercado Libre</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Mercado Libre es el canal más grande para vender impresiones 3D en Argentina, pero los costos de venta y las reglas de propiedad intelectual pueden comerse la ganancia o darte de baja una publicación. Esto es lo que conviene revisar antes de publicar.</p>\n<section class=\"help\"><h2>Antes de publicar: ¿podés vender ese diseño?</h2><p>Solo publicá diseños propios o modelos cuya licencia permita el uso comercial. Mercado Libre tiene un programa de protección de marcas: los titulares de personajes, logos y marcas pueden denunciar publicaciones y la plataforma las da de baja. Un archivo con licencia libre no te da derechos sobre un personaje de terceros. Más detalle en <a href=\"/guias/licencias-modelos-3d.html\">la guía de licencias</a>.</p></section>\n<section class=\"help\"><h2>Conocé los costos de vender</h2><ul><li><strong>Comisión por venta:</strong> depende de la categoría y del tipo de publicación (clásica o premium).</li><li><strong>Cargo fijo:</strong> se suma en productos por debajo de cierto precio.</li><li><strong>Envío:</strong> según el precio, el peso y tu reputación, puede que tengas que ofrecerlo gratis y pagar parte del costo.</li><li><strong>Cuotas:</strong> ofrecer cuotas sin interés tiene un costo extra.</li></ul><p class=\"note\">Los porcentajes y montos cambian seguido. Consultá los valores vigentes en la <a href=\"https://vendedores.mercadolibre.com.ar/aprender/nota/como-funcionan-los-costos-de-mercado-libre\">página de costos de Mercado Libre</a> y cargalos en la calculadora.</p></section>\n<section class=\"help\"><h2>Una publicación que vende</h2><ul><li><strong>Título:</strong> usá las palabras que escribe el comprador, no el nombre del archivo. \"Maceta autorriego 12 cm impresa 3D PETG\" funciona mejor que \"Self watering planter v2\".</li><li><strong>Fotos reales:</strong> mostrá la pieza impresa, con buena luz y algo que dé escala, como una mano o una moneda. Evitá usar las fotos o renders del autor del modelo.</li><li><strong>Medidas y material:</strong> alto, ancho, diámetro interno si aplica, material y si sirve para exterior.</li><li><strong>Variantes:</strong> ofrecé colores como variantes de una misma publicación en vez de publicaciones separadas.</li><li><strong>Tiempo de fabricación:</strong> si imprimís a pedido, indicalo en la publicación para no recibir reclamos por demora.</li></ul></section>\n<section class=\"help\"><h2>Calculá el precio con la comisión incluida</h2><p>El error más común es calcular el costo y sumarle un porcentaje. La comisión se cobra sobre el precio final, así que el precio tiene que salir de dividir el costo por lo que queda después de comisión y margen. La guía <a href=\"/guias/cuanto-cobrar-impresion-3d.html\">cuánto cobrar una impresión 3D</a> tiene un ejemplo completo.</p></section>\n<section class=\"help\"><h2>Embalaje y envío</h2><ul><li>Pesá y medí la caja ya armada: el costo de envío depende de eso.</li><li>Protegé las piezas finas con papel o burbuja; las puntas y los encastres son lo primero que se rompe.</li><li>Incluí una tarjeta con instrucciones de uso o de cuidado si la pieza lo necesita.</li></ul></section>\n<section class=\"help\"><h2>Reputación</h2><p>Respondé las preguntas rápido, despachá en el plazo que prometiste y describí la pieza tal como es. Las primeras ventas con buena calificación pesan mucho en la visibilidad de tus publicaciones.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D en Argentina</a></li><li><a href=\"/guias/licencias-modelos-3d.html\">Licencias de modelos 3D: qué podés vender y qué no</a></li><li><a href=\"/guias/costos-de-impresion.html\">Cómo calcular el costo real de una impresión 3D</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/llaveros/\">Llaveros</a> · <a href=\"__SEARCH_HOME__categorias/decoracion/\">Decoración</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/primera-capa.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo lograr una primera capa perfecta</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo lograr una primera capa perfecta</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">La mayoría de las impresiones que fallan, fallan en la primera capa. Si se despega, la pieza se mueve; si queda muy aplastada, aparece pie de elefante y las piezas móviles se traban. Así se diagnostica y se corrige.</p>\n<section class=\"help\"><h2>Leé la primera capa</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Lo que ves</th><th scope=\"col\">Qué significa</th><th scope=\"col\">Qué hacer</th></tr></thead><tbody><tr><th scope=\"row\">Líneas redondas con huecos entre sí</th><td>La boquilla está alta</td><td>Bajá el Z offset de a 0,02 mm</td></tr><tr><th scope=\"row\">Superficie áspera, con crestas o transparente</th><td>La boquilla está baja y raspa</td><td>Subí el Z offset de a 0,02 mm</td></tr><tr><th scope=\"row\">Bien en una zona y mal en otra</th><td>La cama no está pareja</td><td>Repetí la nivelación o la malla</td></tr><tr><th scope=\"row\">Las esquinas se levantan</th><td>Falta adhesión o hay warping</td><td>Limpiá la cama y revisá la temperatura</td></tr><tr><th scope=\"row\">El filamento no se pega en ninguna parte</th><td>Cama sucia o temperatura baja</td><td>Lavá la superficie y subí 5 °C la cama</td></tr></tbody></table></div></section>\n<section class=\"help\"><h2>1. Limpiá la superficie</h2><p>La grasa de los dedos es la causa número uno de falta de adhesión. Las placas de PEI se lavan con agua tibia y detergente, se enjuagan bien y se secan con papel. Entre impresiones alcanza con alcohol isopropílico. Agarrá la placa por los bordes.</p></section>\n<section class=\"help\"><h2>2. Calentá y esperá</h2><p>La cama se dilata al calentarse. Si nivelás o medís la malla en frío, la medición no sirve. Calentá la cama a la temperatura de trabajo y esperá unos minutos antes de medir.</p></section>\n<section class=\"help\"><h2>3. Nivelación y malla</h2><p>Si tu impresora tiene sensor, hacé una malla nueva cuando cambies de placa o muevas la máquina. Si es manual, nivelá con una hoja de papel en las cuatro esquinas y el centro, y repetí la vuelta hasta que no haga falta ajustar nada.</p></section>\n<section class=\"help\"><h2>4. Ajustá el Z offset con una prueba</h2><p>Imprimí un cuadrado de una sola capa que cubra buena parte de la cama y ajustá el Z offset en vivo, de a 0,02 mm. Buscá una superficie lisa, sin huecos entre líneas y sin crestas. Al pasar el dedo no tiene que sentirse el relieve de cada línea.</p></section>\n<section class=\"help\"><h2>5. Velocidad y temperatura</h2><ul><li>Imprimí la primera capa más lenta que el resto.</li><li>Usá una altura de primera capa algo mayor, como 0,2 a 0,25 mm: perdona pequeñas diferencias de nivel.</li><li>Un ancho de línea mayor en la primera capa mejora el contacto con la cama.</li><li>Apagá o reducí el ventilador de pieza en las primeras capas.</li></ul></section>\n<section class=\"help\"><h2>Si igual se despega</h2><p>Usá brim en piezas con poca superficie de contacto o con esquinas finas, y una capa fina de lápiz adhesivo si la placa ya está gastada. Si el problema son las esquinas que se levantan con el correr de las capas, el problema es warping: tiene su <a href=\"/guias/warping.html\">propia guía</a>.</p></section>\n<section class=\"help\"><h2>Pie de elefante</h2><p>Si la base de la pieza sale más ancha que el resto, la primera capa está demasiado aplastada o la cama muy caliente. Subí un poco el Z offset o usá la compensación de pie de elefante del laminador. Es clave en piezas que encastran.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/warping.html\">Warping: por qué se levanta la pieza y cómo evitarlo</a></li><li><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento</a></li><li><a href=\"/guias/fidgets-y-holguras.html\">Cómo lograr que un fidget gire al salir de la cama</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/organizacion/\">Organización</a> · <a href=\"__SEARCH_HOME__categorias/juguetes/\">Juguetes</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/secar-filamento.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo secar el filamento y guardarlo bien</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo secar el filamento y guardarlo bien</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Casi todos los filamentos absorben humedad del ambiente. Un filamento húmedo hace hilos, burbujas, piezas ásperas y frágiles. Secarlo es barato y resuelve problemas que parecen de configuración.</p>\n<section class=\"help\"><h2>Señales de un filamento húmedo</h2><ul><li>Chasquidos o pequeños estallidos al extruir.</li><li>Vapor o burbujas en el material que sale de la boquilla.</li><li>Muchos más hilos que antes con la misma configuración.</li><li>Superficie áspera o con poros.</li><li>Piezas más frágiles o capas que se separan.</li><li>En PLA, filamento que se quiebra en la bobina (también puede ser por antigüedad).</li></ul></section>\n<section class=\"help\"><h2>Qué tan sensible es cada material</h2><p>El PLA absorbe poco, pero en un lugar húmedo y después de semanas abierto también lo sufre. El PETG y el TPU son bastante sensibles. El nylon y el PVA absorben tanta humedad que conviene imprimirlos directamente desde un secador.</p></section>\n<section class=\"help\"><h2>Temperaturas y tiempos de secado</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Material</th><th scope=\"col\">Temperatura</th><th scope=\"col\">Tiempo</th></tr></thead><tbody><tr><th scope=\"row\">PLA</th><td>45 a 50 °C</td><td>4 a 6 h</td></tr><tr><th scope=\"row\">PETG</th><td>60 a 65 °C</td><td>4 a 6 h</td></tr><tr><th scope=\"row\">TPU</th><td>50 a 55 °C</td><td>4 a 8 h</td></tr><tr><th scope=\"row\">ABS y ASA</th><td>65 a 80 °C</td><td>4 h</td></tr><tr><th scope=\"row\">Nylon</th><td>70 a 80 °C</td><td>8 a 12 h</td></tr><tr><th scope=\"row\">PVA</th><td>45 a 55 °C</td><td>4 a 6 h</td></tr></tbody></table></div><p class=\"note\">Son valores orientativos: la ficha del fabricante tiene prioridad. Algunas bobinas plásticas se deforman por encima de 60 °C; si es el caso, pasá el filamento a una bobina resistente o secá a menor temperatura durante más tiempo.</p></section>\n<section class=\"help\"><h2>Con qué secarlo</h2><ul><li><strong>Secador de filamento:</strong> la opción más cómoda. Muchos permiten imprimir mientras secan.</li><li><strong>Deshidratador de alimentos:</strong> funciona bien si la bobina entra y llega a la temperatura necesaria.</li><li><strong>Horno de cocina:</strong> sirve, pero los termostatos suelen ser imprecisos y tener picos. Usá un termómetro aparte, la temperatura más baja y la puerta apenas abierta. Nunca lo dejes sin supervisión.</li><li><strong>Cama caliente con una caja encima:</strong> es lento y desparejo; sirve solo como solución de emergencia.</li></ul></section>\n<section class=\"help\"><h2>Cómo guardarlo</h2><ul><li>Guardá cada bobina en una bolsa con cierre hermético y un sobre de sílica gel.</li><li>Para varias bobinas, usá una caja hermética con desecante y un higrómetro barato: apuntá a menos de 20–30 % de humedad.</li><li>Regenerá la sílica gel en el horno cuando cambie de color.</li><li>En ciudades húmedas como Buenos Aires o Rosario, no dejes bobinas abiertas en la impresora más de lo necesario.</li></ul></section>\n<section class=\"help\"><h2>Un hábito que ahorra fallos</h2><p>Anotá en la bobina la fecha en que la abriste y la última vez que la secaste. Si una impresión que antes salía bien empieza a fallar, secá el filamento antes de tocar la configuración.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/hilos-stringing.html\">Cómo eliminar los hilos (stringing) en impresión 3D</a></li><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir para cada pieza</a></li><li><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/decoracion/\">Decoración</a> · <a href=\"__SEARCH_HOME__categorias/macetas/\">Macetas</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/warping.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Warping: por qué se levanta la pieza y cómo evitarlo</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Warping: por qué se levanta la pieza y cómo evitarlo</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">El warping es cuando las esquinas o los bordes de la pieza se despegan de la cama y se curvan hacia arriba. Pasa porque el plástico se contrae al enfriarse y tira de la base. Se puede prevenir casi siempre.</p>\n<section class=\"help\"><h2>Qué materiales lo sufren más</h2><p>El ABS, el ASA y el nylon son los más propensos porque se contraen mucho. El PETG tiene un warping moderado y el PLA, bajo; aun así, una pieza de PLA larga y con esquinas rectas puede levantarse si hay una corriente de aire.</p></section>\n<section class=\"help\"><h2>Primero, la adhesión</h2><ul><li>Limpiá la cama con agua y detergente o con alcohol isopropílico.</li><li>Revisá que la <a href=\"/guias/primera-capa.html\">primera capa</a> esté bien aplastada y sin huecos.</li><li>Usá la temperatura de cama recomendada para el material.</li><li>En placas gastadas, una capa fina de lápiz adhesivo mejora mucho el agarre.</li></ul></section>\n<section class=\"help\"><h2>Después, controlá el enfriamiento</h2><ul><li>Evitá corrientes de aire: ventanas, aire acondicionado o ventiladores cerca de la impresora.</li><li>Para ABS, ASA y nylon, imprimí con la impresora cerrada o dentro de un gabinete.</li><li>Apagá el ventilador de pieza en las primeras capas y usá menos ventilación en materiales técnicos.</li><li>No abras la puerta hasta que la pieza y la cama se enfríen.</li></ul></section>\n<section class=\"help\"><h2>Ayudas del laminador</h2><ul><li><strong>Brim:</strong> un borde de varias líneas alrededor de la base que aumenta la superficie de contacto y se retira después.</li><li><strong>Orejas o mouse ears:</strong> discos chicos solo en las esquinas, que se retiran más fácil que un brim completo.</li><li><strong>Draft shield:</strong> una pared fina alrededor de la pieza que la protege del aire.</li></ul></section>\n<section class=\"help\"><h2>Desde el diseño</h2><ul><li>Redondeá las esquinas de la base: las esquinas a 90° concentran la tensión.</li><li>Si podés, orientá la pieza para que la base sea más chica o tenga menos largo continuo.</li><li>Dividí piezas muy largas en partes que se unen después.</li></ul></section>\n<section class=\"help\"><h2>Si la pieza ya se levantó</h2><p>No hay forma de recuperar la geometría de una pieza deformada. Anotá en qué capa empezó a levantarse: si fue en las primeras, el problema es adhesión; si fue más arriba, es enfriamiento y corrientes de aire.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta</a></li><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir para cada pieza</a></li><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento y guardarlo bien</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/cosplay/\">Cosplay</a> · <a href=\"__SEARCH_HOME__categorias/organizacion/\">Organización</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/hilos-stringing.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo eliminar los hilos (stringing) en impresión 3D</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo eliminar los hilos (stringing) en impresión 3D</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Los hilos son filamentos finos que quedan entre partes de la pieza cuando la boquilla se mueve sin extruir. Casi siempre se resuelven con secado, temperatura y retracción, en ese orden.</p>\n<section class=\"help\"><h2>Por qué aparecen</h2><p>Mientras la boquilla viaja de un punto a otro, el plástico caliente sigue goteando. Si el material está húmedo, muy caliente o la retracción no alcanza, ese goteo se estira y forma hilos.</p></section>\n<section class=\"help\"><h2>1. Secá el filamento</h2><p>Es la causa más subestimada, sobre todo en PETG y TPU. Si los hilos aparecieron de golpe con una bobina que antes andaba bien, <a href=\"/guias/secar-filamento.html\">secala</a> antes de cambiar cualquier parámetro.</p></section>\n<section class=\"help\"><h2>2. Bajá la temperatura</h2><p>Imprimí una torre de temperatura: una pieza que cambia de temperatura cada pocos milímetros. Elegí la temperatura más baja que todavía da buena unión entre capas. Bajar 5 a 10 °C suele reducir mucho los hilos.</p></section>\n<section class=\"help\"><h2>3. Ajustá la retracción</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Tipo de extrusor</th><th scope=\"col\">Distancia de partida</th><th scope=\"col\">Velocidad</th></tr></thead><tbody><tr><th scope=\"row\">Directo (direct drive)</th><td>0,5 a 2 mm</td><td>30 a 45 mm/s</td></tr><tr><th scope=\"row\">Bowden</th><td>2 a 6 mm</td><td>30 a 50 mm/s</td></tr></tbody></table></div><p class=\"note\">Imprimí una prueba de retracción y cambiá una variable por vez. Una retracción excesiva puede trabar el filamento en el extrusor o generar huecos al reanudar la extrusión.</p></section>\n<section class=\"help\"><h2>4. Mejorá los recorridos</h2><ul><li>Activá la opción de evitar cruzar perímetros (combing o avoid crossing walls) para que los viajes queden dentro de la pieza.</li><li>Subí la velocidad de desplazamiento sin extruir.</li><li>Probá la función de limpieza (wipe) al final de cada perímetro.</li><li>Si tu laminador lo permite, ajustá pressure advance o linear advance: reduce el goteo al frenar.</li></ul></section>\n<section class=\"help\"><h2>PETG y TPU</h2><p>Estos materiales siempre hacen algunos hilos. En el TPU, usá retracciones cortas y lentas para que no se trabe en el extrusor. Los pelitos finos que quedan se eliminan pasando rápido una pistola de calor; no te detengas en un punto porque deformás la pieza.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento y guardarlo bien</a></li><li><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento</a></li><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir para cada pieza</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/decoracion/\">Decoración</a> · <a href=\"__SEARCH_HOME__categorias/miniaturas/\">Miniaturas</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/licencias-modelos-3d.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Licencias de modelos 3D: qué podés vender y qué no</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Licencias de modelos 3D: qué podés vender y qué no</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Que un archivo sea gratis no significa que puedas vender lo que imprimís con él. Cada modelo tiene una licencia que define si podés usarlo comercialmente, modificarlo y cómo tenés que citar al autor.</p>\n<section class=\"help\"><h2>Precio del archivo y permiso de venta son cosas distintas</h2><p>Un modelo gratis puede tener licencia no comercial, y un modelo pago puede prohibir vender impresiones. Antes de vender, revisá la licencia en la ficha del modelo, no solo si se descarga gratis o no.</p></section>\n<section class=\"help\"><h2>Las licencias Creative Commons más comunes</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Licencia</th><th scope=\"col\">¿Podés vender impresiones?</th><th scope=\"col\">¿Podés modificarlo?</th></tr></thead><tbody><tr><th scope=\"row\">CC0 o dominio público</th><td>Sí</td><td>Sí</td></tr><tr><th scope=\"row\">CC BY (atribución)</th><td>Sí, citando al autor</td><td>Sí</td></tr><tr><th scope=\"row\">CC BY-SA (compartir igual)</th><td>Sí, citando al autor</td><td>Sí, con la misma licencia</td></tr><tr><th scope=\"row\">CC BY-ND (sin derivadas)</th><td>Sí, citando al autor</td><td>No</td></tr><tr><th scope=\"row\">CC BY-NC (no comercial)</th><td>No</td><td>Sí, sin uso comercial</td></tr><tr><th scope=\"row\">CC BY-NC-SA y BY-NC-ND</th><td>No</td><td>Según la variante</td></tr></tbody></table></div><p class=\"note\">Resumen orientativo. El texto oficial de cada licencia está en <a href=\"https://creativecommons.org.ar/licencias/\">Creative Commons Argentina</a>.</p></section>\n<section class=\"help\"><h2>Licencias propias de cada plataforma</h2><p>Printables, MakerWorld, Cults3D y otras tienen licencias propias, como la \"Standard Digital File License\" o licencias comerciales que se compran aparte. No se interpretan como las Creative Commons: leé las condiciones en la ficha. En UtiliTools aparecen como \"Licencia a revisar\".</p></section>\n<section class=\"help\"><h2>Licencias comerciales y membresías</h2><p>Muchos diseñadores venden permisos comerciales: una licencia por modelo, un plan mensual en su Patreon o membresías de la plataforma. Si querés vender un modelo popular con licencia no comercial, escribile al autor: muchas veces lo autoriza o te ofrece una licencia.</p></section>\n<section class=\"help\"><h2>Marcas y personajes</h2><p>La licencia del archivo solo cubre el trabajo del diseñador. Si el modelo reproduce un personaje, un logo o una marca, esos derechos son de su titular aunque el archivo sea CC0. Vender figuras de personajes de películas, videojuegos o clubes de fútbol sin autorización expone a denuncias y a que te den de baja las publicaciones.</p></section>\n<section class=\"help\"><h2>Cómo citar al autor</h2><p>Cuando la licencia pide atribución, incluí en la publicación o en la etiqueta el nombre del modelo, el autor, la licencia y el enlace. Por ejemplo: \"Diseño: Maceta geométrica, de [nombre del autor], CC BY 4.0, [enlace al modelo]\".</p></section>\n<section class=\"help\"><h2>Diseños propios</h2><p>Lo más seguro para vender en volumen es diseñar tus propias piezas o remezclar modelos que lo permitan. Además, te diferencia de otros vendedores que imprimen los mismos archivos populares.</p></section>\n<section class=\"help\"><h2>Aclaración</h2><p>Esta guía es informativa y no reemplaza el asesoramiento legal. Ante dudas sobre un caso concreto, consultá con un abogado especializado en propiedad intelectual.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/vender-en-mercado-libre.html\">Cómo vender impresiones 3D en Mercado Libre</a></li><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D en Argentina</a></li><li><a href=\"/guias/costos-de-impresion.html\">Cómo calcular el costo real de una impresión 3D</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/juguetes/\">Juguetes</a> · <a href=\"__SEARCH_HOME__categorias/miniaturas/\">Miniaturas</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/categorias/gamer/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Gamer</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Gamer</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Accesorios gamer para imprimir en 3D</h1><p>Soportes para joysticks y auriculares, organizadores de juegos, grips y pasacables: el escritorio gamer es uno de los lugares donde más se usan piezas impresas. Son objetos funcionales, que se ven todos los días y que se pueden hacer a medida.</p><p>Muchos modelos están pensados para un control o una consola en particular. Antes de imprimir, confirmá que el diseño corresponde a tu modelo exacto: entre versiones de un mismo control cambian medidas y la posición de los botones.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=controller%20stand#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:controller stand--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=controller%20stand#catalogo\">Soportes para joysticks →</a><a href=\"/?q=headphone%20stand#catalogo\">Soportes para auriculares →</a><a href=\"/?q=game%20card%20holder#catalogo\">Organizadores de juegos →</a><a href=\"/?q=cable%20management#catalogo\">Pasacables →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Medí el control, los auriculares o la consola, y compará con las medidas del modelo.</li><li>Para soportes que cargan peso, como auriculares, usá más paredes y orientá la pieza para que las capas no trabajen separándose.</li><li>Agregá almohadillas de goma o fieltro en la base para que no raye el escritorio ni se deslice.</li><li>Los logos de consolas y videojuegos tienen dueño: no los vendas sin permiso.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PLA para soportes; PETG para grips y piezas que se flexionan</dd></div><div><dt>Altura de capa</dt><dd>0,16 a 0,20 mm</dd></div><div><dt>Relleno</dt><dd>15 a 25 %</dd></div><div><dt>Perímetros</dt><dd>3 o 4 en piezas que cargan peso</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/soportes.html\">Soportes fáciles de retirar →</a></li><li><a href=\"/guias/multicolor.html\">Multicolor con menos purga →</a></li><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/cocina/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Cocina</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Cocina</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Accesorios de cocina para imprimir en 3D</h1><p>Organizadores de cajones, soportes para esponjas, ganchos, clips para bolsas y cortantes de galletitas: la cocina tiene muchos objetos chicos que se resuelven bien con una impresora 3D.</p><p>Hay que tener cuidado con lo que toca alimentos. Las capas dejan rendijas donde se acumulan restos y bacterias, y ningún filamento común garantiza ser apto para contacto con alimentos una vez impreso. Para cortantes de galletitas de un solo uso puede alcanzar; para recipientes o utensilios de uso repetido, no.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=kitchen%20organizer#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:kitchen organizer--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=kitchen%20organizer#catalogo\">Organizadores de cocina →</a><a href=\"/?q=cookie%20cutter#catalogo\">Cortantes de galletitas →</a><a href=\"/?q=sponge%20holder#catalogo\">Soportes para esponja →</a><a href=\"/?q=bag%20clip#catalogo\">Clips para bolsas →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Cerca del calor, el PLA se deforma: usá PETG o ASA para piezas al lado de la hornalla o el horno.</li><li>No los laves en el lavavajillas: el agua caliente deforma el PLA y puede ablandar otros materiales.</li><li>Para piezas que van a estar mojadas, como soportes de esponja, agregá agujeros de drenaje.</li><li>Medí el cajón o la alacena por dentro antes de imprimir un organizador.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PETG para la mayoría de las piezas de cocina</dd></div><div><dt>Altura de capa</dt><dd>0,20 mm</dd></div><div><dt>Relleno</dt><dd>15 a 20 %</dd></div><div><dt>Paredes</dt><dd>3 o más para que no filtre el agua</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir →</a></li><li><a href=\"/guias/tpu-flexibles.html\">Cómo imprimir TPU y flexibles →</a></li><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/mascotas/\">Mascotas</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/mascotas/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Mascotas</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Mascotas</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Accesorios para mascotas para imprimir en 3D</h1><p>Soportes elevados para comederos, chapitas con el nombre, colgadores de correas y juguetes con premios: hay muchos accesorios para perros y gatos que se pueden imprimir y personalizar.</p><p>La seguridad es lo primero. Una mascota puede romper una pieza impresa al morderla y tragar los fragmentos, que suelen tener bordes filosos. Evitá imprimir juguetes para morder y elegí accesorios que no queden a su alcance sin supervisión.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=pet%20bowl%20stand#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:pet bowl stand--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=pet%20bowl%20stand#catalogo\">Soportes para comederos →</a><a href=\"/?q=pet%20tag#catalogo\">Chapitas de identificación →</a><a href=\"/?q=leash%20holder#catalogo\">Colgadores de correas →</a><a href=\"/?q=cat%20toy#catalogo\">Juguetes para gatos →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>No imprimas juguetes para morder: los fragmentos de plástico pueden lastimar a la mascota.</li><li>Para soportes de comedero, imprimí solo la base y usá un plato de acero o cerámica para la comida.</li><li>En chapitas de identificación, usá letras gruesas y una argolla metálica.</li><li>Redondeá o lijá los bordes de cualquier pieza que la mascota pueda tocar.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PETG, más tenaz y fácil de limpiar</dd></div><div><dt>Altura de capa</dt><dd>0,20 mm</dd></div><div><dt>Relleno</dt><dd>20 a 30 % para que no vuelque</dd></div><div><dt>Base</dt><dd>Ancha y con almohadillas antideslizantes</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir →</a></li><li><a href=\"/guias/tpu-flexibles.html\">Cómo imprimir TPU y flexibles →</a></li><li><a href=\"/guias/warping.html\">Warping: por qué se levanta la pieza →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/electronica/\">Electrónica</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/categorias/electronica/":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Electrónica</title><link rel=\"stylesheet\" href=\"/style.css\"></head>\n<body><header><div class=\"wrap nav\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap category-page\"><nav class=\"breadcrumb\" aria-label=\"Ruta de navegación\"><a href=\"__SEARCH_HOME__\">Inicio</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">Electrónica</span></nav><section class=\"category-hero\"><p class=\"eyebrow\">CATEGORÍA</p><h1>Electrónica: cajas y soportes para imprimir en 3D</h1><p>Gabinetes para Raspberry Pi y Arduino, soportes para placas, cajas de proyectos y organizadores de cables: la impresión 3D es ideal para terminar un proyecto electrónico con un acabado prolijo.</p><p>Muchos diseños son paramétricos: se ajustan las medidas antes de exportar el archivo. Si tu placa es una revisión distinta de la del modelo, verificá la posición de los conectores y de los agujeros de fijación.</p></section>\n<section class=\"category-models\"><div class=\"section-head\"><h2>Modelos populares</h2><a class=\"more\" href=\"/?q=raspberry%20pi%20case#catalogo\">Ver más en el buscador →</a></div><!--MODELOS:raspberry pi case--></section>\n<section class=\"category-related\"><h2>Búsquedas relacionadas</h2><div class=\"suggestions\"><a href=\"/?q=raspberry%20pi%20case#catalogo\">Gabinetes para Raspberry Pi →</a><a href=\"/?q=arduino%20case#catalogo\">Cajas para Arduino →</a><a href=\"/?q=electronics%20enclosure#catalogo\">Cajas de proyectos →</a><a href=\"/?q=cable%20organizer#catalogo\">Organizadores de cables →</a></div></section>\n<div class=\"category-columns\"><section><h2>Qué revisar antes de imprimir</h2><ul class=\"checklist\"><li>Dejá ventilación si la placa se calienta, y no encierres fuentes de alimentación sin aire.</li><li>Los agujeros para tornillos salen un poco más chicos: probá una pieza de prueba o usá insertos roscados térmicos.</li><li>El PLA se deforma cerca de reguladores o fuentes que levantan temperatura: usá PETG o ASA.</li><li>Revisá que los conectores queden alineados con las aberturas antes de imprimir la tapa.</li></ul></section><section><h2>Configuración de partida</h2><dl class=\"setup\"><div><dt>Material</dt><dd>PETG o ASA si hay calor; PLA para cajas sin carga térmica</dd></div><div><dt>Altura de capa</dt><dd>0,16 a 0,20 mm</dd></div><div><dt>Relleno</dt><dd>15 a 20 %</dd></div><div><dt>Holguras</dt><dd>0,2 a 0,3 mm para tapas y encastres</dd></div></dl><p class=\"note\">Son valores iniciales para una boquilla de 0,4 mm. Ajustalos con una prueba corta y con la ficha de tu filamento.</p></section></div>\n<section class=\"category-guides\"><h2>Guías relacionadas</h2><ul class=\"guide-links\"><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir →</a></li><li><a href=\"/guias/fidgets-y-holguras.html\">Holguras para fidgets y encastres →</a></li><li><a href=\"/guias/warping.html\">Warping: por qué se levanta la pieza →</a></li></ul></section>\n<section class=\"category-cta\"><h2>¿Cuánto cuesta imprimirlo?</h2><p>Cargá el G-code o los gramos y las horas del laminador y calculá el costo y el precio sugerido en pesos.</p><a class=\"button-lime\" href=\"/calculadora/\">Abrir la calculadora →</a></section>\n<aside data-ad-slot=\"category\" hidden aria-label=\"Publicidad\"></aside><section><h2>Otras categorías</h2><div class=\"categories\" aria-label=\"Otras categorías\"><a href=\"/categorias/juguetes/\">Juguetes</a><a href=\"/categorias/diy-taller/\">DIY y taller</a><a href=\"/categorias/decoracion/\">Decoración</a><a href=\"/categorias/organizacion/\">Organización</a><a href=\"/categorias/macetas/\">Macetas</a><a href=\"/categorias/miniaturas/\">Miniaturas</a><a href=\"/categorias/repuestos/\">Repuestos</a><a href=\"/categorias/cosplay/\">Cosplay</a><a href=\"/categorias/llaveros/\">Llaveros</a><a href=\"/categorias/gamer/\">Gamer</a><a href=\"/categorias/cocina/\">Cocina</a><a href=\"/categorias/mascotas/\">Mascotas</a></div></section></main>\n<footer class=\"wrap\"><strong>UtiliTools</strong><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a><span>Los archivos y sus licencias se gestionan en los sitios originales.</span></footer></body></html>\n","/herramientas/guias/soportes.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Soportes fáciles de retirar: cómo configurarlos</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Soportes fáciles de retirar: cómo configurarlos</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Los soportes sostienen las partes de la pieza que quedan en el aire. Bien configurados se retiran en segundos y casi no dejan marcas; mal configurados arruinan la superficie o quedan soldados a la pieza.</p>\n<section class=\"help\"><h2>Cuándo hacen falta</h2><p>Como regla general, una pared con una inclinación de hasta 45° respecto de la vertical se imprime sin soporte, porque cada capa se apoya parcialmente sobre la anterior. Los puentes cortos, entre dos apoyos, también suelen salir bien sin soporte. Más inclinación o voladizos largos sí lo necesitan.</p></section>\n<section class=\"help\"><h2>Antes de agregar soportes</h2><ul><li>Probá otra orientación: muchas piezas no necesitan soporte si se apoyan sobre otra cara.</li><li>Dividí la pieza en partes que se impriman planas y se peguen después.</li><li>Si diseñás, reemplazá voladizos por chaflanes de 45°.</li><li>Dejá las caras visibles lejos de los soportes.</li></ul></section>\n<section class=\"help\"><h2>Normales o en árbol</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Tipo</th><th scope=\"col\">Ventajas</th><th scope=\"col\">Conviene para</th></tr></thead><tbody><tr><th scope=\"row\">Normales (en grilla)</th><td>Rápidos de calcular, firmes</td><td>Superficies planas grandes, piezas técnicas</td></tr><tr><th scope=\"row\">En árbol u orgánicos</th><td>Menos material, tocan menos la pieza, se retiran mejor</td><td>Figuras, miniaturas, formas curvas</td></tr></tbody></table></div></section>\n<section class=\"help\"><h2>Los parámetros que importan</h2><ul><li><strong>Distancia Z superior:</strong> la separación entre el soporte y la pieza. Para empezar, una capa: 0,2 mm con capas de 0,2 mm en PLA; en PETG, un poco más, entre 0,24 y 0,3 mm.</li><li><strong>Distancia XY:</strong> la separación lateral; 0,6 a 0,8 mm evita que el soporte se pegue a las paredes.</li><li><strong>Capas de interfaz:</strong> dos o tres capas más densas entre el soporte y la pieza dan una superficie inferior más prolija.</li><li><strong>Solo sobre la cama:</strong> evita que aparezcan soportes apoyados sobre la propia pieza, que dejan marcas.</li><li><strong>Pintar soportes:</strong> la mayoría de los laminadores permite marcar dónde sí y dónde no generar soporte.</li></ul></section>\n<section class=\"help\"><h2>El truco del PETG</h2><p>El PETG se pega mucho a sus propios soportes. Si tenés una impresora multimaterial, imprimí solo la interfaz del soporte en PLA: el PLA y el PETG casi no se adhieren entre sí y el soporte sale limpio.</p></section>\n<section class=\"help\"><h2>Cómo retirarlos</h2><p>Esperá a que la pieza se enfríe. Usá una pinza de punta y un alicate de corte al ras, y empezá por los bordes. Las marcas que queden se emparejan con una lija fina o una pasada rápida de pistola de calor, sin detenerte en un punto.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta</a></li><li><a href=\"/guias/multicolor.html\">Impresión multicolor con menos purga</a></li><li><a href=\"/guias/boquillas.html\">Qué boquilla usar: tamaño y material</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/miniaturas/\">Miniaturas</a> · <a href=\"__SEARCH_HOME__categorias/cosplay/\">Cosplay</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/multicolor.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Impresión multicolor con menos purga</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Impresión multicolor con menos purga</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Imprimir en varios colores puede desperdiciar más filamento que el que lleva la pieza. Con algunas decisiones de diseño y de laminado se reduce mucho la purga, el tiempo y el costo.</p>\n<section class=\"help\"><h2>Tres formas de imprimir en colores</h2><ul><li><strong>Cambio por capa con pausa:</strong> la impresora se detiene en una altura y cambiás el filamento a mano. No genera purga y funciona en cualquier impresora; ideal para llaveros y carteles con texto en relieve.</li><li><strong>Multimaterial automático:</strong> sistemas como AMS, CFS o MMU cambian el filamento solos, capa por capa o dentro de la misma capa. Permiten diseños complejos, pero cada cambio purga material.</li><li><strong>Pintar después:</strong> imprimís en un solo color y pintás. Para figuras con mucho detalle suele dar mejor resultado.</li></ul></section>\n<section class=\"help\"><h2>Por qué se desperdicia tanto</h2><p>En cada cambio, el filamento anterior tiene que salir por completo de la boquilla antes de imprimir el nuevo color. Ese material va a una torre de purga o se expulsa por detrás. En una pieza chica con muchos cambios por capa, la purga puede pesar más que la pieza.</p></section>\n<section class=\"help\"><h2>Cómo reducir la purga</h2><ul><li>Concentrá los cambios de color en pocas capas: por ejemplo, un logo en relieve solo en la parte superior.</li><li>Ajustá el volumen de purga por combinación: pasar de oscuro a claro necesita más purga que de claro a oscuro.</li><li>Purgá dentro del relleno o de los soportes, si tu laminador lo permite: ese material queda oculto y no se tira.</li><li>Imprimí varias piezas en la misma placa: la purga de cada cambio se reparte entre todas.</li><li>Elegí colores que cubran bien: un blanco sobre negro necesita mucha más purga que un gris.</li></ul></section>\n<section class=\"help\"><h2>Diseñar pensando en los colores</h2><p>Separá el modelo en cuerpos por color y ubicá los detalles de color en capas horizontales cuando puedas. Un texto que sobresale 0,6 mm sobre una base plana se puede hacer con un solo cambio de filamento, sin multimaterial.</p></section>\n<section class=\"help\"><h2>Calculá el costo real</h2><p>Anotá los gramos de pieza y de purga que muestra el laminador y cargalos en la <a href=\"/calculadora/\">calculadora</a>. Para vender, el precio tiene que cubrir también el filamento que terminó en la torre de purga.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D en Argentina</a></li><li><a href=\"/guias/soportes.html\">Soportes fáciles de retirar: cómo configurarlos</a></li><li><a href=\"/guias/hilos-stringing.html\">Cómo eliminar los hilos (stringing) en impresión 3D</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/llaveros/\">Llaveros</a> · <a href=\"__SEARCH_HOME__categorias/decoracion/\">Decoración</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/tpu-flexibles.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Cómo imprimir TPU y filamentos flexibles</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Cómo imprimir TPU y filamentos flexibles</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">El TPU sirve para fundas, topes, juntas, ruedas y correas: piezas que se doblan y vuelven a su forma. Es más difícil de imprimir que el PLA, pero con velocidad baja y el filamento seco sale muy bien.</p>\n<section class=\"help\"><h2>La dureza importa</h2><p>Los flexibles se clasifican por dureza Shore. El más común es el 95A, bastante firme y el más fácil de imprimir. Los más blandos, como 85A, se doblan más pero tienden a enroscarse en el extrusor.</p></section>\n<section class=\"help\"><h2>Extrusor directo o bowden</h2><p>Con extrusor directo, el filamento recorre poco camino hasta la boquilla y se imprime mucho mejor. En un bowden, el TPU 95A se puede imprimir despacio; los más blandos, en general, no.</p></section>\n<section class=\"help\"><h2>Configuración de partida</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Parámetro</th><th scope=\"col\">Valor inicial</th></tr></thead><tbody><tr><th scope=\"row\">Boquilla</th><td>220 a 240 °C</td></tr><tr><th scope=\"row\">Cama</th><td>40 a 60 °C</td></tr><tr><th scope=\"row\">Velocidad</th><td>20 a 40 mm/s</td></tr><tr><th scope=\"row\">Retracción</th><td>Mínima o desactivada</td></tr><tr><th scope=\"row\">Ventilador de pieza</th><td>50 a 100 %</td></tr></tbody></table></div><p class=\"note\">Valores orientativos para TPU 95A. Si el filamento se enrosca en el extrusor, bajá más la velocidad.</p></section>\n<section class=\"help\"><h2>Cuidados</h2><ul><li>Secalo antes de imprimir: absorbe humedad y hace hilos y burbujas.</li><li>Se pega muy fuerte al PEI liso y al vidrio: usá una capa de lápiz adhesivo como separador.</li><li>La mayoría de los sistemas multimaterial automáticos no admite TPU: alimentalo desde una bobina externa.</li><li>Ajustá la tensión del extrusor según el fabricante: si aprieta demasiado, aplasta el filamento.</li></ul></section>\n<section class=\"help\"><h2>Más o menos flexible</h2><p>La flexibilidad no depende solo del material: menos paredes y menos relleno dan una pieza más blanda. Un relleno gyroid del 10 al 20 % se comprime de forma pareja en todas las direcciones.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/secar-filamento.html\">Cómo secar el filamento y guardarlo bien</a></li><li><a href=\"/guias/hilos-stringing.html\">Cómo eliminar los hilos (stringing) en impresión 3D</a></li><li><a href=\"/guias/pla-vs-petg.html\">PLA o PETG: cuál elegir para cada pieza</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/repuestos/\">Repuestos</a> · <a href=\"__SEARCH_HOME__categorias/mascotas/\">Mascotas</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/boquillas.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Qué boquilla usar: tamaño y material</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Qué boquilla usar: tamaño y material</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Cambiar la boquilla es una de las formas más baratas de cambiar lo que puede hacer tu impresora: más detalle, piezas más rápidas o materiales abrasivos.</p>\n<section class=\"help\"><h2>Tamaño</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Diámetro</th><th scope=\"col\">Para qué</th><th scope=\"col\">A tener en cuenta</th></tr></thead><tbody><tr><th scope=\"row\">0,2 mm</th><td>Miniaturas, texto chico, detalle fino</td><td>Muy lenta; se tapa con más facilidad</td></tr><tr><th scope=\"row\">0,4 mm</th><td>Uso general</td><td>La que viene de fábrica en casi todas las impresoras</td></tr><tr><th scope=\"row\">0,6 mm</th><td>Piezas funcionales más rápidas y resistentes</td><td>Menos detalle; capas más gruesas</td></tr><tr><th scope=\"row\">0,8 mm</th><td>Piezas grandes, floreros, prototipos rápidos</td><td>Escalonado visible</td></tr></tbody></table></div><p class=\"note\">Como referencia, el ancho de línea suele ir del 100 al 120 % del diámetro, y la altura de capa no debería superar el 75 % del diámetro.</p></section>\n<section class=\"help\"><h2>Material</h2><ul><li><strong>Latón:</strong> el estándar. Conduce muy bien el calor, pero se desgasta rápido con filamentos abrasivos.</li><li><strong>Acero endurecido:</strong> para filamentos con fibra de carbono o de vidrio, brillantina o los que brillan en la oscuridad. Conduce menos calor: subí 5 a 10 °C la temperatura.</li><li><strong>Boquillas de alto caudal:</strong> calientan mejor el filamento y permiten imprimir más rápido, si tu hotend las admite.</li></ul></section>\n<section class=\"help\"><h2>Señales de una boquilla gastada</h2><ul><li>Subextrusión o paredes más finas que antes, sin cambio de configuración.</li><li>Más hilos y gotas, o un agujero que se ve más grande y ovalado.</li><li>Medidas que empeoran en piezas que antes salían justas.</li></ul></section>\n<section class=\"help\"><h2>Cómo cambiarla</h2><p>Seguí el procedimiento del fabricante: muchas boquillas se ajustan en caliente y con un torque bajo. No fuerces la rosca. Después del cambio, repetí la calibración de primera capa y de caudal.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/mantenimiento.html\">Mantenimiento básico de la impresora 3D</a></li><li><a href=\"/guias/calibrar-filamento.html\">Cómo calibrar una bobina de filamento</a></li><li><a href=\"/guias/soportes.html\">Soportes fáciles de retirar: cómo configurarlos</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/miniaturas/\">Miniaturas</a> · <a href=\"__SEARCH_HOME__categorias/diy-taller/\">DIY y taller</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/herramientas/guias/mantenimiento.html":"<!doctype html>\n<html lang=\"es-AR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Mantenimiento básico de la impresora 3D</title><link rel=\"stylesheet\" href=\"/herramientas/site.css\"></head>\n<body><header class=\"site-header\"><div class=\"wrap header-inner\"><a href=\"__SEARCH_HOME__\" class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><nav aria-label=\"Principal\"><a href=\"__SEARCH_HOME__#catalogo\">Modelos</a><a href=\"/calculadora/\">Calculadora</a><a href=\"/perfiles/\">Perfiles</a><a href=\"/perfiles/#materiales\">Filamentos</a><a href=\"/guias/\">Guías</a></nav></div></header>\n<main class=\"wrap\"><article class=\"editorial\"><a href=\"/guias/\">← Volver a guías</a><h1>Mantenimiento básico de la impresora 3D</h1><p class=\"byline\">Actualizada el <time datetime=\"2026-11-17\">17 de noviembre de 2026</time> · UtiliTools</p><p class=\"intro\">Una impresora bien mantenida falla menos y dura más. La mayoría de las tareas llevan pocos minutos, y el desgaste ya lo podés sumar al costo de cada pieza en la calculadora.</p>\n<section class=\"help\"><h2>Rutina por frecuencia</h2><div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Cuándo</th><th scope=\"col\">Qué hacer</th></tr></thead><tbody><tr><th scope=\"row\">Cada impresión</th><td>Limpiar la placa y revisar que no queden restos en la boquilla</td></tr><tr><th scope=\"row\">Cada semana</th><td>Quitar el polvo, revisar los tubos de PTFE y limpiar el exterior de la boquilla en caliente</td></tr><tr><th scope=\"row\">Cada mes</th><td>Revisar tensión de correas, tornillos y ruedas; limpiar ventiladores; lubricar según el manual</td></tr><tr><th scope=\"row\">Según el uso</th><td>Cambiar boquilla, tubo PTFE y superficie de impresión cuando se gastan</td></tr></tbody></table></div></section>\n<section class=\"help\"><h2>Lubricación</h2><p>Usá el lubricante que indica el fabricante: grasa para rieles lineales y aceite liviano o grasa para varillas, según el modelo. Evitá el WD-40 como lubricante: es un desplazador de agua y solvente, y deja las piezas secas con el tiempo.</p></section>\n<section class=\"help\"><h2>Correas</h2><p>Una correa floja produce piezas con ondas y medidas incorrectas; una muy tensa gasta los rodamientos. Muchas impresoras traen una guía de tensión o la ajustan solas. Revisá también que no tengan dientes gastados.</p></section>\n<section class=\"help\"><h2>Atascos</h2><ul><li>Si el filamento no sale, calentá la boquilla y empujá a mano para ver si avanza.</li><li>Hacé un tirón en frío: calentás, empujás filamento, bajás la temperatura unos 90 °C y tirás con firmeza. Arrastra los restos del interior.</li><li>Si se repite, revisá el tubo PTFE y la boquilla.</li></ul></section>\n<section class=\"help\"><h2>Firmware y seguridad</h2><ul><li>Actualizá el firmware: suele traer correcciones de calibración y seguridad.</li><li>Revisá que los cables de la cama caliente y del cabezal no estén pelados ni flojos.</li><li>No dejes impresiones largas sin supervisión si la impresora no tiene detección de fallas térmicas.</li></ul></section>\n<section class=\"help\"><h2>Llevá un registro</h2><p>Anotá cuándo cambiaste cada repuesto y cuántas horas de impresión llevaba. Con eso podés calcular el desgaste por hora y cargarlo en la <a href=\"/calculadora/\">calculadora</a>.</p></section>\n<aside data-ad-slot=\"guide\" hidden aria-label=\"Publicidad\"></aside><section class=\"help related-guides\"><h2>Seguí leyendo</h2><ul><li><a href=\"/guias/boquillas.html\">Qué boquilla usar: tamaño y material</a></li><li><a href=\"/guias/primera-capa.html\">Cómo lograr una primera capa perfecta</a></li><li><a href=\"/guias/cuanto-cobrar-impresion-3d.html\">Cuánto cobrar una impresión 3D en Argentina</a></li></ul><p class=\"related-cats\">Modelos para imprimir: <a href=\"__SEARCH_HOME__categorias/diy-taller/\">DIY y taller</a> · <a href=\"__SEARCH_HOME__categorias/repuestos/\">Repuestos</a></p><p><a class=\"button primary\" href=\"/calculadora/\">Calcular el costo de una impresión →</a></p></section></article></main>\n<footer class=\"site-footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"__SEARCH_HOME__\"><span class=\"brand-mark\" aria-hidden=\"true\">U</span> UtiliTools</a><div><a href=\"__SEARCH_HOME__privacidad/\">Privacidad</a><a href=\"__SEARCH_HOME__acerca/\">Acerca de UtiliTools</a></div></div></footer></body></html>\n","/og/categorias/cocina.png":"","/og/categorias/cosplay.png":"","/og/categorias/decoracion.png":"","/og/categorias/diy-taller.png":"","/og/categorias/electronica.png":"","/og/categorias/gamer.png":"","/og/categorias/juguetes.png":"","/og/categorias/llaveros.png":"","/og/categorias/macetas.png":"","/og/categorias/mascotas.png":"","/og/categorias/miniaturas.png":"","/og/categorias/organizacion.png":"","/og/categorias/repuestos.png":"","/og/guias/boquillas.png":"","/og/guias/calibrar-filamento.png":"","/og/guias/costos-de-impresion.png":"","/og/guias/cuanto-cobrar-impresion-3d.png":"","/og/guias/fidgets-y-holguras.png":"","/og/guias/hilos-stringing.png":"","/og/guias/licencias-modelos-3d.png":"","/og/guias/mantenimiento.png":"","/og/guias/multicolor.png":"","/og/guias/pla-vs-petg.png":"","/og/guias/primera-capa.png":"","/og/guias/secar-filamento.png":"","/og/guias/soportes.png":"","/og/guias/tpu-flexibles.png":"","/og/guias/vender-en-mercado-libre.png":"","/og/guias/warping.png":""};
// Cambia con cada versión del sitio: se agrega a las URLs de CSS/JS para poder cachearlos mucho tiempo.
const assetVersion = createHash('sha1').update(JSON.stringify(assets)).digest('hex').slice(0, 10);
const binaryTypes = { webp: 'image/webp', jpg: 'image/jpeg', png: 'image/png', ico: 'image/x-icon' };
const binaryCache = new Map();
const cachePolicy = {
  html: 'public, max-age=0, must-revalidate, s-maxage=600, stale-while-revalidate=86400',
  versioned: 'public, max-age=31536000, immutable',
  static: 'public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800'
};
const printablesEndpoint = 'https://api.printables.com/graphql/';
const query = `query Models($q: String!, $ordering: SearchChoicesEnum, $offset: Int) {
  searchPrints2(query: $q, printType: print, limit: 48, offset: $offset, ordering: $ordering) {
    items { id name slug downloadCount license { name } filesType images { filePath } stls { name } }
  }
}`;

function imageUrl(path) {
  if (!path) return '';
  const url = new URL(path, 'https://media.printables.com/');
  if (url.origin !== 'https://media.printables.com') return '';
  if (url.pathname.includes('/thumbs/')) return url.href;
  const match = url.pathname.match(/^(.*)\/([^/]+)\.(jpg|jpeg|png|webp)$/i);
  if (!match) return url.href;
  url.pathname = match[1] + '/thumbs/inside/640x480/' + match[3].toLowerCase() + '/' + match[2] + '.webp';
  return url.href;
}

let printablesRetryAt = 0;

async function searchPrintables(term, top = false, page = 1) {
  if (Date.now() < printablesRetryAt) throw new Error('Rate limited');
  const response = await fetch(printablesEndpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json', accept: 'application/json' },
    body: JSON.stringify({ query, variables: { q: term, ordering: top ? "popular" : "best_match", offset: (page - 1) * 48 } }),
    signal: AbortSignal.timeout(8500)
  });
  if (response.status === 429) printablesRetryAt = Date.now() + 300_000;
  if (!response.ok) throw new Error('HTTP ' + response.status);
  const payload = await response.json();
  const items = payload.data?.searchPrints2?.items;
  if (!Array.isArray(items)) throw new Error(payload.errors?.[0]?.message ?? 'Missing items');
  return items.filter(item => item.id && item.name).map(item => {
    const formats = new Set((item.stls ?? []).map(file => file.name?.split('.').at(-1).toUpperCase())
      .filter(ext => ['STL', '3MF', 'OBJ', 'STEP'].includes(ext)));
    if (item.filesType === 'STL' && !formats.size) formats.add('STL');
    if (item.filesType === 'STEP') formats.add('STEP');
    return {
      title: item.name, repo: 'Printables', type: 'gratis', downloads: item.downloadCount, licenseName: item.license?.name ?? '', licenseStatus: classifyLicense(item.license?.name),
      url: 'https://www.printables.com/model/' + encodeURIComponent(item.id + (item.slug ? '-' + item.slug : '')),
      image: imageUrl(item.images?.find(image => image.filePath)?.filePath),
      formats: [...formats]
    };
  });
}

function classifyLicense(name) {
  const value=(name ?? '').toLowerCase();
  if (/non.?commercial|\bby-nc\b|private use|personal use/.test(value)) return 'personal';
  if (/public domain|\bcc0\b|commercial use|gnu|gpl/.test(value)) return 'commercial';
  if (/creative commons/.test(value) && /attribution/.test(value)) return 'commercial';
  return 'unknown';
}

const catalogUrls = [...assets['/app.js'].matchAll(/'(https:\/\/[^'\s]+)', '[^'\n]+'\]/g)].map(match => match[1]);

const thumbnailCache = new Map();
async function catalogThumbnail(index) {
  const url = catalogUrls[index];
  if (!url) return new Response(null, { status: 404 });
  const cached = thumbnailCache.get(index);
  if (cached && cached.expires > Date.now()) return Response.redirect(cached.url,302);
  try {
    const printId = url.match(/printables\.com\/model\/(\d+)/)?.[1];
    if (printId) {
      const response = await fetch(printablesEndpoint, {
        method:'POST', headers:{'content-type':'application/json'},
        body:JSON.stringify({query:'query Preview($id: ID!) { print(id: $id) { images { filePath } } }',variables:{id:printId}}),
        signal:AbortSignal.timeout(7000)
      });
      const payload = await response.json();
      const image = imageUrl(payload.data?.print?.images?.[0]?.filePath);
      if (image) {
        thumbnailCache.set(index,{url:image,expires:Date.now()+3600000});
        return new Response(null,{status:302,headers:{location:image,'cache-control':'public, max-age=3600'}});
      }
    }
    const response = await fetch(url, { signal: AbortSignal.timeout(7000) });
    if (!response.ok) return new Response(null, { status: 404 });
    let image = '';
    const handler = { element(element) { image ||= element.getAttribute('content') ?? ''; } };
    await new HTMLRewriter().on('meta[property="og:image"]', handler)
      .on('meta[name="twitter:image"]', handler).transform(response).text();
    if (!image) return new Response(null, { status: 404 });
    const resolved = new URL(image, response.url || url);
    if (resolved.protocol === 'https:') {
      return new Response(null, { status: 302, headers: { location: resolved.href, 'cache-control': 'private, max-age=86400' } });
    }
  } catch (error) {
    console.warn('Catalog image unavailable', index, error.message);
  }
  return new Response(null, { status: 404 });
}

const analyticsEvents = {
  page_view: [['channel',['search','social','referral','direct','internal']],
    ['category',['juguetes','diy-taller','decoracion','organizacion','macetas','miniaturas','repuestos','cosplay','llaveros','gamer','cocina','mascotas','electronica']]],
  model_opened:[], calculator_opened:[],
  search_completed:[['result',['found','empty','more','error']]],
  filter_changed:[['format',['STL','3MF','OBJ','STEP','all']],['price',['gratis','pago','all']],
    ['license',['commercial','personal','unknown','all']]],
  model_saved:[], collection_created:[], collection_model_saved:[], collection_link_copied:[],
  slicer_import:[['result',['complete','partial','error']],['slicer',['bambu','orca','creality','unknown']],['format',['gcode','3mf']]],
  quote_exported:[['method',['clipboard','text_file']]]
};
const analyticsHost = process.env.UTILITOOLS_POSTHOG_HOST;
const analyticsToken = process.env.UTILITOOLS_POSTHOG_TOKEN;
const analyticsEnabled = Boolean(analyticsToken && /^https:\/\/(us|eu)\.i\.posthog\.com$/.test(analyticsHost ?? ''));

async function analyticsCapture(request,url) {
  if (!analyticsEnabled) return new Response(null,{status:503});
  if (!['www.utilitools.com.ar','utilitools.com.ar','calculadora.utilitools.com.ar',
    'guias.utilitools.com.ar','perfiles.utilitools.com.ar'].includes(url.hostname) ||
    request.headers.get('origin') !== url.origin) return new Response(null,{status:403});
  let event;
  try {event=await request.json();} catch {return new Response(null,{status:400});}
  if (!event || !Object.hasOwn(analyticsEvents,event.event) ||
    typeof event.id!=='string' || !/^[a-f0-9-]{36}$/.test(event.id) ||
    !['home','calculadora','guias','perfiles','category','guide','other'].includes(event.page)) {
    return new Response(null,{status:400});
  }
  const properties={page:event.page,$process_person_profile:false,$geoip_disable:true};
  for(const [name,values] of analyticsEvents[event.event]) {
    if(values.includes(event[name])) properties[name]=event[name];
  }
  try {
    const response=await fetch(analyticsHost+'/capture/',{
      method:'POST',headers:{'content-type':'application/json'},
      body:JSON.stringify({api_key:analyticsToken,event:'utilitools_'+event.event,
        distinct_id:event.id,properties}),signal:AbortSignal.timeout(4000)
    });
    return new Response(null,{status:response.ok?204:502});
  } catch {return new Response(null,{status:502});}
}

// Pedidos de baja de modelos: se guardan como JSON en un Blob privado de Vercel.
const takedownReasons = ['autor', 'licencia', 'marca', 'otro'];
async function takedownRequest(request, url) {
  const back = status => Response.redirect(url.origin + '/acerca/?baja=' + status + '#bajas', 303);
  if (request.headers.get('origin') !== url.origin) return new Response(null, { status: 403 });
  let form;
  try { form = await request.json(); } catch { return back('error'); }
  const field = (name, max) => typeof form?.[name] === 'string' ? form[name].trim().slice(0, max) : '';
  if (field('web', 200)) return back('enviada'); // campo trampa: solo lo completan los bots
  const entry = {
    modelo: field('modelo', 500), motivo: field('motivo', 20), detalle: field('detalle', 1500),
    email: field('email', 200), creado: new Date().toISOString(), sitio: url.hostname
  };
  if (!entry.modelo || !takedownReasons.includes(entry.motivo) ||
    !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(entry.email)) return back('incompleto');
  if (!process.env.BLOB_READ_WRITE_TOKEN) return back('error');
  try {
    // La librería reintenta con espera si Blob falla: cortamos a los 8 s para no dejar al usuario esperando.
    const controller = new AbortController();
    let timer;
    const timeout = new Promise((_, reject) => { timer = setTimeout(() => { controller.abort(); reject(new Error('timeout')); }, 8000); });
    try {
      await Promise.race([put('bajas/' + entry.creado.slice(0, 10) + '-' + randomUUID() + '.json', JSON.stringify(entry, null, 2),
        { access: 'private', contentType: 'application/json', addRandomSuffix: false, abortSignal: controller.signal }), timeout]);
    } finally { clearTimeout(timer); }
    return back('enviada');
  } catch (error) {
    console.error('Takedown request not stored', error.message);
    return back('error');
  }
}

const takedownMessages = {
  enviada: 'Recibimos tu pedido. Lo revisamos y, si corresponde, quitamos el modelo del sitio.',
  incompleto: 'Faltan datos: completá el enlace o nombre del modelo, el motivo y un email válido.',
  error: 'No pudimos guardar el pedido. Probá de nuevo en unos minutos.'
};

const site = {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/api/medicion' && request.method === 'POST') return analyticsCapture(request,url);
    if (url.pathname === '/api/bajas' && request.method === 'POST') return takedownRequest(request,url);
    if (request.method !== 'GET') return new Response(null, { status: 405 });
    if (url.pathname === '/api/search') {
      const term = url.searchParams.get('q')?.trim() ?? '';
      if ((!term && url.searchParams.get('top') !== '1') || term.length > 100) return Response.json({ error: 'Consulta inválida' }, { status: 400 });
      const page = Math.min(100, Math.max(1, Number.parseInt(url.searchParams.get('page') ?? '1',10) || 1));
      const repo = url.searchParams.get('source');
      const price = url.searchParams.get('price');
      const sources = [];
      if ((!repo || repo === 'Printables') && price !== 'pago') sources.push(['Printables', searchPrintables(term, url.searchParams.get('top') === '1', page)]);
      const outcomes = await Promise.allSettled(sources.map(([, result]) => result));
      const models = [];
      const unavailable = [];
      outcomes.forEach((result, index) => {
        if (result.status === 'fulfilled') models.push(...result.value);
        else {
          unavailable.push(sources[index][0]);
          console.warn(sources[index][0] + ' search unavailable', result.reason.message);
        }
      });
      if (url.searchParams.get('top') === '1') models.sort((a,b)=>(b.downloads??0)-(a.downloads??0));
      const format = url.searchParams.get('format');
      const license = url.searchParams.get('license');
      const filtered = models.filter(model=>
        (!format || model.formats.includes(format)) &&
        (!license || model.licenseStatus === license));
      return Response.json({ models:filtered, unavailable, hasNext:page<100 && models.length===48 }, {
        headers:{'cache-control':'private, max-age=120'}
      });
    }
    const thumb = url.pathname.match(/^\/api\/thumbnail\/(\d{1,2})$/);
    if (thumb) return catalogThumbnail(Number(thumb[1]));
    return await serveSite(url);
  }
};

const domain = 'utilitools.com.ar';
const sections = {
  calculadora: ['Calculadora de impresión 3D en ARS', 'costos'],
  perfiles: ['Perfiles y filamentos para impresión 3D', 'perfiles'],
  guias: ['Guías de impresión 3D', 'tecnicas']
};

function sectionHost(hostname) {
  return Object.keys(sections).find(section => hostname === section + '.' + domain);
}

async function serveSite(url) {
  const hostSection = sectionHost(url.hostname);
  const crawler = crawlFile(url, hostSection);
  if (crawler) return crawler;
  const searchHome = hostSection ? 'https://www.' + domain + '/' : '/';
  const path = url.pathname;
  if (/^\/categorias\/[a-z-]+$/.test(path) && Object.hasOwn(categoryDetails,path+'/')) return Response.redirect(web+path+'/',308);
  const route = path.match(/^\/(calculadora|perfiles|guias)\/?$/)?.[1];
  let name = path;
  let section;

  if (route || (hostSection && path === '/')) {
    section = route ?? hostSection;
    name = '/herramientas/index.html';
  } else if (path === '/herramientas' || path === '/herramientas/') {
    name = '/herramientas/index.html';
  } else if (path.startsWith('/guias/')) {
    name = '/herramientas' + path;
  } else if (path === '/' || path === '/index.html') {
    name = '/index.html';
  }

  let status = 200;
  if (!Object.hasOwn(assets, name)) {
    name = '/404.html';
    section = undefined;
    status = 404;
  }
  const extension = name.endsWith('/') ? 'html' : name.split('.').at(-1);
  const types = { html: 'text/html; charset=utf-8', css: 'text/css; charset=utf-8',
    js: 'text/javascript; charset=utf-8', svg: 'image/svg+xml', ...binaryTypes };
  let body = assets[name];
  if (Object.hasOwn(binaryTypes, extension)) {
    if (!binaryCache.has(name)) binaryCache.set(name, Buffer.from(body, 'base64'));
    body = binaryCache.get(name);
  } else if (extension === 'html') {
    body = body.replaceAll('__SEARCH_HOME__', searchHome);
    if (section) {
      const [title, anchor] = sections[section];
      body = body.replace(/<title>[^<]*<\/title>/, '<title>' + title + ' | UtiliTools 3D</title>')
        .replace('<body id="inicio">', '<body id="inicio" data-tool="' + section + '">')
        .replace('href="#perfiles">Ir al buscador de perfiles', 'href="#' + anchor + '">Ir a la herramienta')
        .replace(/(<section class="hero">[\s\S]*?)<h1>([\s\S]*?)<\/h1>/, '$1<p class="hero-title">$2</p>');
      const sectionHeading = new RegExp('(id="' + anchor + '"[^>]*>[\\s\\S]*?)<h2([^>]*)>(.*?)</h2>');
      body = body.replace(sectionHeading, '$1<h1$2>$3</h1>');
    }
    if (hostSection || url.hostname === 'www.' + domain) {
      // /calculadora/ y /perfiles/#x pasan a la raíz de su subdominio; /guias/x.html conserva la ruta.
      for (const section of Object.keys(sections)) {
        body = body.replace(new RegExp('href="/' + section + '/([^"]*)"', 'g'), (match, rest) =>
          'href="https://' + section + '.' + domain + '/' + (rest === '' || rest.startsWith('#') ? rest : section + '/' + rest) + '"');
      }
    }
  }
  let degraded = false;
  if (name === '/acerca/' && Object.hasOwn(takedownMessages, url.searchParams.get('baja') ?? '')) {
    const status = url.searchParams.get('baja');
    body = body.replace('<!--BAJA-ESTADO-->', '<p class="form-status ' + status + '" role="status">' + takedownMessages[status] + '</p>');
  }
  if (extension === 'html' && body.includes('<!--MODELOS:')) {
    const rendered = await categoryModels(body, name);
    body = rendered.body;
    degraded = rendered.degraded;
  }
  if (extension === 'html') {
    body = seoHtml(body, name, section);
    body = body.replace(/\b(href|src)="((?:\/|\.\.\/)[^"?#:]+\.(?:css|js))"/g, '$1="$2?v=' + assetVersion + '"');
    if(analyticsEnabled) body=body.replace('</body>',
      '<div style="max-width:1100px;margin:1rem auto;padding:0 1rem;font-size:.9rem"><label><input id="analytics-consent" type="checkbox"> Permitir estadísticas de uso</label> · <a href="https://www.utilitools.com.ar/privacidad/">Privacidad</a></div><script src="/utilitools-analytics.js" defer></script></body>');
  }
  const cacheControl = status !== 200 ? 'public, max-age=0, s-maxage=300'
    : degraded ? 'public, max-age=0, s-maxage=60'
    : extension === 'html' ? cachePolicy.html
    : url.searchParams.get('v') === assetVersion ? cachePolicy.versioned
    : cachePolicy.static;
  return new Response(body, {
    status,
    headers: { 'content-type': types[extension], 'cache-control': cacheControl }
  });
}


const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const licenseLabels = { commercial: 'Uso comercial', personal: 'No comercial', unknown: 'Licencia a revisar' };

// Completa <!--MODELOS:consulta--> con los modelos más descargados de Printables.
// Si la fuente no responde a tiempo, deja un enlace al buscador y se cachea menos.
async function categoryModels(body, name) {
  const marker = body.match(/<!--MODELOS:([^>]{1,80})-->/);
  const query = marker[1].trim();
  const searchLink = '/?q=' + encodeURIComponent(query) + '#catalogo';
  let models = [];
  try {
    const timeout = new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 4000));
    models = (await Promise.race([searchPrintables(query, true, 1), timeout]))
      .filter(model => model.image && !/\.gif$/i.test(model.image))
      .sort((a, b) => (b.downloads ?? 0) - (a.downloads ?? 0))
      .slice(0, 12);
  } catch (error) {
    console.warn('Category models unavailable', name, error.message);
  }
  if (!models.length) {
    return { degraded: true, body: body.replace(marker[0],
      '<p class="models-fallback">No pudimos cargar los modelos en este momento. <a href="' + searchLink + '">Buscalos en el buscador →</a></p>') };
  }
  const cards = models.map(model => '<a class="model-card" href="' + escapeHtml(model.url) + '" target="_blank" rel="noopener noreferrer">' +
    '<img src="' + escapeHtml(model.image) + '" alt="' + escapeHtml(model.title) + '" width="640" height="480" loading="lazy" decoding="async">' +
    '<div><strong>' + escapeHtml(model.title) + '</strong><small><span>' + escapeHtml(model.repo) +
    (model.downloads ? ' · ' + Number(model.downloads).toLocaleString('es-AR') + ' descargas' : '') + '</span>' +
    '<span class="lic ' + model.licenseStatus + '">' + licenseLabels[model.licenseStatus] + '</span></small></div></a>').join('');
  const itemList = { '@context': 'https://schema.org', '@type': 'ItemList', itemListElement:
    models.map((model, index) => ({ '@type': 'ListItem', position: index + 1, url: model.url, name: model.title })) };
  return { degraded: false, body: body.replace(marker[0], '<div class="model-grid">' + cards + '</div>' +
    '<script type="application/ld+json">' + JSON.stringify(itemList).replace(/</g, '\\u003c') + '</script>') };
}

